  nameEl.className = 'c-chatlist-item__name';
  nameEl.textContent = name || address;
  content.append(nameEl, createExcerpt({ ...excerpt, strings }));
  el.append(content);

  const right = document.createElement('span');
  right.className = 'c-chatlist-item__right';
