/* ---- src/components/lazy-history.js ---- */
/**
 * c-history — LAZY history pagination (DECISIONS #86: no "load more" button —
 * nearing the top auto-fires `ixian:loadmore`, a spinner row shows, and the
 * scroll anchor is preserved when older rows prepend).
 *
 * attachLazyHistory(box, { onLoadMore, threshold = 160, strings })
 *   box        — the scrolling message container (role=log)
 *   onLoadMore — shell hook: fire ixian:loadmore, PREPEND the older rows,
 *                then resolve. Resolve `false` when history is exhausted
 *                (detaches — no further loads).
 *   Re-entrancy guarded; scroll restored so the previously-visible message
 *   stays put (scrollTop += height delta).
 * Returns { setDone() } — shell can end pagination early (e.g. chat cleared).
 */


function attachLazyHistory(box, { onLoadMore, threshold = 160, strings = getStrings() } = {}) {
  let loading = false;
  let done = false;

  const spinner = () => {
    const row = document.createElement('div');
    row.className = 'c-history-loading';
    row.setAttribute('role', 'status');
    row.setAttribute('aria-label', strings.loadingHistory || 'Loading earlier messages');
    const sp = document.createElement('span');
    sp.className = 'c-history-loading__spinner';
    sp.setAttribute('aria-hidden', 'true');
    row.append(sp);
    return row;
  };

  const check = () => {
    if (loading || done || !onLoadMore) return;
    if (box.scrollTop > threshold) return;
    loading = true;
    const h0 = box.scrollHeight; // anchor BEFORE spinner + new rows
    const sp = spinner();
    box.prepend(sp);
    Promise.resolve(onLoadMore()).then((result) => {
      sp.remove();
      // keep the previously-visible message in place after the prepend
      box.scrollTop += box.scrollHeight - h0;
      if (result === false) {
        done = true;
        box.removeEventListener('scroll', check);
      }
      loading = false;
      // content may still sit above the threshold (short pages) — re-check
      if (!done) check();
    }).catch(() => {
      sp.remove();
      loading = false; // failed page loads stay retryable on the next scroll
    });
  };

  box.addEventListener('scroll', check, { passive: true });
  return {
    setDone() {
      done = true;
      box.removeEventListener('scroll', check);
    },
  };
}

/* ---- src/components/attach-sheet.js ---- */
/**
 * c-attach — composer ⊕ attach sheet (#87①, Damir interview 2026-07-03):
 * TILE GRID on c-sheet (creation verbs scan better as tiles; still the same
 * overlay stack). Bridge-real actions: file / pay / request / app invite.
 * Photo + GIF are DESIGNED-IN but FEATURE-FLAGGED (`media: false`) until the
 * BE image standard lands (#81) — the #64 voice-flag precedent.
 *
 * openAttachSheet({ host, media = false, apps = true, payments = true,
 *                   onAction, strings }) → sheet
 *   onAction(id) — 'file' | 'photo' | 'gif' | 'pay' | 'request' | 'app'
 *   (shell routes: sendfile / sendmedia / payment intent / app invite)
 *   media    — #81 flag: reveals Photo + GIF (BE image standard).
 *   apps     — gate the App-invite tile: no single chat-invite verb exists on
 *              every host (SingleChatPage has none), so the shell can hide it.
 *   payments — gate Pay + Request: 1:1 only (C# rejects them in groups/bots).
 */




const ATTACH_ACTIONS = [
  { id: 'file', glyph: 'file-isr', label: 'Send file', key: 'sendFile' },
  { id: 'photo', glyph: 'photo', label: 'Photo', key: 'photo', flag: 'media' },
  { id: 'gif', glyph: 'gif', label: 'GIF', key: 'gif', flag: 'media' },
  { id: 'pay', glyph: 'arrow-up-right', label: 'Send payment', key: 'sendPayment', flag: 'payments' },
  { id: 'request', glyph: 'arrow-down-left', label: 'Request payment', key: 'requestPayment', flag: 'payments' },
  { id: 'app', glyph: 'rocket', label: 'App invite', key: 'appInvite', flag: 'apps' },
];

function openAttachSheet({ host, media = false, apps = true, payments = true, onAction, strings = getStrings() } = {}) {
  const grid = document.createElement('div');
  grid.className = 'c-attach';
  const enabled = { media, apps, payments };

  for (const a of ATTACH_ACTIONS) {
    if (a.flag && !enabled[a.flag]) continue; // #81 media flag / apps gate (voice-flag precedent #64)
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = 'c-attach__tile';
    const med = document.createElement('span');
    med.className = 'c-attach__medallion';
    med.setAttribute('aria-hidden', 'true');
    med.append(icon(a.glyph, { size: 22 }));
    const label = document.createElement('span');
    label.className = 'c-attach__label';
    label.textContent = strings[a.key] || a.label;
    tile.append(med, label);
    tile.addEventListener('click', () => {
      closeSheet(sheet);
      if (onAction) onAction(a.id);
    });
    grid.append(tile);
  }

  const sheet = createSheet({ title: strings.attachTitle || 'Share', content: grid, host, strings });
  openSheet(sheet);
  return sheet;
}

/* ---- src/components/channel-sheet.js ---- */
/**
 * c-channels — bot-chat channel selector sheet (#86 bot surface). Bot chat =
 * a big group chat (Damir): the topbar identity is TAPPABLE (createTopbar
 * onIdentity) and opens this sheet; picking a channel re-renders the
 * conversation (shell duty — bridge setSelectedChannel).
 * Bridge: addChannelToSelector / setSelectedChannel / setChannelSelectorStatus
 * — the shell aggregates those into the `channels` list passed at open.
 *
 * openChannelSheet({ host, channels: [{ id, name, status, unread, selected }],
 *                    onSelect, strings }) → sheet
 */





function openChannelSheet({ host, channels = [], onSelect, strings = getStrings() } = {}) {
  const list = document.createElement('div');
  list.className = 'c-channels';
  // freeze audit: NO list/listitem roles — role=listitem on a <button>
  // replaces its button semantics for SRs (a column of buttons in a dialog
  // needs no list wrapper)

  for (const ch of channels) {
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'c-channels__row';
    if (ch.selected) row.setAttribute('aria-current', 'true');

    const hash = document.createElement('span');
    hash.className = 'c-channels__hash';
    hash.setAttribute('aria-hidden', 'true');
    hash.textContent = '#';
    row.append(hash);

    const info = document.createElement('span');
    info.className = 'c-channels__info';
    const name = document.createElement('span');
    name.className = 'c-channels__name';
    name.textContent = ch.name || '';
    info.append(name);
    if (ch.status) {
      const st = document.createElement('span');
      st.className = 'c-channels__status';
      st.textContent = ch.status; // bridge setChannelSelectorStatus (C#-composed)
      info.append(st);
    }
    row.append(info);

    if (ch.unread) row.append(createIndicator({ count: ch.unread, strings }));
    if (ch.selected) {
      const check = icon('check', { size: 18 });
      check.classList.add('c-channels__check');
      row.append(check);
    }

    row.addEventListener('click', () => {
      closeSheet(sheet);
      if (onSelect) onSelect(ch.id);
    });
    list.append(row);
  }

  const sheet = createSheet({ title: strings.channels || 'Channels', content: list, host, strings });
  openSheet(sheet);
  return sheet;
}

/* ---- src/components/member-sheet.js ---- */
/**
 * c-member — group member identity sheet (#99, Damir-approved round 8).
 * Opened by tapping a sender label or its avatar in group/bot chats: the
 * nickname is user-set and spoofable — the ADDRESS is the truth, so it shows
 * FULL and copyable, plus the contact-request path (normal/bot groups).
 * BLIND groups render the hidden-identity state instead (no address, no
 * request) — bridge must flag blindness per chat (BE question, #99).
 *
 * openMemberSheet({ host, member: { name, address, avatar }, blind = false,
 *                   relation = 'none' | 'pending' | 'contact',  // shell knows
 *                   onRequest,        // 'none' → "Send contact request"
 *                   onMessage,        // 'contact' → "Message" (open 1:1)
 *                   onPay, onRequestPayment, // 'contact' ONLY (round 10):
 *                                     // payment affordances stay behind the
 *                                     // contact relationship — pointing money
 *                                     // UI at unverified strangers = scam bait
 *                   onViewContact,    // 'contact': identity block tappable →
 *                                     // full contact page (shell nav)
 *                   strings }) → sheet
 * relation states (Damir sanity check): none → request button · pending →
 * "Request sent" badge (no button) · contact → "In your contacts" badge +
 * Message + Pay|Request row + tappable identity.
 */







function openMemberSheet({
  host,
  member = {},
  blind = false,
  relation = 'none',
  onRequest,
  onMessage,
  onPay,
  onRequestPayment,
  onViewContact,
  actions = [],     // #141 chat-info: capability-injected rows (admin kick/ban) —
                    // [{ label, glyph, destructive, onClick }]; the CALLER owns
                    // any confirm flow, the sheet just closes itself first
  strings = getStrings(),
} = {}) {
  const content = document.createElement('div');
  content.className = 'c-member';

  if (blind) {
    const med = document.createElement('span');
    med.className = 'c-member__blind-medallion';
    med.setAttribute('aria-hidden', 'true');
    med.append(icon('eye-off', { size: 22 }));
    const t = document.createElement('span');
    t.className = 'c-member__blind-title';
    t.textContent = strings.blindTitle || 'Identities are hidden in this group';
    const sub = document.createElement('span');
    sub.className = 'c-member__blind-sub';
    sub.textContent = strings.blindSub ||
      'Members of a blind group can’t be viewed or added to contacts.';
    content.append(med, t, sub);
  } else {
    // identity block — for CONTACTS it's a button → full contact page
    // (round 10; the page itself lands with the contacts shell)
    const canView = relation === 'contact' && !!onViewContact;
    const id = document.createElement(canView ? 'button' : 'div');
    id.className = 'c-member__id';
    if (canView) {
      id.type = 'button';
      id.addEventListener('click', () => { closeSheet(sheet); onViewContact(member); });
    }
    id.append(createAvatar({
      src: member.avatar, name: member.name, address: member.address, size: 48,
    }));
    const nameRow = document.createElement('span');
    nameRow.className = 'c-member__name';
    nameRow.textContent = member.name || member.address || '';
    if (canView) {
      const chev = icon('chevron-right', { size: 18 });
      chev.classList.add('c-member__chevron');
      nameRow.append(chev); // affordance: identity leads somewhere
    }
    id.append(nameRow);
    content.append(id);

    if (member.address) {
      const label = document.createElement('span');
      label.className = 'c-member__addr-label';
      label.textContent = strings.ixianAddress || 'Ixian address';
      const addrRow = document.createElement('div');
      addrRow.className = 'c-member__addr';
      const addr = document.createElement('span');
      addr.className = 'c-member__addr-text u-tabular';
      addr.textContent = member.address;
      const copy = document.createElement('button');
      copy.type = 'button';
      copy.className = 'c-member__copy';
      copy.setAttribute('aria-label', strings.copyAddress || 'Copy address');
      copy.append(icon('copy', { size: 18 }));
      copy.addEventListener('click', () => {
        if (navigator.clipboard) navigator.clipboard.writeText(member.address).catch(() => {});
        copy.textContent = '';
        copy.append(icon('check', { size: 18 })); // brief confirmation morph
        copy.setAttribute('aria-label', strings.copied || 'Copied'); // SRs hear the confirm too (freeze audit)
        setTimeout(() => {
          copy.textContent = '';
          copy.append(icon('copy', { size: 18 }));
          copy.setAttribute('aria-label', strings.copyAddress || 'Copy address');
        }, 1400);
      });
      addrRow.append(addr, copy);
      content.append(label, addrRow);
    }

    // relation-aware footer (Damir sanity check): never offer a request to
    // someone who's already a contact or already asked
    if (relation === 'contact') {
      const badge = createBadge({
        type: 'success', weight: 'tonal',
        label: strings.inContacts || 'In your contacts', icon: 'check',
      });
      badge.classList.add('c-member__relation');
      content.append(badge);
      if (onMessage) {
        const msg = createButton({
          label: strings.message || 'Message',
          type: 'fill', size: 44,
          icon: icon('messages', { size: 18 }),
          onClick: () => { closeSheet(sheet); onMessage(member); },
        });
        msg.dataset.width = 'full';
        msg.classList.add('c-member__request');
        content.append(msg);
      }
      // payment pair — CONTACTS ONLY (round 10 guard rail)
      if (onPay || onRequestPayment) {
        const payRow = document.createElement('div');
        payRow.className = 'c-member__payrow';
        if (onPay) payRow.append(createButton({
          label: strings.sendPayment || 'Pay', type: 'outline', size: 44,
          icon: icon('arrow-up-right', { size: 18 }),
          onClick: () => { closeSheet(sheet); onPay(member); },
        }));
        if (onRequestPayment) payRow.append(createButton({
          label: strings.requestPayment || 'Request', type: 'outline', size: 44,
          icon: icon('arrow-down-left', { size: 18 }),
          onClick: () => { closeSheet(sheet); onRequestPayment(member); },
        }));
        content.append(payRow);
      }
    } else if (relation === 'pending') {
      const badge = createBadge({
        type: 'info', weight: 'tonal',
        label: strings.requestSent || 'Request sent', icon: 'clock-hour-10',
      });
      badge.classList.add('c-member__relation');
      content.append(badge);
    } else if (onRequest) {
      const req = createButton({
        label: strings.sendContactRequest || 'Send contact request',
        type: 'fill', size: 44,
        icon: icon('heart-handshake', { size: 18 }),
        onClick: (e) => {
          // state-changing → latch (r2 guard family); shell/bridge confirms
          if (e.currentTarget.dataset.acted !== undefined) return;
          e.currentTarget.dataset.acted = '';
          e.currentTarget.disabled = true;
          closeSheet(sheet);
          onRequest(member);
        },
      });
      req.dataset.width = 'full';
      req.classList.add('c-member__request');
      content.append(req);
    }
  }

  // capability-injected actions (#141) — rendered LAST in both branches
  // (an admin can still act on a blind-group member; the model has the
  // address even when the UI hides it). Sheet closes BEFORE the callback so
  // a caller's confirm modal never stacks under the sheet scrim.
  if (actions.length) {
    const actRow = document.createElement('div');
    actRow.className = 'c-member__actions';
    let acted = false;   // one latch across the row (#141 audit m8): a double-
                         // click must not fire two actions once the sheet closes
    for (const a of actions) {
      actRow.append(createButton({
        label: a.label, type: 'outline', size: 44,
        intent: a.destructive ? 'destructive' : 'default',
        icon: a.glyph ? icon(a.glyph, { size: 18 }) : null,
        onClick: () => {
          if (acted) return;
          acted = true;
          closeSheet(sheet);
          if (a.onClick) a.onClick(member);
        },
      }));
    }
    content.append(actRow);
  }

  const sheet = createSheet({
    content, host, strings,
    title: '', // content carries the identity — a title would duplicate the name
  });
  sheet.setAttribute('aria-label', strings.memberDetails || 'Member details');
  openSheet(sheet);
  return sheet;
}

/* ---- src/components/media-viewer.js ---- */
/**
 * c-mviewer — full-screen media viewer (#86 last v1 gap): the c-mbubble
 * onOpen target. V1 = fit-to-screen + close (+ optional Save); pinch/zoom is
 * post-v1 (#86 note). Rides the overlay stack (#56): Esc, ✕ and
 * swipe-to-dismiss close it (the viewer covers the scrim, so scrim-tap is
 * unreachable — freeze audit); focus contained, back-hook via
 * dismissTopOverlay.
 *
 * openMediaViewer({ host, src, alt, kind, onSave, strings }) → el
 *   onSave — shell hook (P2P: saving = local file op via bridge); omitted =
 *   no Save button.
 */




function openMediaViewer({
  host,
  src = '',
  alt = '',
  kind = 'image',
  onSave,
  strings = getStrings(),
} = {}) {
  const el = document.createElement('section');
  el.className = 'c-mviewer';
  el.setAttribute('role', 'dialog');
  el.setAttribute('aria-modal', 'true');
  el.setAttribute('aria-label', alt || (kind === 'gif' ? 'GIF' : (strings.image || 'Image')));
  el.tabIndex = -1;

  const bar = document.createElement('div');
  bar.className = 'c-mviewer__bar';
  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'c-mviewer__btn';
  close.setAttribute('aria-label', strings.close || 'Close');
  close.append(icon('x', { size: 22 }));
  close.addEventListener('click', () => dismissOverlay(el));
  bar.append(close);
  if (alt) {
    const cap = document.createElement('span');
    cap.className = 'c-mviewer__caption';
    cap.textContent = alt;
    bar.append(cap);
  }
  if (onSave) {
    const save = document.createElement('button');
    save.type = 'button';
    save.className = 'c-mviewer__btn';
    save.setAttribute('aria-label', strings.save || 'Save');
    save.append(icon('download', { size: 22 }));
    save.addEventListener('click', () => onSave());
    bar.append(save);
  } else {
    const spacer = document.createElement('span');
    spacer.className = 'c-mviewer__spacer';
    spacer.setAttribute('aria-hidden', 'true');
    bar.append(spacer);
  }
  el.append(bar);

  const stage = document.createElement('div');
  stage.className = 'c-mviewer__stage';
  const img = document.createElement('img');
  img.className = 'c-mviewer__img';
  img.src = src;
  img.alt = ''; // the dialog carries the accessible name
  img.draggable = false; // mouse-drag fix: native image drag hijacked the pointer stream
  stage.append(img);
  el.append(stage);
  stage.addEventListener('dragstart', (e) => e.preventDefault());

  // swipe-to-dismiss (Damir: intuitive close, no hunting the ✕): vertical
  // drag EITHER direction — the image rides the finger and the viewer fades;
  // past the threshold on release = dismiss, under it = spring back.
  const DISMISS_PX = 80;
  let startY = 0;
  let dragY = null;
  stage.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    startY = e.clientY;
    dragY = 0;
    stage.setPointerCapture(e.pointerId);
    img.style.transition = 'none'; // finger-follow must not lag
  });
  stage.addEventListener('pointermove', (e) => {
    if (dragY === null) return;
    dragY = e.clientY - startY;
    img.style.transform = 'translateY(' + dragY + 'px)';
    el.style.opacity = String(Math.max(0.4, 1 - Math.abs(dragY) / 320));
  });
  const endDrag = () => {
    if (dragY === null) return;
    const past = Math.abs(dragY) > DISMISS_PX;
    img.style.transition = ''; // spring-back transition returns (css)
    if (past) {
      dismissOverlay(el);
    } else {
      img.style.transform = '';
      el.style.opacity = '';
    }
    dragY = null;
  };
  stage.addEventListener('pointerup', endDrag);
  stage.addEventListener('pointercancel', endDrag);

  setOverlayOpts(el, { host, lightDismiss: true, escDismiss: true });
  openOverlay(el);
  return el;
}

/* ---- src/components/call-overlay.js ---- */
/**
 * c-callin — incoming voice call overlay (#86 last v1 gap; Damir: accept /
 * decline / ignore). Rides the overlay stack; renders at the call layer
 * (z-60, above modals — an incoming call outranks everything but toasts).
 * Ongoing-call UI stays c-callbar (#57); Accept typically chains into
 * showCallBar (shell duty). All three actions latch (state-changing).
 *
 * showIncomingCall({ host, caller: { name, address, avatar }, sub,
 *                    onAccept, onDecline, onIgnore, strings }) → el
 *   sub — line under the name (default "Incoming voice call…")
 *   Ignore = overlay dismisses, ringing continues muted (shell duty);
 *   Esc / scrim tap route to onIgnore too (safe dismiss = quietest action).
 * hideIncomingCall(el) — bridge hook (peer hung up before an answer).
 */





function showIncomingCall({
  host,
  caller = {},
  sub = '',
  onAccept,
  onDecline,
  onIgnore,
  strings = getStrings(),
} = {}) {
  const el = document.createElement('section');
  el.className = 'c-callin';
  el.setAttribute('role', 'alertdialog');
  el.setAttribute('aria-modal', 'true');
  el.setAttribute('aria-label',
    (strings.incomingCall || 'Incoming voice call') + (caller.name ? ' — ' + caller.name : ''));
  el.tabIndex = -1;

  const id = document.createElement('div');
  id.className = 'c-callin__identity';
  const avatarWrap = document.createElement('span');
  avatarWrap.className = 'c-callin__avatar'; // pulse ring lives here
  avatarWrap.append(createAvatar({
    src: caller.avatar, name: caller.name, address: caller.address, size: 48,
  }));
  const name = document.createElement('span');
  name.className = 'c-callin__name';
  name.textContent = caller.name || caller.address || '';
  const subEl = document.createElement('span');
  subEl.className = 'c-callin__sub';
  subEl.textContent = sub || strings.incomingCall || 'Incoming voice call';
  id.append(avatarWrap, name, subEl);
  el.append(id);

  let acted = false; // one outcome per ring — all three actions latch
  const act = (fn) => () => {
    if (acted) return;
    acted = true;
    dismissOverlay(el);
    if (fn) fn();
  };

  const actions = document.createElement('div');
  actions.className = 'c-callin__actions';
  const action = (kind, glyph, label, fn) => {
    const wrap = document.createElement('span');
    wrap.className = 'c-callin__action';
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'c-callin__circle';
    b.dataset.kind = kind;
    b.setAttribute('aria-label', label);
    b.append(icon(glyph, { size: 24 }));
    b.addEventListener('click', act(fn));
    const l = document.createElement('span');
    l.className = 'c-callin__label';
    l.setAttribute('aria-hidden', 'true');
    l.textContent = label;
    wrap.append(b, l);
    actions.append(wrap);
  };
  action('decline', 'phone-end', strings.decline || 'Decline', onDecline);
  action('ignore', 'bell-off', strings.ignore || 'Ignore', onIgnore);
  action('accept', 'phone', strings.accept || 'Accept', onAccept);
  // freeze audit: overlay autofocus took the FIRST focusable = Decline — a
  // reflexive Enter while ringing killed the call. APG: focus the safe action.
  actions.querySelector('[data-kind="accept"]').dataset.autofocus = '';
  el.append(actions);

  // Esc / scrim = the QUIETEST outcome (ignore) — never auto-declines.
  // data-silent (freeze audit): a REMOTE hang-up must not report onIgnore —
  // that's not a user outcome (shell may log/telemetry the ignore path)
  setOverlayOpts(el, { host, lightDismiss: true, escDismiss: true, onDismiss: () => {
    if (!acted && el.dataset.silent === undefined) {
      acted = true;
      if (onIgnore) onIgnore();
    }
  } });
  openOverlay(el);
  return el;
}

/** Bridge hook: caller hung up before an answer — drop the overlay SILENTLY
 *  (no onIgnore; see data-silent above). */
function hideIncomingCall(el) {
  el.dataset.silent = '';
  dismissOverlay(el);
}

/* ---- src/components/contact-request.js ---- */
/**
 * c-contact-request — incoming contact-request row in the Chats list (step 3;
 * spec §5). Promotes the app-frame inline block into a real component. Rendered
 * at the top of the list for pending requests. Decline routes through the
 * c-modal confirm (Cancel autofocused, APG); Accept fires onAccept(row). The
 * #109 STAGED HANDSHAKE (step 6): the caller latches the Accept button via
 * setRequestAccepting(row) — "Accepting…" loading — then transitions the request
 * into a handshaking chat; entry unblocks only on the bridge handshake-complete
 * signal. Non-contacts keep composer disabled downstream (#86, shell duty).
 *
 * createContactRequest({ name, nick, address, avatar, timestamp, strings, host,
 *                        onAccept, onDecline }) → row element
 * setRequestAccepting(row, strings) — latch Accept to "Accepting…" (loading).
 */







/** Middle-truncate a long address for display (keeps head + tail). */
function crDisplayAddress(addr) {
  const s = String(addr || '');
  return s.length > 14 ? s.slice(0, 6) + '…' + s.slice(-4) : s;
}

function createContactRequest({ name = '', nick = '', address = '', avatar = null, timestamp, strings = getStrings(), host, onAccept, onDecline } = {}) {
  const display = nick || name || crDisplayAddress(address);

  const row = document.createElement('div');
  row.className = 'c-contact-request';
  row.dataset.kind = 'request';

  // photo if present, else deterministic hue off the ADDRESS (identity-stable)
  row.append(createAvatar({ src: avatar, name: nick || name, address, size: 48 }));

  const body = document.createElement('div');
  body.className = 'c-contact-request__body';
  const nameEl = document.createElement('span');
  nameEl.className = 'c-contact-request__name';
  nameEl.textContent = display;                      // user data → textContent (XSS-safe)
  const sub = document.createElement('span');
  sub.className = 'c-contact-request__sub';
  sub.textContent = strings.wantsToConnect || 'Wants to connect';
  body.append(nameEl, sub);

  const actions = document.createElement('div');
  actions.className = 'c-contact-request__actions';
  const declineLabel = strings.decline || 'Decline';
  const acceptLabel = strings.accept || 'Accept';
  const decline = createButton({
    label: declineLabel, type: 'outline', size: 32,
    onClick: () => openModal(createModal({
      title: strings.declineTitle || 'Decline request?',
      body: (strings.declineBody || '{name} won’t be notified, and can send another request later.').split('{name}').join(display),
      role: 'alertdialog', host,
      actions: [
        { label: strings.cancel || 'Cancel', type: 'text', autofocus: true },
        { label: declineLabel, type: 'fill', intent: 'destructive', onClick: () => { if (onDecline) onDecline(); } },
      ],
    })),
  });
  decline.dataset.decline = '';
  decline.setAttribute('aria-label', declineLabel + ' ' + display);
  const accept = createButton({
    label: acceptLabel, type: 'fill', size: 32, icon: icon('check', { size: 16 }),
    onClick: () => { if (onAccept) onAccept(row); },
  });
  accept.dataset.accept = '';
  accept.setAttribute('aria-label', acceptLabel + ' ' + display);
  actions.append(decline, accept);
  body.append(actions);
  row.append(body);

  const time = document.createElement('span');
  time.className = 'c-contact-request__time u-tabular';
  time.textContent = formatChatTimestamp(timestamp, strings);
  row.append(time);

  return row;
}

/** Latch the Accept button into "Accepting…" loading (staged handshake, #109);
 *  Decline is disabled while accepting. The row is then transitioned into a
 *  handshaking chat by the shell (acceptContactRequest). */
function setRequestAccepting(row, strings = getStrings()) {
  const btn = row && row.querySelector('[data-accept]');
  if (!btn) return;
  const accepting = strings.accepting || 'Accepting…';
  const label = btn.querySelector('.c-button__label');
  if (label) label.textContent = accepting;
  btn.setAttribute('aria-label', accepting);       // keep SR label in sync with the visible state
  setLoading(btn, true);
  const decline = row.querySelector('[data-decline]');
  if (decline) decline.disabled = true;
}

/* ---- src/components/chats-row-menu.js ---- */
/**
 * Chat-row context menu (step 4; spec §6). Long-press / right-click a chat row →
 * c-sheet with Pin/Mute/Mark read/Chat info/Delete. Reuses the c-msgmenu sheet
 * styling (message-menu.css) + the message-menu interaction pattern (long-press
 * ~500ms, cancel on >10px move = scroll intent; desktop right-click; Android
 * double-open guard). Delete routes through the c-modal confirm. Chat info is a
 * stub (Damir: pane deferred) → fires onAction('info'), shell shows a toast.
 *
 * Pin/Mute are CAPABILITY-GATED (parkable until BE persists them, #67/§8): shown
 * only when capabilities.pin / capabilities.mute are truthy. Mark-read / Chat
 * info / Delete are always present. A HANDSHAKING row (#109, still establishing)
 * gets a single "Cancel handshake" action instead — the row's only recovery path
 * (it has no swipe / open), so a stalled handshake is never an un-removable trap.
 *
 * openChatRowMenu({ chat, host, onAction, strings, capabilities, handshaking }) → sheet
 *   onAction(action) — 'pin' | 'mute' | 'markRead' | 'info' | 'delete' | 'cancelHandshake'
 * attachChatRowMenu(row, opts) — wires long-press + right-click on the row
 */






const CHATMENU_LONG_PRESS_MS = 500;   // §5b
const CHATMENU_MOVE_CANCEL_PX = 10;   // §5b: >10px move = scroll intent

function openChatRowMenu({ chat = {}, host, onAction, strings = getStrings(), capabilities = {}, handshaking = false } = {}) {
  closeChatRowSwipe();                              // any open swipe drawer closes when a sheet takes over (single-open invariant across row types)
  const content = document.createElement('div');
  content.className = 'c-msgmenu';                 // reuse the sheet-menu styling
  const list = document.createElement('div');
  list.className = 'c-msgmenu__list';

  const act = (action) => { closeSheet(sheet); if (onAction) onAction(action); };
  const item = (glyph, label, onClick, destructive = false) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'c-msgmenu__item';
    if (destructive) b.dataset.destructive = '';
    b.append(icon(glyph, { size: 20 }), document.createTextNode(label));
    b.addEventListener('click', onClick);
    list.append(b);
  };

  // #109: a handshaking row can ONLY be cancelled (its recovery path) — no
  // pin/mute/mark-read/info/open while the key exchange is still in flight.
  if (handshaking) {
    item('x', strings.cancelHandshake || 'Cancel handshake', () => {
      closeSheet(sheet);
      openModal(createModal({
        title: strings.cancelHandshakeTitle || 'Cancel handshake?',
        body: strings.cancelHandshakeBody || 'This stops establishing the secure connection and removes the chat.',
        role: 'alertdialog', host,
        actions: [
          { label: strings.keepWaiting || 'Keep waiting', type: 'text', autofocus: true },
          { label: strings.cancel || 'Cancel', type: 'fill', intent: 'destructive', onClick: () => { if (onAction) onAction('cancelHandshake'); } },
        ],
      }));
    }, true);
    content.append(list);
    const sheet = createSheet({ content, host, strings });
    openSheet(sheet);
    return sheet;
  }

  // toggles reflect what tapping DOES (glyph + label). Pin/Mute parkable (§8).
  if (capabilities.pin) {
    item(chat.pinned ? 'pinned-off' : 'pin',
         chat.pinned ? (strings.unpin || 'Unpin') : (strings.pin || 'Pin'),
         () => act('pin'));
  }
  if (capabilities.mute) {
    item(chat.muted ? 'bell' : 'bell-off',
         chat.muted ? (strings.unmute || 'Unmute') : (strings.mute || 'Mute'),
         () => act('mute'));
  }
  item('checks', strings.markRead || 'Mark as read', () => act('markRead'));
  item('info-circle', strings.chatInfo || 'Chat info', () => act('info'));
  // destructive last (§5b) — confirm via c-modal
  item('trash', strings.deleteChat || 'Delete chat', () => {
    closeSheet(sheet);
    openModal(createModal({
      title: strings.deleteChatTitle || 'Delete chat?',
      body: strings.deleteChatBody || 'This removes the conversation from your device.',
      role: 'alertdialog', host,
      actions: [
        { label: strings.cancel || 'Cancel', type: 'text', autofocus: true },   // safe action focused (APG)
        { label: strings.delete || 'Delete', type: 'fill', intent: 'destructive', onClick: () => { if (onAction) onAction('delete'); } },
      ],
    }));
  }, true);

  content.append(list);
  const sheet = createSheet({ content, host, strings });
  openSheet(sheet);
  return sheet;
}

/** Long-press (touch) + right-click (desktop) wiring for one chat row. */
function attachChatRowMenu(row, opts = {}) {
  let timer = null;
  let startX = 0;
  let startY = 0;
  let fired = false;

  const cancel = () => { if (timer) { clearTimeout(timer); timer = null; } };

  row.addEventListener('pointerdown', (e) => {
    fired = false;                              // any new gesture resets suppression (audit r4)
    if (e.button !== 0) return;                 // right button → contextmenu path
    startX = e.clientX; startY = e.clientY;
    cancel();
    timer = setTimeout(() => {
      timer = null;
      fired = true;
      openChatRowMenu({ ...opts });
    }, CHATMENU_LONG_PRESS_MS);
  });
  row.addEventListener('pointermove', (e) => {
    if (timer && (Math.abs(e.clientX - startX) > CHATMENU_MOVE_CANCEL_PX ||
                  Math.abs(e.clientY - startY) > CHATMENU_MOVE_CANCEL_PX)) cancel();
  });
  row.addEventListener('pointerup', cancel);
  row.addEventListener('pointercancel', cancel);
  // long-press fired → the release click must not open the chat
  row.addEventListener('click', (e) => {
    if (fired) { e.preventDefault(); e.stopPropagation(); fired = false; }
  }, true);

  row.addEventListener('contextmenu', (e) => {
    e.preventDefault();
    if (fired) return;                          // Android fires contextmenu ≈ long-press (audit r3)
    cancel();
    fired = true;
    openChatRowMenu({ ...opts });
  });

  // keyboard path to the context menu (a11y): the swipe accelerator is pointer-only,
  // so keyboard users reach Pin/Mute/Mark-read/Delete here. Shift+F10 and the
  // dedicated ContextMenu/Apps key are the standard "open context menu" bindings.
  row.addEventListener('keydown', (e) => {
    if (e.key === 'ContextMenu' || (e.shiftKey && e.key === 'F10')) {
      e.preventDefault();
      cancel();
      fired = false;                            // keyboard open ≠ a click to suppress
      openChatRowMenu({ ...opts });
    }
  });
}

/* ---- src/components/chats-swipe.js ---- */
/**
 * Chat-row swipe accelerator (step 5, spec §6; Damir: option 1 = iOS-Mail reveal
 * + full-swipe). Pointer-only accelerator — the long-press sheet is the
 * accessible/keyboard path (the action buttons here are tabindex=-1 + aria-hidden
 * by design). Leading swipe = Pin/Unpin, trailing = Mute/Unmute, each shown ONLY
 * if its capability is enabled (parkable until BE persists them, #67/§8). Delete
 * stays menu-only; NON-destructive actions only.
 *
 *   wrapChatRowSwipe(rowEl, { chat, capabilities, strings, onAction, rtl }) → wrapper
 *     onAction('pin'|'mute') fires on full-swipe commit OR action-button tap.
 *   closeChatRowSwipe() — closes any currently-open drawer (call before a list
 *     re-render so the single-open invariant + GC hold).
 *
 * If neither pin nor mute is enabled, returns rowEl unwrapped (no swipe).
 * Behaviour: drag reveals the enabled side's labelled action; release past the
 * COMMIT ratio fires it; release past OPEN settles the button open (tap to fire);
 * otherwise springs back. Only one row open at a time. Tapping an open row (or
 * touching another row) closes the drawer.
 */



const SWIPE_OPEN_PX = 76;         // settle offset that holds the action button open (== CSS min-width)
const SWIPE_COMMIT_RATIO = 0.4;   // drag past this fraction of the row width → fire
const SWIPE_DIRLOCK_PX = 8;       // travel before we decide horizontal vs vertical

let currentClose = null;          // close fn of the currently-open row (only one open)
function closeCurrent() { if (currentClose) { const c = currentClose; currentClose = null; c(); } }

/** Close any open drawer — call before a list re-render (detaches would orphan it). */
function closeChatRowSwipe() { closeCurrent(); }

function wrapChatRowSwipe(rowEl, { chat = {}, capabilities = {}, strings = getStrings(), onAction, rtl } = {}) {
  const dir = rtl != null ? rtl
    : (typeof document !== 'undefined' && document.documentElement.getAttribute('dir') === 'rtl');
  // physical sides ↔ logical actions (RTL mirrors leading/trailing)
  const leftAction = dir ? 'mute' : 'pin';
  const rightAction = dir ? 'pin' : 'mute';
  const enabled = (a) => (a === 'pin' ? !!capabilities.pin : !!capabilities.mute);
  const leftEnabled = enabled(leftAction);
  const rightEnabled = enabled(rightAction);
  if (!leftEnabled && !rightEnabled) return rowEl;   // fully parked → no swipe wrapper

  const wrap = document.createElement('div');
  wrap.className = 'c-swipe';

  const actionBtn = (action, side) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'c-swipe__action c-swipe__action--' + side;
    b.dataset.action = action;
    b.tabIndex = -1;                          // pointer-only accelerator (sheet is the a11y path)
    b.setAttribute('aria-hidden', 'true');
    const label = action === 'pin'
      ? (chat.pinned ? (strings.unpin || 'Unpin') : (strings.pin || 'Pin'))
      : (chat.muted ? (strings.unmute || 'Unmute') : (strings.mute || 'Mute'));
    const glyph = action === 'pin'
      ? (chat.pinned ? 'pinned-off' : 'pin')
      : (chat.muted ? 'bell' : 'bell-off');
    b.append(icon(glyph, { size: 22 }));
    const t = document.createElement('span');
    t.className = 'c-swipe__label';
    t.textContent = label;
    b.append(t);
    b.setAttribute('aria-label', label);
    b.addEventListener('click', () => fire(action));
    return b;
  };
  if (leftEnabled) wrap.append(actionBtn(leftAction, 'left'));
  if (rightEnabled) wrap.append(actionBtn(rightAction, 'right'));

  const content = document.createElement('div');
  content.className = 'c-swipe__content';
  content.append(rowEl);
  wrap.append(content);

  let offset = 0;                 // current translateX (physical px)
  let startX = 0, startY = 0, startOffset = 0;
  let dragging = false, decided = false, horiz = false, swiped = false;

  const setX = (x, animate) => {
    content.style.transition = animate ? '' : 'none';   // '' = CSS transition (spring)
    content.style.transform = x ? 'translateX(' + x + 'px)' : '';
    offset = x;
  };
  const close = () => { setX(0, true); delete wrap.dataset.open; if (currentClose === close) currentClose = null; };
  const openTo = (x) => { closeCurrent(); setX(x, true); wrap.dataset.open = ''; currentClose = close; };
  const fire = (action) => { setX(0, true); delete wrap.dataset.open; if (currentClose === close) currentClose = null; if (onAction) onAction(action); };

  content.addEventListener('pointerdown', (e) => {
    if (e.button !== 0) return;
    swiped = false;                                         // reset per gesture (#2: never suppress a fresh tap)
    if (currentClose && currentClose !== close) closeCurrent();   // touching another row closes the open one
    startX = e.clientX; startY = e.clientY; startOffset = offset;
    dragging = true; decided = false; horiz = false;
  });
  content.addEventListener('pointermove', (e) => {
    if (!dragging) return;
    const dx = e.clientX - startX, dy = e.clientY - startY;
    if (!decided) {
      if (Math.abs(dx) < SWIPE_DIRLOCK_PX && Math.abs(dy) < SWIPE_DIRLOCK_PX) return;
      decided = true;
      horiz = Math.abs(dx) > Math.abs(dy);
      if (horiz) {
        swiped = true;
        // cancel a pending long-press on the ROW without ending our own gesture
        // (non-bubbling so it doesn't reach content's pointercancel → end). #3
        try { rowEl.dispatchEvent(new Event('pointercancel', { bubbles: false })); } catch (_) {}
        if (content.setPointerCapture) { try { content.setPointerCapture(e.pointerId); } catch (_) {} }
      }
    }
    if (!horiz) return;            // vertical intent → let the list scroll, don't hijack
    e.preventDefault();
    let x = startOffset + dx;
    if (x > 0 && !leftEnabled) x = 0;      // can't reveal a parked side
    if (x < 0 && !rightEnabled) x = 0;
    const w = wrap.offsetWidth || 320;
    x = Math.max(-w, Math.min(w, x));
    setX(x, false);
  });
  const end = () => {
    if (!dragging) return;
    dragging = false;
    if (!horiz) return;            // stationary / vertical gesture — nothing to settle
    const w = wrap.offsetWidth || 320;
    const commit = w * SWIPE_COMMIT_RATIO;
    if (offset >= commit && leftEnabled) return fire(leftAction);
    if (offset <= -commit && rightEnabled) return fire(rightAction);
    if (offset >= SWIPE_OPEN_PX && leftEnabled) return openTo(SWIPE_OPEN_PX);
    if (offset <= -SWIPE_OPEN_PX && rightEnabled) return openTo(-SWIPE_OPEN_PX);
    close();
  };
  content.addEventListener('pointerup', end);
  content.addEventListener('pointercancel', end);

  // a swipe must not also open the chat; and tapping an OPEN row closes the drawer
  content.addEventListener('click', (e) => {
    if (swiped) { e.preventDefault(); e.stopPropagation(); swiped = false; return; }
    if (wrap.dataset.open !== undefined) { e.preventDefault(); e.stopPropagation(); close(); }
  }, true);

  return wrap;
}

/* ---- src/components/chats-shell.js ---- */
/**
 * c-chats-shell — Chats flow shell scaffold: model + render pipeline. Spec:
 * docs/chats-shell-spec.md. Steps: 1 model/render · 3 c-contact-request ·
 * 4 row context menu · 5 swipe accelerator.
 *
 * Holds the chats/requests MODEL and renders the visible list — requests on top,
 * then pinned, then recency. Filter + search operate on the MODEL, not the DOM
 * (#52). Inline mock data feeds it (no bridge module yet — Damir). Reuses
 * createChatItem + createContactRequest + attachChatRowMenu + wrapChatRowSwipe.
 *
 * Model shapes:
 *   chat:    { name, address, online, pinned, muted, favorite, type,
 *              timestamp, status, unread, mention, handshaking,
 *              excerpt:{type,text,sender} }
 *   request: { name, address, avatar, timestamp }   // normalized 'pending' entry
 *   state:   { chats:[], requests:[], filter:'all', query:'' }
 *   filter ∈ 'all' | 'unread' | 'favorites' | 'groups' | 'requests'
 *
 * #109 staged accept: acceptContactRequest turns a request into a handshaking
 * chat (excerpt "Establishing a quantum-secure handshake…", typing style); it's
 * un-openable/un-swipeable/un-menuable until completeHandshake fires on the bridge
 * signal. The caller latches the Accept button first (setRequestAccepting).
 *
 * opts: { strings, host, capabilities:{pin,mute,favorites,…}, rowMenu,
 *         onOpen, onHandshakeBlocked(chat), onRequestAccept(req,row),
 *         onRequestDecline(req), onChatInfo(chat), onModelChange(state),
 *         onPersist(action,chat) }
 * capabilities gate BE-dependent features so they can be PARKED until BE ships
 * (#67/§8): pin/mute swipe + menu items render only when their flag is truthy.
 * Update APIs are FREE FUNCTIONS operating on (listEl, state, …) per #44.
 */






/* —————————————————————— model (pure, DOM-free, testable) —————————————————————— */

/** Does a chat pass the active filter chip? Requests are handled separately. */
function chatMatchesFilter(chat, filter) {
  switch (filter) {
    case 'unread': return (chat.unread || 0) > 0 || !!chat.mention;
    case 'favorites': return !!chat.favorite;          // BE-gated (§8) — empty until then
    case 'groups': return chat.type === 'group';
    case 'requests': return false;                     // requests are not chats
    case 'all':
    default: return true;
  }
}

/** Locale-aware substring match over name (or address) + excerpt text.
 *  Empty/whitespace needle matches everything. */
function chatMatchesQuery(item, needle) {
  const q = (needle || '').trim().toLocaleLowerCase();
  if (!q) return true;
  const name = (item.name || item.address || '').toLocaleLowerCase();
  if (name.includes(q)) return true;
  const ex = item.excerpt && item.excerpt.text;
  return typeof ex === 'string' && ex.toLocaleLowerCase().includes(q);
}

/** Requests appear in the 'all' and 'requests' filters; searchable. In 'all'
 *  they INTERLEAVE by arrival time (see orderedTimeline), not pinned on top —
 *  Damir 2026-07-04: a request sits at its chronological place; accepting it
 *  slides the new chat to the top (latest action). Not shown in Groups (1:1). */
function orderedRequests(state) {
  const f = state.filter;
  if (f !== 'all' && f !== 'requests') return [];
  return (state.requests || []).filter(Boolean).filter((r) => chatMatchesQuery(r, state.query));
}

/** Visible chats: filtered by chip + query, then pinned-first, then newest-first.
 *  Array#sort is stable (ES2019+), so equal keys keep source order. */
function orderedChats(state) {
  if (state.filter === 'requests') return [];
  return (state.chats || [])
    .filter(Boolean)                                    // harden against null entries from a bridge feed
    .filter((c) => chatMatchesFilter(c, state.filter) && chatMatchesQuery(c, state.query))
    .slice()                                            // never mutate the source array
    .sort((a, b) => {
      const pinDelta = (b.pinned ? 1 : 0) - (a.pinned ? 1 : 0);
      if (pinDelta) return pinDelta;                    // pinned above the rest
      return (b.timestamp || 0) - (a.timestamp || 0);   // newest first
    });
}

/** Combined All-list order: **pinned chats stay on top**, then pending requests
 *  and unpinned chats **interleave by recency** (newest first). A request sits at
 *  its arrival time (not pinned to the top); an accepted chat (timestamp = now)
 *  slides to the top of the unpinned flow. In the 'requests' filter orderedChats
 *  is empty, so this yields just the requests, newest-first. Returns a flat list
 *  of `{ kind: 'chat' | 'request', item }`. */
function orderedTimeline(state) {
  const reqs = orderedRequests(state);
  const chats = orderedChats(state);
  const pinned = chats.filter((c) => c.pinned).map((c) => ({ kind: 'chat', item: c }));
  const flow = [
    ...chats.filter((c) => !c.pinned).map((c) => ({ ts: c.timestamp || 0, kind: 'chat', item: c })),
    ...reqs.map((r) => ({ ts: r.timestamp || 0, kind: 'request', item: r })),
  ]
    .sort((a, b) => b.ts - a.ts)                          // newest first; stable → chat before request on a tie
    .map(({ kind, item }) => ({ kind, item }));
  return [...pinned, ...flow];
}

/** Unread total excluding muted; a bare mention counts as 1 (mirrors #42 / the
 *  value setUnreadIndicator should deliver). Drives the Chats nav badge. */
function chatsUnreadTotal(chats) {
  return (chats || []).filter(Boolean).reduce((n, c) => {
    if (c.muted) return n;
    const u = Math.max(0, c.unread || 0);            // clamp: a negative/corrupt count must not drag the badge below true
    return n + (u || (c.mention ? 1 : 0));
  }, 0);
}

/* ————————————————————————————— render pipeline ————————————————————————————— */

/** Empty-state copy for the active filter/query (defaults; strings override).
 *  (Placeholder copy — illustrations + CTAs are a later pass, Damir.) */
function chatsEmptyCopy(state, strings) {
  const q = (state.query || '').trim();
  // split/join, not replace(): a query with $-patterns ($&, $', $1…) would be
  // interpreted as replacement specials by String#replace and corrupt the text.
  if (q) return (strings.chatsEmptySearch || 'No chats match “{q}”').split('{q}').join(q);
  switch (state.filter) {
    case 'unread': return strings.chatsEmptyUnread || 'No unread chats';
    case 'groups': return strings.chatsEmptyGroups || 'No groups yet';
    case 'favorites': return strings.chatsEmptyFavorites || 'No favorites yet';
    case 'requests': return strings.chatsEmptyRequests || 'No pending requests';
    case 'all':
    default: return strings.chatsEmptyAll || 'No chats yet';
  }
}

function chatsEmptyState(state, strings) {
  const el = document.createElement('div');
  el.className = 'c-chats-empty';
  el.setAttribute('role', 'note');
  el.textContent = chatsEmptyCopy(state, strings);
  return el;
}

/** (Re)render the whole list from the model. Full re-render for the scaffold
 *  (row-level diffing is a logged enhancement — spec §9). Returns listEl. */
function renderChatsList(listEl, state, opts = {}) {
  const strings = opts.strings || getStrings();
  const caps = opts.capabilities || {};
  closeChatRowSwipe();                                   // close any open swipe drawer before detaching rows (#1: single-open + GC)
  listEl.textContent = '';                               // clear (detaches old rows + listeners for GC)

  const renderRequest = (r) => {
    listEl.append(createContactRequest({
      ...r, strings, host: opts.host,
      onAccept: opts.onRequestAccept ? (row) => opts.onRequestAccept(r, row) : undefined,
      onDecline: opts.onRequestDecline ? () => opts.onRequestDecline(r) : undefined,
    }));
  };
  const renderChat = (c) => {
    // handshaking chats (#109) are not yet openable — tapping routes to
    // onHandshakeBlocked, and they carry no pin/mute affordances until secured.
    const onClick = c.handshaking
      ? (opts.onHandshakeBlocked ? () => opts.onHandshakeBlocked(c) : undefined)
      : (opts.onOpen ? () => opts.onOpen(c) : undefined);
    const el = createChatItem({ ...c, strings, onClick });
    if (c.pinned) el.dataset.pinned = '';                // shell markers for pin/mute
    if (c.muted) el.dataset.muted = '';
    if (c.handshaking) {                                 // #109: no open/swipe/pin — but a cancel menu so a stalled handshake is recoverable
      el.dataset.handshaking = ''; el.setAttribute('aria-busy', 'true');
      if (opts.rowMenu !== false) {
        attachChatRowMenu(el, {
          chat: c, host: opts.host, strings, handshaking: true,
          onAction: (action) => { if (action === 'cancelHandshake') failHandshake(listEl, state, c, opts); },
        });
      }
      listEl.append(el); return;
    }
    if (opts.rowMenu !== false) {                        // long-press/right-click → context sheet (step 4)
      attachChatRowMenu(el, {
        chat: c, host: opts.host, strings, capabilities: caps,
        onAction: (action) => applyChatRowAction(listEl, state, c, action, opts),
      });
    }
    // swipe accelerator (step 5) — capability-gated; returns el unwrapped if parked
    const node = wrapChatRowSwipe(el, {
      chat: c, capabilities: caps, strings,
      onAction: (action) => applyChatRowAction(listEl, state, c, action, opts),
    });
    listEl.append(node);
  };

  // pinned chats on top, then requests + unpinned chats interleaved by recency
  const timeline = orderedTimeline(state);
  for (const { kind, item } of timeline) (kind === 'request' ? renderRequest : renderChat)(item);

  if (!timeline.length) listEl.append(chatsEmptyState(state, strings));
  return listEl;
}

/** Apply a row action (menu or swipe) to the model, then re-render (#44). Pin/
 *  mute toggle, mark-read clears unread+mention, delete removes the chat; info is
 *  a stub (no model change) → opts.onChatInfo. On a model change: fire
 *  opts.onPersist(action, chat) — the bridge intent (mock no-op now; a real
 *  `ixian:` command when BE ships, §8) — then re-render + opts.onModelChange. */
function applyChatRowAction(listEl, state, chat, action, opts = {}) {
  switch (action) {
    case 'pin': chat.pinned = !chat.pinned; break;
    case 'mute': chat.muted = !chat.muted; break;
    case 'markRead': chat.unread = 0; chat.mention = false; break;
    case 'delete': state.chats = (state.chats || []).filter((c) => c !== chat); break;
    case 'info': if (opts.onChatInfo) opts.onChatInfo(chat); return;   // stub — no model change
    default: return;
  }
  if (opts.onPersist) opts.onPersist(action, chat);      // bridge intent → C# persists (mock no-op)
  renderChatsList(listEl, state, opts);
  if (opts.onModelChange) opts.onModelChange(state);
}

/* ————————————————————— #109 staged accept handshake ————————————————————— */

/** Accept a pending request → transition it into a HANDSHAKING chat. Removes the
 *  request, prepends a chat with handshaking:true + the "Establishing a
 *  quantum-secure handshake…" excerpt (typing style), re-renders, and returns the
 *  new chat so the caller can settle it via completeHandshake on the bridge's
 *  handshake-complete signal (§9). No-op (returns null) if the request is already
 *  gone — guards double-accept from a double-tap before re-render. Opening the
 *  handshaking chat is blocked (onHandshakeBlocked) until it completes. */
function acceptContactRequest(listEl, state, req, opts = {}) {
  if (!req || (state.requests || []).indexOf(req) === -1) return null;
  const strings = opts.strings || getStrings();
  state.requests = (state.requests || []).filter((r) => r !== req);
  const chat = {
    name: req.name, nick: req.nick, address: req.address, avatar: req.avatar,
    type: 'direct', timestamp: Date.now(), handshaking: true, unread: 0, mention: false,
    excerpt: { type: 'typing', text: strings.handshakeEstablishing || 'Establishing a quantum-secure handshake…' },
  };
  state.chats = [chat, ...(state.chats || [])];
  renderChatsList(listEl, state, opts);
  if (opts.onModelChange) opts.onModelChange(state);
  return chat;
}

/** The bridge handshake-complete signal landed — unblock entry. Clears the
 *  handshaking flag + the establishing excerpt, re-renders. Bumping the timestamp
 *  surfaces the just-secured contact at the top (you likely want to message them).
 *  No-op if the chat was deleted/never-handshaking meanwhile (guards a late signal). */
function completeHandshake(listEl, state, chat, opts = {}) {
  if (!chat || (state.chats || []).indexOf(chat) === -1 || !chat.handshaking) return;
  const strings = opts.strings || getStrings();
  chat.handshaking = false;
  chat.excerpt = { type: 'text', text: strings.handshakeReady || '' };   // empty until a real message arrives
  chat.timestamp = Date.now();
  renderChatsList(listEl, state, opts);
  if (opts.onModelChange) opts.onModelChange(state);
}

/** Handshake failed / timed out / user-cancelled — remove the stranded chat so a
 *  never-completing handshake is never an un-removable trap (bridge failure signal
 *  §9, OR the row's Cancel-handshake action). No-op if it already settled/left. */
function failHandshake(listEl, state, chat, opts = {}) {
  if (!chat || (state.chats || []).indexOf(chat) === -1 || !chat.handshaking) return;
  state.chats = (state.chats || []).filter((c) => c !== chat);
  renderChatsList(listEl, state, opts);
  if (opts.onModelChange) opts.onModelChange(state);
}

/** Build the list container and render it. */
function createChatsList(state, opts = {}) {
  const el = document.createElement('div');
  el.className = 'c-chats-list';
  renderChatsList(el, state, opts);
  return el;
}

/* update APIs — free functions (#44): mutate state, re-render, return listEl */

function setChatsFilter(listEl, state, filter, opts) {
  state.filter = filter;
  return renderChatsList(listEl, state, opts);
}

function setChatsQuery(listEl, state, query, opts) {
  state.query = query;
  return renderChatsList(listEl, state, opts);
}

/* ---- src/components/chats-header.js ---- */
/**
 * c-chats-header — collapsing header for the Chats shell (step 2): search field
 * + filter chips as ONE unit, plus the scroll-collapse behavior (#67, Damir).
 * Search wires to setChatsQuery, chips to setChatsFilter (chats-shell.js).
 * Favorites is BE-gated (§8) → hidden unless opts.favorites.
 * Spec: docs/chats-shell-spec.md §3–4.
 *
 * Two exports:
 *   createChatsHeader(opts) → header element (search + chips)
 *   attachChatsCollapse(headerEl, scrollEl, opts) → detach()  [scroll behavior]
 */




const CHATS_FILTERS = [
  { id: 'all', label: 'All' },
  { id: 'unread', label: 'Unread' },
  { id: 'favorites', label: 'Favorites' },   // BE-gated (§8) — hidden unless favorites:true
  { id: 'groups', label: 'Groups' },
  { id: 'requests', label: 'Requests' },
];

/** Build the header: search field + exclusive filter-chip group. */
function createChatsHeader({ activeFilter = 'all', strings = getStrings(), favorites = false, onFilter, onQuery } = {}) {
  const el = document.createElement('div');
  el.className = 'c-chats-header';

  const searchWrap = document.createElement('div');
  searchWrap.className = 'c-chats-header__search';
  searchWrap.append(createSearchField({
    placeholder: strings.searchChats || 'Search chats',
    onInput: (q) => { if (onQuery) onQuery(q); },
  }));
  el.append(searchWrap);

  const chipsRow = document.createElement('div');
  chipsRow.className = 'c-chats-header__filters';
  chipsRow.setAttribute('role', 'group');
  chipsRow.setAttribute('aria-label', strings.filterChats || 'Filter chats');

  const chips = CHATS_FILTERS
    .filter((f) => f.id !== 'favorites' || favorites)      // Favorites hidden until BE (§8)
    .map((f) => {
      const chip = createChip({
        label: strings['chatsFilter_' + f.id] || f.label,
        selected: f.id === activeFilter,
        onClick: () => {
          for (const c of chips) setChipSelected(c, c === chip);   // exclusive group
          if (onFilter) onFilter(f.id);
        },
      });
      chip.dataset.filter = f.id;
      return chip;
    });
  chipsRow.append(...chips);
  el.append(chipsRow);

  return el;
}

// reveal ONLY within this many px of the absolute top (Damir: "appear only at
// absolute top"); 1px covers sub-pixel scroll rest positions.
const CHATS_REVEAL_AT = 1;

/**
 * Scroll-collapse (#67, Damir): binary, TRIGGERED CSS transition (smooth, not
 * finger-tracking). The header collapses on downward scroll and reveals ONLY
 * when the list is back at the absolute top — scrolling up partway does NOT
 * reveal it. Animates `max-height` + `opacity` (transition lives in
 * chats-header.css, --duration-300 --easing-standard; reduced-motion zeros it).
 *
 * a11y: collapsed header leaves the tab order via `inert` + `aria-hidden`, plus
 * a fallback (`data-collapsed` → pointer-events:none + `tabindex="-1"` on the
 * focusables) because `inert` needs a modern WebView (Chromium ≥102, #4). All
 * toggle only on collapse⇄reveal transitions.
 */
function attachChatsCollapse(headerEl, scrollEl, { reducedMotion } = {}) {
  const rm = reducedMotion != null ? reducedMotion
    : (typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches);

  let naturalH = headerEl.offsetHeight || 0;   // full height (re-captured at each collapse)
  let collapsed = false;
  let lastTop = scrollEl.scrollTop;

  const setFocusable = (on) => {
    for (const f of headerEl.querySelectorAll('input, button')) {
      if (on) f.removeAttribute('tabindex'); else f.setAttribute('tabindex', '-1');
    }
  };

  const onEnd = (e) => {
    // once fully expanded, release max-height to natural so a later collapse
    // re-measures fresh (handles font-load / orientation while collapsed)
    if (e.target === headerEl && e.propertyName === 'max-height' && !collapsed) {
      headerEl.style.maxHeight = '';
    }
  };
  headerEl.addEventListener('transitionend', onEnd);

  const setCollapsed = (want) => {
    if (want === collapsed) return;
    if (want) {
      const h = headerEl.offsetHeight || naturalH;      // capture current height
      if (!h) return;                                   // never collapse an UNMEASURED header (stay expanded)
      naturalH = h;
      collapsed = true;
      headerEl.style.maxHeight = naturalH + 'px';
      void headerEl.offsetHeight;                       // reflow so 0 transitions FROM naturalH
      headerEl.style.maxHeight = '0px';
      headerEl.style.opacity = '0';
      headerEl.setAttribute('inert', '');
      headerEl.setAttribute('aria-hidden', 'true');
      headerEl.dataset.collapsed = '';
      setFocusable(false);
    } else {
      collapsed = false;
      headerEl.style.maxHeight = naturalH + 'px';       // 0 → naturalH (transition)
      headerEl.style.opacity = '';                      // release to CSS default (1); animates 0→1
      if (rm) headerEl.style.maxHeight = '';            // instant → release immediately
      headerEl.removeAttribute('inert');
      headerEl.removeAttribute('aria-hidden');
      delete headerEl.dataset.collapsed;
      setFocusable(true);
    }
  };

  const onScroll = () => {
    const top = scrollEl.scrollTop;
    const delta = top - lastTop;
    lastTop = top;
    if (top <= CHATS_REVEAL_AT) setCollapsed(false);   // reveal ONLY at the absolute top
    else if (delta > 0) setCollapsed(true);            // collapse on downward scroll (stays collapsed on up)
  };

  const onResize = () => {                    // re-measure while expanded (can't while collapsed)
    if (!collapsed) { headerEl.style.maxHeight = ''; naturalH = headerEl.offsetHeight || naturalH; }
  };

  scrollEl.addEventListener('scroll', onScroll, { passive: true });
  window.addEventListener('resize', onResize);

  return function detachChatsCollapse() {
    scrollEl.removeEventListener('scroll', onScroll);
    window.removeEventListener('resize', onResize);
    headerEl.removeEventListener('transitionend', onEnd);
    headerEl.style.maxHeight = '';
    headerEl.style.opacity = '';
    headerEl.removeAttribute('inert');
    headerEl.removeAttribute('aria-hidden');
    delete headerEl.dataset.collapsed;
    setFocusable(true);
  };
}

/* ---- src/components/apps-icon.js ---- */
/**
 * c-app-icon — a mini-app's icon as a rounded-SQUARE tile (the square sibling of
 * the round c-avatar). Shows the app image, or a deterministic gradient placeholder
 * (first letter, or the apps glyph) when no icon is available. Reuses the avatar
 * hue hash so a given app is always the same colour. Sizes: 48 (row) / 64 (card).
 *
 * createAppIcon({ src, name, size = 48 }) → span
 */



/** First letter for the placeholder (any script); null for empty/non-letter names. */
function appInitial(name) {
  const s = String(name || '').trim();
  if (!/^\p{L}/u.test(s)) return null;
  return [...s][0].toLocaleUpperCase();   // [...s] not s[0] — first char may be astral-plane
}

function createAppIcon({ src = null, name = '', size = 48 } = {}) {
  const el = document.createElement('span');
  el.className = 'c-app-icon';
  el.dataset.size = String(size);
  if (size !== 48 && size !== 64) { el.style.width = size + 'px'; el.style.height = size + 'px'; }

  if (src) {
    const img = document.createElement('img');
    img.className = 'c-app-icon__img';
    img.src = src;
    img.alt = '';                          // decorative — the name label carries meaning
    el.append(img);
  } else {
    const hue = hashHue(name || 'app');
    el.dataset.placeholder = '';
    el.style.setProperty('--ai-h1', hue);
    el.style.setProperty('--ai-h2', (hue + 40) % 360);
    const letter = appInitial(name);
    if (letter) {
      const t = document.createElement('span');
      t.className = 'c-app-icon__initial';
      t.setAttribute('aria-hidden', 'true');
      t.textContent = letter;
      el.append(t);
    } else {
      el.append(icon('apps', { size: Math.round(size * 0.5) }));
    }
  }
  return el;
}

/* ---- src/components/apps-item.js ---- */
/**
 * c-app-item — one installed mini-app, in two renderings off ONE model (spec §2.1):
 *   layout 'list' → a horizontal ROW (icon 48 · name+creator · ⋮)
 *   layout 'grid' → a CARD (icon 64 · name+creator, ⋮ top-trailing)
 *
 * Structure is a container with TWO sibling buttons (never nested — invalid a11y):
 *   .c-app-item__open  — the big tap target → onOpen(app)  (LAUNCHES the app, #126 2B)
 *   .c-app-item__menu  — the ⋮ overflow → onMenu(app, btn) (App details / Uninstall)
 * Creator (publisher) is a §8 field — rendered only when provided.
 *
 * createAppItem({ id, name, creator, icon, layout, strings, onOpen, onMenu }) → div
 */




function createAppItem({ id, name = '', creator = '', icon: iconSrc = null, layout = 'list', strings = getStrings(), onOpen, onMenu } = {}) {
  const el = document.createElement('div');
  el.className = 'c-app-item';
  el.dataset.layout = layout === 'grid' ? 'grid' : 'list';
  if (id != null) el.dataset.appId = String(id);

  const open = document.createElement('button');
  open.type = 'button';
  open.className = 'c-app-item__open';
  open.setAttribute('aria-label', name || (strings.app || 'App'));
  open.append(createAppIcon({ src: iconSrc, name, size: layout === 'grid' ? 64 : 48 }));

  const text = document.createElement('span');
  text.className = 'c-app-item__text';
  const nm = document.createElement('span');
  nm.className = 'c-app-item__name';
  nm.textContent = name;                                 // user data → textContent (XSS-safe)
  text.append(nm);
  if (creator) {
    const cr = document.createElement('span');
    cr.className = 'c-app-item__creator';
    cr.textContent = creator;
    text.append(cr);
  }
  open.append(text);
  if (onOpen) open.addEventListener('click', () => onOpen({ id, name, creator }));
  el.append(open);

  const menuBtn = document.createElement('button');
  menuBtn.type = 'button';
  menuBtn.className = 'c-app-item__menu';
  menuBtn.setAttribute('aria-label', (strings.moreOptions || 'More options') + (name ? ' — ' + name : ''));
  menuBtn.append(icon('dots', { size: 24 }));
  if (onMenu) menuBtn.addEventListener('click', (e) => { e.stopPropagation(); onMenu({ id, name, creator }, menuBtn); });
  el.append(menuBtn);

  return el;
}

/* ---- src/components/apps-menu.js ---- */
/**
 * App ⋮ overflow menu (spec §2.1). Tapping an app's ⋮ opens a c-sheet (reusing the
 * c-msgmenu styling, same infra as chats-row-menu): App details · Uninstall (confirm
 * via c-modal). Launch is the row's primary tap now, so it's not repeated here.
 * onAction(action, app) — 'details' | 'uninstall'.
 *
 * NB: uninstalling from the list menu assumes the bridge accepts uninstall-by-id from
 * the apps list (today `ixian:uninstall` is details-page-scoped) — flagged for BE (§8).
 *
 * openAppMenu({ app, host, onAction, strings }) → sheet
 */





function openAppMenu({ app = {}, host, onAction, strings = getStrings() } = {}) {
  const content = document.createElement('div');
  content.className = 'c-msgmenu';
  const list = document.createElement('div');
  list.className = 'c-msgmenu__list';

  const act = (action) => { closeSheet(sheet); if (onAction) onAction(action, app); };
  const item = (glyph, label, onClick, destructive = false) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'c-msgmenu__item';
    if (destructive) b.dataset.destructive = '';
    b.append(icon(glyph, { size: 20 }), document.createTextNode(label));
    b.addEventListener('click', onClick);
    list.append(b);
  };

  item('info-circle', strings.appDetails || 'App details', () => act('details'));
  item('trash', strings.uninstall || 'Uninstall', () => {
    closeSheet(sheet);
    openModal(createModal({
      title: strings.uninstallTitle || 'Uninstall app?',
      body: (strings.uninstallBody || 'This removes {name} from your device.')
        .split('{name}').join(app.name || strings.thisApp || 'this app'),
      role: 'alertdialog', host,
      actions: [
        { label: strings.cancel || 'Cancel', type: 'text', autofocus: true },
        { label: strings.uninstall || 'Uninstall', type: 'fill', intent: 'destructive', onClick: () => { if (onAction) onAction('uninstall', app); } },
      ],
    }));
  }, true);

  content.append(list);
  const sheet = createSheet({ content, host, strings });
  openSheet(sheet);
  return sheet;
}

/* ---- src/components/apps-shell.js ---- */
/**
 * c-apps-shell — Apps flow shell: model + render pipeline (spec: docs/apps-shell-spec.md).
 * Holds the installed-apps MODEL and renders them as a list (rows) or grid (cards)
 * per state.layout. Search filters the MODEL, not the DOM (#52). Reuses createAppItem.
 * Update APIs are FREE FUNCTIONS operating on (listEl, state, …) per #44.
 *
 * Model:
 *   app:   { id, name, icon, creator }
 *   state: { apps:[], query:'', layout:'list'|'grid' }
 * opts:  { strings, host, onLaunch(app), onOpen(app), onUninstall(app), onModelChange }
 *         onLaunch = primary tap (launch the app + record recent); onOpen = open details
 *         (the ⋮ "App details" action). Recents model: recordRecent / orderedRecents.
 */




/* ————————————————————————— model (pure, DOM-free) ————————————————————————— */

/** Substring match over name (+ creator). Empty/whitespace needle matches all. */
function appMatchesQuery(app, needle) {
  const q = (needle || '').trim().toLocaleLowerCase();
  if (!q) return true;
  if ((app.name || '').toLocaleLowerCase().includes(q)) return true;
  return (app.creator || '').toLocaleLowerCase().includes(q);
}

/** Visible apps: source order (install order, as the bridge appends), query-filtered.
 *  (Alphabetical sort is a logged enhancement — keeps parity with today's addApp.) */
function orderedApps(state) {
  return (state.apps || [])
    .filter(Boolean)                                   // harden against null entries from a bridge feed
    .filter((a) => appMatchesQuery(a, state.query));
}

/** Recents model: `state.recents` is a most-recent-first list of app ids. Launching an
 *  app moves it to the front (deduped, capped). Resolved back to live app objects for
 *  render — uninstalled/unknown ids drop out automatically. In-memory (persistence §7). */
function recordRecent(state, app) {
  if (!app || app.id == null) return state;
  const arr = (state.recents || []).filter((x) => x !== app.id);
  arr.unshift(app.id);
  state.recents = arr.slice(0, 12);
  return state;
}
function orderedRecents(state, limit = 8) {
  const byId = new Map((state.apps || []).filter(Boolean).map((a) => [a.id, a]));
  return (state.recents || [])
    .map((id) => byId.get(id))
    .filter(Boolean)
    .slice(0, limit);
}

/* ————————————————————————————— render pipeline ————————————————————————————— */

function appsEmptyCopy(state, strings) {
  const q = (state.query || '').trim();
  if (q) return (strings.appsEmptySearch || 'No apps match “{q}”').split('{q}').join(q);
  return strings.appsEmptyAll || 'No mini apps yet';
}

function appsEmptyState(state, strings) {
  const el = document.createElement('div');
  el.className = 'c-apps-empty';
  el.setAttribute('role', 'note');
  el.textContent = appsEmptyCopy(state, strings);
  return el;
}

/** (Re)render the whole list from the model. `state.layout` picks row vs card and
 *  sets `listEl[data-layout]` so the CSS switches between a column and a 2-up grid. */
function renderAppsList(listEl, state, opts = {}) {
  const strings = opts.strings || getStrings();
  const layout = state.layout === 'grid' ? 'grid' : 'list';
  listEl.dataset.layout = layout;
  listEl.textContent = '';                             // clear (detaches old rows + listeners for GC)

  const apps = orderedApps(state);
  for (const a of apps) {
    listEl.append(createAppItem({
      ...a, layout, strings,
      onOpen: opts.onLaunch ? () => opts.onLaunch(a) : undefined,   // tap → LAUNCH the app (⋮ → details/uninstall)
      onMenu: opts.appMenu === false ? undefined : () => openAppMenu({
        app: a, host: opts.host, strings,
        onAction: (action) => applyAppAction(listEl, state, a, action, opts),
      }),
    }));
  }
  if (!apps.length) listEl.append(appsEmptyState(state, strings));
  return listEl;
}

/** Apply an app ⋮-menu action (spec §2.1). 'open' launches (opts.onLaunch), 'details'
 *  opens the details view (opts.onOpen), 'uninstall' removes the app from the model,
 *  fires opts.onUninstall (bridge intent → `ixian:uninstall`, mock now), re-renders. */
function applyAppAction(listEl, state, app, action, opts = {}) {
  switch (action) {
    case 'open': if (opts.onLaunch) opts.onLaunch(app); return;
    case 'details': if (opts.onOpen) opts.onOpen(app); return;
    case 'uninstall': state.apps = (state.apps || []).filter((a) => a !== app); break;
    default: return;
  }
  if (opts.onUninstall) opts.onUninstall(app);              // bridge intent (mock no-op)
  renderAppsList(listEl, state, opts);
  if (opts.onModelChange) opts.onModelChange(state);
}

/** Build the list container and render it. */
function createAppsList(state, opts = {}) {
  const el = document.createElement('div');
  el.className = 'c-apps-list';
  renderAppsList(el, state, opts);
  return el;
}

/* update APIs — free functions (#44): mutate state, re-render, return listEl */

function setAppsLayout(listEl, state, layout, opts) {
  state.layout = layout === 'grid' ? 'grid' : 'list';   // in-memory preference (persistence deferred, §7)
  return renderAppsList(listEl, state, opts);
}

function setAppsQuery(listEl, state, query, opts) {
  state.query = query;
  return renderAppsList(listEl, state, opts);
}

/* ---- src/components/apps-recents.js ---- */
/**
 * c-apps-recents — a horizontal "Recently used" strip above the installed list.
 * Reuses c-app-icon; each tile taps to LAUNCH (opts.onLaunch). Hidden when there are
 * no recents. Model lives in apps-shell (recordRecent / orderedRecents), in-memory
 * for now (persistence deferred, §7).
 *
 * createAppsRecents(state, opts) → section
 * renderAppsRecents(el, state, opts) — free-fn updater (#44): rebuilds the strip.
 */




function renderAppsRecents(el, state, opts = {}) {
  const strings = opts.strings || getStrings();
  el.textContent = '';
  const recents = orderedRecents(state, 8);
  if (!recents.length) { el.hidden = true; return el; }   // graceful — nothing launched yet
  el.hidden = false;

  const title = document.createElement('h2');
  title.className = 'c-apps-recents__title';
  title.textContent = strings.recentlyUsed || 'Recently used';
  el.append(title);

  const strip = document.createElement('div');
  strip.className = 'c-apps-recents__strip';
  for (const app of recents) {
    // plain buttons — role="listitem" would override button semantics for SRs (#106③ precedent)
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = 'c-apps-recents__item';
    tile.setAttribute('aria-label', app.name || strings.app || 'App');
    tile.append(createAppIcon({ src: app.icon, name: app.name, size: 56 }));
    const nm = document.createElement('span');
    nm.className = 'c-apps-recents__name';
    nm.textContent = app.name || '';
    tile.append(nm);
    if (opts.onLaunch) tile.addEventListener('click', () => opts.onLaunch(app));
    strip.append(tile);
  }
  el.append(strip);
  return el;
}

function createAppsRecents(state, opts = {}) {
  const el = document.createElement('section');
  el.className = 'c-apps-recents';
  renderAppsRecents(el, state, opts);
  return el;
}

/* ---- src/components/apps-header.js ---- */
/**
 * c-apps-header — the Apps screen header (spec §2.1): a search field, a self-syncing
 * list⇄grid layout toggle, and the blue "Explore Spixi Mini Apps" discover banner.
 * The toggle shows the layout you'll switch TO and reports the new layout via
 * onToggleLayout(next); the demo wires that to setAppsLayout.
 *
 * createAppsHeader({ layout, strings, discover, onQuery, onToggleLayout, onExplore }) → div
 */




function createAppsHeader({ layout = 'list', strings = getStrings(), discover = false, exploreImage = null, onQuery, onToggleLayout, onExplore } = {}) {
  const el = document.createElement('div');
  el.className = 'c-apps-header';

  /* search + layout toggle */
  const row = document.createElement('div');
  row.className = 'c-apps-header__row';
  row.append(createSearchField({
    placeholder: strings.searchApps || 'Find installed apps',
    onInput: (v) => { if (onQuery) onQuery(v); },
    strings,
  }));

  const toggle = document.createElement('button');
  toggle.type = 'button';
  toggle.className = 'c-apps-header__toggle';
  let current = layout === 'grid' ? 'grid' : 'list';
  const applyToggle = (lay) => {
    current = lay;
    toggle.dataset.layout = lay;
    const target = lay === 'list' ? 'grid' : 'list';        // clicking switches to this
    toggle.textContent = '';
    toggle.append(icon(target === 'grid' ? 'apps' : 'menu-2', { size: 22 }));
    toggle.setAttribute('aria-label', target === 'grid'
      ? (strings.viewAsGrid || 'View as grid')
      : (strings.viewAsList || 'View as list'));
  };
  applyToggle(current);
  toggle.addEventListener('click', () => {
    const next = current === 'grid' ? 'list' : 'grid';
    applyToggle(next);
    if (onToggleLayout) onToggleLayout(next);
  });
  row.append(toggle);
  el.append(row);

  /* explore / discover banner (parked until the feed lands, §2.4) */
  const banner = document.createElement('button');
  banner.type = 'button';
  banner.className = 'c-apps-explore';
  const btext = document.createElement('span');
  btext.className = 'c-apps-explore__text';
  const bt1 = document.createElement('span');
  bt1.className = 'c-apps-explore__title';
  bt1.textContent = strings.exploreTitle || 'Not sure where to start?';
  const bt2 = document.createElement('span');
  bt2.className = 'c-apps-explore__cta';
  const ctaText = strings.exploreCta || 'Explore Spixi Mini Apps';
  bt2.append(document.createTextNode(ctaText), icon('arrow-right', { size: 18 }));
  btext.append(bt1, bt2);
  banner.append(btext);
  if (exploreImage) {
    const illo = document.createElement('img');
    illo.className = 'c-apps-explore__illo';
    illo.src = exploreImage;
    illo.alt = '';
    banner.append(illo);
  }
  banner.setAttribute('aria-label', bt1.textContent + ' ' + ctaText);
  banner.addEventListener('click', () => { if (onExplore) onExplore(); });
  el.append(banner);

  return el;
}

/* ---- src/components/apps-add.js ---- */
/**
 * c-apps-add — the "Add mini app" surface (spec §2.2), now combined with Discover
 * (Damir: "combine discover with adding custom link"). Three method TILES — Paste
 * link (reveals an inline URL field → `ixian:fetch:url`), Scan QR (`ixian:quickscan`),
 * From file (`ixian:selectAppFile`) — a trust banner, and the embedded Discover
 * section (reuses c-apps-discover, parked until the apps.spixi.io feed lands).
 *
 * createAppsAdd({ strings, onFetchUrl(url), onScan, onPickFile, onCategory,
 *                 onBrowseWeb, onLearnBuild, onOpenApp }) → view
 *   onBrowseWeb  — parked-Discover fallback: opens the web directory (via external-link confirm)
 *   onLearnBuild — developer CTA: "anyone can build a mini app" → resources page (same confirm)
 *   onOpenApp    — a live-Discover card/tile tap → that app's details
 * Free fns (#44): setAddUrl(el, url) reveals + fills the field (QR → setScannedData);
 *                 setAddError(el, msg) shows the inline invalid-URL error;
 *                 setAddDiscoverFeed(el, feed, opts) — shell fetched the directory (#131):
 *                 flips the embedded Discover live (parsed via apps-feed.js).
 */





function createAppsAdd({ strings = getStrings(), onFetchUrl, onScan, onPickFile, onCategory, onBrowseWeb, onLearnBuild, onOpenApp } = {}) {
  const el = document.createElement('div');
  el.className = 'c-apps-add';

  /* lead */
  const lead = document.createElement('p');
  lead.className = 'c-apps-add__lead';
  lead.textContent = strings.addLead
    || 'Add a mini app from a link, a QR code, or a file — or explore the directory below.';
  el.append(lead);

  /* URL field (revealed by the Paste-link tile / a QR scan) */
  const field = document.createElement('div');
  field.className = 'c-apps-add__field';
  field.hidden = true;
  const label = document.createElement('label');
  label.className = 'c-apps-add__label';
  label.textContent = strings.appUrlLabel || 'Mini app link';
  label.setAttribute('for', 'apps-add-url');
  const input = document.createElement('input');
  input.type = 'url';
  input.id = 'apps-add-url';
  input.className = 'c-apps-add__input';
  input.placeholder = strings.appUrlPlaceholder || 'https://…';
  input.setAttribute('aria-label', strings.appUrlLabel || 'Mini app link');
  const err = document.createElement('span');
  err.className = 'c-apps-add__error';
  err.hidden = true;
  err.setAttribute('role', 'alert');
  input.addEventListener('input', () => { err.hidden = true; input.removeAttribute('aria-invalid'); });
  const getBtn = createButton({
    label: strings.getFromUrl || 'Get app', type: 'fill', size: 56, width: 'full',
    icon: icon('download', { size: 20 }),
    onClick: () => { if (onFetchUrl) onFetchUrl(input.value.trim()); },
  });
  field.append(label, input, err, getBtn);

  /* method tiles */
  const methods = document.createElement('div');
  methods.className = 'c-apps-add__methods';
  methods.setAttribute('role', 'group');
  methods.setAttribute('aria-label', strings.addMethods || 'Ways to add a mini app');
  const method = (glyph, text, onClick) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'c-apps-add__method';
    const ic = document.createElement('span');
    ic.className = 'c-apps-add__method-icon';
    ic.append(icon(glyph, { size: 24 }));
    const t = document.createElement('span');
    t.className = 'c-apps-add__method-label';
    t.textContent = text;
    b.append(ic, t);
    b.addEventListener('click', onClick);
    return b;
  };
  methods.append(
    method('link', strings.pasteLink || 'Paste link', () => { field.hidden = false; input.focus(); }),
    method('scan', strings.scanQr || 'Scan QR', () => { if (onScan) onScan(); }),
    method('file-isr', strings.pickFile || 'From file', () => { if (onPickFile) onPickFile(); }),
  );
  el.append(methods, field);

  /* trust banner */
  const info = document.createElement('div');
  info.className = 'c-apps-add__info';
  info.append(icon('info-circle', { size: 20 }));
  const itext = document.createElement('span');
  itext.textContent = strings.miniAppInfo
    || 'Mini apps are lightweight web apps that run securely inside Spixi. Only add apps from sources you trust.';
  info.append(itext);
  el.append(info);

  /* Discover (embedded, reuses c-apps-discover; parked until the feed lands) */
  const disc = document.createElement('section');
  disc.className = 'c-apps-add__discover';
  const dTitle = document.createElement('h2');
  dTitle.className = 'c-apps-add__sectiontitle';
  dTitle.textContent = strings.discover || 'Discover';
  disc.append(dTitle, createAppsDiscover({ strings, ready: false, onCategory, onBrowseWeb, onOpen: onOpenApp }));
  el.append(disc);

  /* developer CTA — anyone can build a mini app (quiet, page bottom; Damir #128③) */
  if (onLearnBuild) {
    const dev = document.createElement('div');
    dev.className = 'c-apps-add__dev';
    dev.append(icon('rocket', { size: 20 }));   // ⚠ 'code' glyph not in the icon export yet — swap when Damir exports it (glyph-sweep list)
    const dtext = document.createElement('span');
    dtext.className = 'c-apps-add__dev-text';
    dtext.textContent = strings.devLead
      || 'Anyone can build a mini app — web-friendly tech, no backend to run.';
    dev.append(dtext);
    const learn = document.createElement('button');
    learn.type = 'button';
    learn.className = 'c-apps-add__dev-link';
    learn.textContent = strings.devLearn || 'Learn how';
    learn.addEventListener('click', onLearnBuild);
    dev.append(learn);
    el.append(dev);
  }

  return el;
}

/** Reveal + populate the URL field (used by the QR-scan callback → setScannedData). */
function setAddUrl(el, url) {
  const input = el && el.querySelector('.c-apps-add__input');
  const field = el && el.querySelector('.c-apps-add__field');
  if (field) field.hidden = false;
  if (input) { input.value = url == null ? '' : String(url); input.focus(); }
}

/** Shell fetched the directory feed (#131) — flip the embedded Discover live. */
function setAddDiscoverFeed(el, feed, opts = {}) {
  const disc = el && el.querySelector('.c-apps-discover');
  if (disc) setDiscoverFeed(disc, feed, opts);
  return el;
}

/** Show an inline invalid-URL error (the shell's `showUrlError` hook). */
function setAddError(el, msg) {
  if (!el) return;
  const field = el.querySelector('.c-apps-add__field');
  const errEl = el.querySelector('.c-apps-add__error');
  const input = el.querySelector('.c-apps-add__input');
  if (field) field.hidden = false;
  if (!errEl) return;
  errEl.textContent = msg || 'That doesn’t look like a valid mini-app link.';
  errEl.hidden = false;
  if (input) input.setAttribute('aria-invalid', 'true');
}

/* ---- src/components/apps-details.js ---- */
/**
 * c-app-details — mini-app details / installer (spec §2.3; premiumised per Damir 2026-07-04).
 * Hero cover + header (icon overlaps the cover; name/publisher/verified sit BELOW it —
 * installed apps get a compact **Open pill** in the header, App-Store style), screenshots
 * strip (Store order: artwork before words), description (clamped + Read more),
 * capability CHIPS (tap-to-explain), meta rows, trust line, related tiles, an Advanced
 * disclosure for the dev install-URL. Actions: NOT installed → sticky full-width Install
 * bar (conversion CTA); installed → NO sticky bar — Open is the header pill, Uninstall is
 * a quiet destructive text-row at the page bottom (confirm modal). Install confirm =
 * c-modal (chips tap-to-explain + source); on confirm the Install button morphs inline
 * (loading → success check → re-render as installed).
 *
 * createAppDetails({ app, strings, host, onInstall(app,ctrl), onUninstall, onLaunch,
 *                    onReport, onInstalled, onCopyUrl }) → view
 *   onInstall(app, { done, fail }) — the caller runs the real install and calls done()/fail().
 */










const APP_CAP_LABELS = {
  MultiUser: 'Multi-user',
  Authentication: 'Sign in as you',
  TransactionSigning: 'Sign transactions',
  RegisteredNamesManagement: 'Manage names',
  Storage: 'Local storage',
};
const APP_CAP_EXPLAIN = {
  MultiUser: 'Runs shared sessions so you can use this app together with friends.',
  Authentication: 'Can prove who you are to this app using your Spixi identity — without a password.',
  TransactionSigning: 'Can ask you to approve IXI payments. You always confirm each one yourself.',
  RegisteredNamesManagement: 'Can read and manage your registered Ixian names.',
  Storage: 'Can save data on your device so it remembers things between sessions.',
};

function normalizeCaps(caps) {
  let arr = [];
  if (Array.isArray(caps)) arr = caps.slice();
  else if (typeof caps === 'string') arr = caps.split(',').map((s) => s.trim());
  else if (caps && typeof caps === 'object') arr = Object.keys(caps).filter((k) => caps[k]);
  return arr.filter((c) => c && c !== 'SingleUser');
}
function capLabel(c, strings) { return strings['cap_' + c] || APP_CAP_LABELS[c] || c; }
function capExplain(c, strings) { return strings['capx_' + c] || APP_CAP_EXPLAIN[c] || ''; }

/** Hero cover (App-Store style). app.cover → the artwork; otherwise the app's own
 *  icon blurred behind its deterministic hue gradient (reuses the c-app-icon hue
 *  recipe so an app's hero always matches its tile). A bottom scrim keeps the
 *  overlapping icon + name legible over bright covers. */
function appHero(app) {
  const hero = document.createElement('div');
  hero.className = 'c-app-hero';
  if (app.cover) {
    const art = document.createElement('img');
    art.className = 'c-app-hero__art';
    art.src = app.cover; art.alt = '';
    hero.append(art);
  } else {
    const hue = hashHue(app.name || 'app');
    hero.dataset.placeholder = '';
    hero.style.setProperty('--ai-h1', hue);
    hero.style.setProperty('--ai-h2', (hue + 40) % 360);
    if (app.icon) {                              // blurred copy of the icon adds depth over the gradient
      const art = document.createElement('img');
      art.className = 'c-app-hero__art';
      art.dataset.blur = '';
      art.src = app.icon; art.alt = '';
      hero.append(art);
    }
  }
  const scrim = document.createElement('div');
  scrim.className = 'c-app-hero__scrim';
  hero.append(scrim);
  return hero;
}

/** Titled section wrapper (reused by permissions / screenshots / related). */
function detailsSection(title) {
  const sec = document.createElement('section');
  sec.className = 'c-app-details__section';
  if (title) {
    const h = document.createElement('h2');
    h.className = 'c-app-details__sectiontitle';
    h.textContent = title;
    sec.append(h);
  }
  return sec;
}

/** Screenshot gallery — horizontal scroll-snap strip (rendered only when the app
 *  ships screenshots; graceful omit otherwise, pending the BE preview payload). */
function screenshotStrip(shots, strings) {
  const sec = detailsSection(strings.preview || 'Preview');
  const strip = document.createElement('div');
  strip.className = 'c-app-shots';
  strip.setAttribute('role', 'region');                  // labelled scroll region (a11y scroll-container pattern)
  strip.tabIndex = 0;                                    // focusable so the strip scrolls with arrow keys
  strip.setAttribute('aria-label', strings.preview || 'Preview');
  shots.forEach((src, i) => {
    const img = document.createElement('img');
    img.className = 'c-app-shots__item';
    img.loading = 'lazy';
    img.src = src;
    img.alt = (strings.screenshot || 'Screenshot') + ' ' + (i + 1) + ' / ' + shots.length;   // region has readable content
    strip.append(img);
  });
  sec.append(strip);
  return sec;
}

/** "More mini apps" — compact tappable tiles (reuse c-app-icon). Each opens that
 *  app's details via onOpen. Rendered only when the app carries related entries. */
function relatedStrip(related, strings, onOpen) {
  const sec = detailsSection(strings.moreApps || 'More mini apps');
  const strip = document.createElement('div');
  strip.className = 'c-app-related';
  for (const rel of related) {
    // plain buttons — role="listitem" would override button semantics for SRs (#106③ precedent)
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = 'c-app-related__item';
    tile.append(createAppIcon({ src: rel.icon, name: rel.name, size: 56 }));
    const nm = document.createElement('span');
    nm.className = 'c-app-related__name';
    nm.textContent = rel.name || '';
    tile.append(nm);
    if (onOpen) tile.addEventListener('click', () => onOpen(rel));
    strip.append(tile);
  }
  sec.append(strip);
  return sec;
}

/** Capability chips (reuse c-chip readonly). explain:true → tappable chips that reveal
 *  a plain-language line beneath (the install-confirm "tap to explain"). */
function capChips(caps, strings, { explain = false, reserve = false } = {}) {
  const wrap = document.createElement('div');
  wrap.className = 'c-app-caps';
  const row = document.createElement('div');
  row.className = 'c-app-caps__row';
  let line;
  // explain → tappable chips that fill a plain-language line. reserve (modal only) pins
  // the line's height so revealing text doesn't resize the dialog (flicker). In the details
  // page there's no modal to flicker, so the line just grows.
  if (explain) {
    line = document.createElement('p');
    line.className = 'c-app-caps__explain';
    line.setAttribute('role', 'status');                 // announce chip-tap explanations to SRs (polite)
    if (reserve) line.dataset.reserve = '';
  }
  for (const c of caps) {
    if (explain) {
      row.append(createChip({
        label: capLabel(c, strings), icon: 'shield-lock', size: 'small',
        onClick: () => { line.textContent = capExplain(c, strings); },
      }));
    } else {
      row.append(createChip({ label: capLabel(c, strings), icon: 'shield-lock', size: 'small', readonly: true }));
    }
  }
  wrap.append(row);
  if (explain) wrap.append(line);
  return wrap;
}

function createAppDetails({ app = {}, strings = getStrings(), host, onInstall, onUninstall, onLaunch, onReport, onInstalled, onCopyUrl, onOpen } = {}) {
  const el = document.createElement('div');
  el.className = 'c-app-details';
  const caps = normalizeCaps(app.capabilities);

  /* hero cover + overlapping header */
  el.append(appHero(app));
  const header = document.createElement('div');
  header.className = 'c-app-details__header';
  header.append(createAppIcon({ src: app.icon, name: app.name, size: 72 }));
  const htext = document.createElement('div');
  htext.className = 'c-app-details__heading';
  const name = document.createElement('h1');
  name.className = 'c-app-details__name';
  name.textContent = app.name || '';
  htext.append(name);
  const pubrow = document.createElement('div');
  pubrow.className = 'c-app-details__pubrow';
  const publisher = app.publisher || app.creator;   // list row calls it "creator"; bridge init calls it "publisher"
  if (publisher) {
    const pub = document.createElement('span');
    pub.className = 'c-app-details__publisher';
    pub.textContent = publisher;
    pubrow.append(pub);
  }
  if (app.verified) pubrow.append(createBadge({ label: strings.verified || 'Verified', type: 'accent', icon: 'checks' }));
  htext.append(pubrow);
  header.append(htext);
  if (app.installed) {
    // installed → compact Open pill in the header (App-Store pattern); no sticky bar
    const openPill = createButton({ label: strings.openApp || 'Open', type: 'fill', size: 44,
      icon: icon('player-play', { size: 18 }), onClick: () => { if (onLaunch) onLaunch(app); } });
    openPill.classList.add('c-app-details__openpill');
    header.append(openPill);
  }
  el.append(header);

  /* screenshots first — artwork sells before words (Store order; graceful omit without previews) */
  if (Array.isArray(app.screenshots) && app.screenshots.length) {
    el.append(screenshotStrip(app.screenshots, strings));
  }

  /* description (clamped + Read more) */
  if (app.description) {
    const desc = document.createElement('p');
    desc.className = 'c-app-details__desc';
    desc.dataset.clamped = '';
    desc.textContent = app.description;
    const more = document.createElement('button');
    more.type = 'button';
    more.className = 'c-app-details__more';
    more.textContent = strings.readMore || 'Read more';
    more.setAttribute('aria-expanded', 'false');
    more.addEventListener('click', () => {
      const clamped = desc.dataset.clamped !== undefined;
      if (clamped) delete desc.dataset.clamped; else desc.dataset.clamped = '';
      more.textContent = clamped ? (strings.readLess || 'Read less') : (strings.readMore || 'Read more');
      more.setAttribute('aria-expanded', clamped ? 'true' : 'false');
    });
    // only show "Read more" when the text actually clamps (overflows the line-clamp).
    // measured after layout — the view isn't in the DOM at build time.
    more.hidden = true;
    const revealIfClamped = () => { more.hidden = !(desc.scrollHeight > desc.clientHeight + 1); };
    if (typeof ResizeObserver !== 'undefined') {
      // stays observing (rotation/resize can change the clamp); syncs only while STILL
      // clamped so it never fights an expanded state. GC'd with the view (self-referential).
      const ro = new ResizeObserver(() => {
        if (desc.clientHeight > 0 && desc.dataset.clamped !== undefined) revealIfClamped();
      });
      ro.observe(desc);
    } else if (typeof requestAnimationFrame !== 'undefined') {
      requestAnimationFrame(revealIfClamped);
    }
    el.append(desc, more);
  }

  /* capability chips (display) */
  if (caps.length) {
    const sec = document.createElement('section');
    sec.className = 'c-app-details__section';
    const h = document.createElement('h2');
    h.className = 'c-app-details__sectiontitle';
    h.textContent = strings.permissions || 'Permissions';
    sec.append(h, capChips(caps, strings, { explain: true }));   // tap a chip → plain-language line (grows; no modal to flicker)
    el.append(sec);
  }

  /* meta rows */
  const meta = document.createElement('div');
  meta.className = 'c-app-details__meta';
  const metaRow = (label, value) => {
    if (value == null || value === '') return;
    const r = document.createElement('div');
    r.className = 'c-app-details__metarow';
    const l = document.createElement('span');
    l.className = 'c-app-details__metalabel';
    l.textContent = label;
    const v = document.createElement('span');
    v.className = 'c-app-details__metavalue';
    v.textContent = String(value);
    r.append(l, v);
    meta.append(r);
  };
  metaRow(strings.developer || 'Developer', publisher);
  metaRow(strings.version || 'Version', app.version);
  metaRow(strings.size || 'Size', app.size);
  if (meta.childNodes.length) el.append(meta);

  /* trust line */
  const trust = document.createElement('p');
  trust.className = 'c-app-details__trust';
  trust.append(icon('shield-lock', { size: 16 }));
  const tt = document.createElement('span');
  tt.textContent = strings.runsSecurely || 'Runs securely inside Spixi — nothing leaves your device without your permission.';
  trust.append(tt);
  el.append(trust);

  /* more mini apps (graceful — only when related entries are provided) */
  if (Array.isArray(app.related) && app.related.length) {
    el.append(relatedStrip(app.related, strings, onOpen));
  }

  /* Advanced disclosure — dev install URL + copy + app id */
  if (app.url || app.id) {
    const adv = document.createElement('details');
    adv.className = 'c-app-details__advanced';
    const sum = document.createElement('summary');
    sum.textContent = strings.advanced || 'Advanced';
    adv.append(sum);
    if (app.url) {
      const urlRow = document.createElement('div');
      urlRow.className = 'c-app-details__url';
      const u = document.createElement('span');
      u.className = 'c-app-details__urlvalue';
      u.textContent = app.url;
      const copyBtn = document.createElement('button');
      copyBtn.type = 'button';
      copyBtn.className = 'c-app-details__copy';
      copyBtn.setAttribute('aria-label', strings.copyUrl || 'Copy link');
      copyBtn.append(icon('copy', { size: 18 }));
      copyBtn.addEventListener('click', () => {
        if (onCopyUrl) onCopyUrl(app.url);
        showToast({ text: strings.copied || 'Copied', tone: 'success', host });
      });
      urlRow.append(u, copyBtn);
      adv.append(urlRow);
      const shareHint = document.createElement('p');
      shareHint.className = 'c-app-details__sharehint';
      shareHint.textContent = strings.shareHint
        || 'Share this link with anyone — they can add the app in Spixi from it.';
      adv.append(shareHint);
    }
    if (app.id) {
      const idRow = document.createElement('div');
      idRow.className = 'c-app-details__metarow';
      const l = document.createElement('span'); l.className = 'c-app-details__metalabel'; l.textContent = strings.appId || 'App ID';
      const v = document.createElement('span'); v.className = 'c-app-details__metavalue'; v.textContent = String(app.id);
      idRow.append(l, v); adv.append(idRow);
    }
    el.append(adv);
  }

  /* actions — installed: quiet destructive Uninstall row at the very bottom (scrolled-to,
     not sticky; Open lives as the header pill + list tap-to-launch). Not-installed: the
     sticky Install bar stays — it's a conversion CTA and the page's single action. */
  if (app.installed) {
    const danger = document.createElement('div');
    danger.className = 'c-app-details__danger';
    danger.append(createButton({ label: strings.uninstall || 'Uninstall', type: 'text', size: 44, width: 'full', intent: 'destructive',
      icon: icon('trash', { size: 20 }), onClick: () => openUninstallConfirm({ app, host, strings, onUninstall }) }));
    el.append(danger);
  } else {
    const actions = document.createElement('div');
    actions.className = 'c-app-details__actions';
    const installBtn = createButton({ label: strings.install || 'Install', type: 'fill', size: 56, width: 'full',
      icon: icon('download', { size: 20 }),
      onClick: () => openInstallConfirm({ app, caps, host, strings, onInstall, installBtn, onInstalled }) });
    actions.append(installBtn);
    el.append(actions);
  }
  return el;
}

/* —— install confirm = c-modal (rich content slot) → inline button morph —— */
function openInstallConfirm({ app, caps, host, strings, onInstall, installBtn, onInstalled }) {
  const content = document.createElement('div');
  content.className = 'c-app-install';
  // identity anchor — the app's icon (same deterministic hue as its tile/hero) so the
  // dialog visually reads as THIS app, Store-install style. Reuses c-app-icon, no new assets.
  const idrow = document.createElement('div');
  idrow.className = 'c-app-install__icon';
  idrow.append(createAppIcon({ src: app.icon, name: app.name, size: 48 }));
  content.append(idrow);
  if (caps.length) {
    const lead = document.createElement('p');
    lead.className = 'c-app-install__lead';
    lead.textContent = strings.installLead || 'This app can do the following — tap any to learn more:';
    content.append(lead, capChips(caps, strings, { explain: true, reserve: true }));
  }
  if (app.url) {
    const src = document.createElement('p');
    src.className = 'c-app-install__src';
    // domain, not the full URL — the dialog is a decision moment, the domain is the trust
    // signal; the full URL stays one tap away (details → Advanced). Unparseable → full string.
    let from = app.url;
    try { from = new URL(app.url).hostname || app.url; } catch { /* keep full string */ }
    src.textContent = (strings.source || 'Source: ') + from;
    src.title = app.url;
    content.append(src);
  }
  openModal(createModal({
    title: (strings.installTitle || 'Install {name}?').split('{name}').join(app.name || 'this app'),
    content, role: 'dialog', host,
    actions: [
      { label: strings.cancel || 'Cancel', type: 'text', autofocus: true },
      { label: strings.install || 'Install', type: 'fill', onClick: () => runInstall({ app, host, strings, onInstall, installBtn, onInstalled }) },
    ],
  }));
}

/** Inline install morph: button → loading → success check → onInstalled (re-render installed). */
function runInstall({ app, host, strings, onInstall, installBtn, onInstalled }) {
  if (!installBtn) { if (onInstall) onInstall(app, { done: () => {}, fail: () => {} }); return; }
  setLoading(installBtn, true);
  const done = () => {
    setLoading(installBtn, false);
    setSuccess(installBtn, { label: strings.installed || 'Installed' });
    if (onInstalled) setTimeout(() => onInstalled(app), 1200);   // re-render as installed after the check
  };
  const fail = () => { setLoading(installBtn, false); showAppInstallFailed({ host, strings }); };
  if (onInstall) onInstall(app, { done, fail }); else done();
}

function openUninstallConfirm({ app, host, strings, onUninstall }) {
  openModal(createModal({
    title: strings.uninstallTitle || 'Uninstall app?',
    body: (strings.uninstallBody || 'This removes {name} from your device.').split('{name}').join(app.name || 'this app'),
    role: 'alertdialog', host,
    actions: [
      { label: strings.cancel || 'Cancel', type: 'text', autofocus: true },
      { label: strings.uninstall || 'Uninstall', type: 'fill', intent: 'destructive', onClick: () => { if (onUninstall) onUninstall(app); } },
    ],
  }));
}

/* —— bridge-driven progress states (kept for the C# showInstalling/…Failed hooks) —— */
function showAppInstalling({ host, strings = getStrings(), name = '' } = {}) {
  const m = createModal({
    title: strings.installing || 'Installing…',
    body: (strings.installingBody || 'Installing {name}…').split('{name}').join(name || 'the app'),
    host, escDismiss: false,
  });
  openModal(m);
  return m;
}
function showAppInstalled({ host, strings = getStrings(), onView } = {}) {
  openModal(createModal({
    title: strings.installedTitle || 'Installed', body: strings.installedBody || 'The mini app is ready to use.',
    host, actions: [{ label: strings.viewApp || 'View app', type: 'fill', autofocus: true, onClick: () => { if (onView) onView(); } }],
  }));
}
function showAppInstallFailed({ host, strings = getStrings() } = {}) {
  openModal(createModal({
    title: strings.failedTitle || 'Install failed', body: strings.failedBody || 'Something went wrong installing this app. Please try again.',
    role: 'alertdialog', host, actions: [{ label: strings.ok || 'OK', type: 'fill', autofocus: true }],
  }));
}
function showAppRemoved({ host, strings = getStrings() } = {}) {
  openModal(createModal({
    title: strings.removedTitle || 'App removed', body: strings.removedBody || 'The mini app was uninstalled.',
    host, actions: [{ label: strings.ok || 'OK', type: 'fill', autofocus: true }],
  }));
}

/* ---- src/components/apps-discover.js ---- */
/**
 * c-apps-discover — the Discover view (spec §2.4), now LIVE-capable (DECISIONS #131):
 * `setDiscoverFeed(el, feed, opts)` renders a parsed apps.spixi.io feed (apps-feed.js) —
 * Featured strip + card grid, category chips filtering client-side, installed apps
 * badged and routed to the SAME onOpen (details resolves installed → Open pill).
 *
 * Without a feed it stays PARKED: chips + "coming soon" + the `onBrowseWeb` fallback
 * button (the web directory exists today, so Explore never dead-ends; shell routes the
 * tap through the external-link confirm, like every outbound link).
 *
 * The component never fetches — the SHELL owns transport (direct fetch where the WebView
 * allows it; bridge proxy otherwise — iOS WKWebView whitelist question, §9) and calls
 * setDiscoverFeed on success. Fetch failure → simply don't call it (parked view stands).
 *
 * createAppsDiscover({ strings, categories, ready, onCategory, onBrowseWeb, onOpen }) → view
 * setDiscoverFeed(el, feed, { strings, onCategory, onOpen }) — free fn (#44)
 */







const APP_CATEGORIES = ['All', 'AI', 'Games', 'IoT', 'Tools', 'Dev Tools'];

function chipRow(categories, strings, onPick) {
  const cats = document.createElement('div');
  cats.className = 'c-apps-discover__cats';
  cats.setAttribute('role', 'group');
  cats.setAttribute('aria-label', strings.categories || 'Categories');
  categories.filter(Boolean).forEach((cat, i) => {
    cats.append(createChip({
      label: cat, selected: i === 0,
      onClick: (e) => {
        for (const c of cats.children) setChipSelected(c, c === e.currentTarget);
        onPick(cat);
      },
      strings,
    }));
  });
  return cats;
}

/** One discover card — icon · name+publisher · Installed badge (when installed). */
function discoverCard(app, strings, onOpen) {
  const card = document.createElement('button');
  card.type = 'button';
  card.className = 'c-apps-discover__card';
  card.append(createAppIcon({ src: app.icon, name: app.name, size: 48 }));
  const text = document.createElement('span');
  text.className = 'c-apps-discover__cardtext';
  const nm = document.createElement('span');
  nm.className = 'c-apps-discover__cardname';
  nm.textContent = app.name || '';
  text.append(nm);
  if (app.publisher) {
    const pub = document.createElement('span');
    pub.className = 'c-apps-discover__cardpub';
    pub.textContent = app.publisher;
    text.append(pub);
  }
  card.append(text);
  if (app.installed) card.append(createBadge({ label: strings.installed || 'Installed', type: 'accent', icon: 'check' }));
  if (onOpen) card.addEventListener('click', () => onOpen(app));
  return card;
}

/** Render/refresh the live sections (featured + grid) for a category. */
function renderLive(el, feed, category, { strings = getStrings(), onOpen } = {}) {
  const host = el.querySelector('.c-apps-discover__live');
  if (!host) return;
  host.textContent = '';
  const all = feed.apps || [];
  const inCat = (a) => category === 'All' || !category || a.category === category;

  const featured = all.filter((a) => a.featured && inCat(a));
  if (featured.length) {
    const ftitle = document.createElement('h3');
    ftitle.className = 'c-apps-discover__sectiontitle';
    ftitle.textContent = strings.featured || 'Featured';
    const strip = document.createElement('div');
    strip.className = 'c-apps-discover__featured';
    for (const app of featured) {
      // plain buttons — role="listitem" would override button semantics for SRs (#106③)
      const tile = document.createElement('button');
      tile.type = 'button';
      tile.className = 'c-apps-discover__ftile';
      tile.append(createAppIcon({ src: app.icon, name: app.name, size: 56 }));
      const nm = document.createElement('span');
      nm.className = 'c-apps-discover__fname';
      nm.textContent = app.name || '';
      tile.append(nm);
      if (app.installed) tile.dataset.installed = '';
      if (onOpen) tile.addEventListener('click', () => onOpen(app));
      strip.append(tile);
    }
    host.append(ftitle, strip);
  }

  const rest = all.filter(inCat);
  if (rest.length) {
    const grid = document.createElement('div');
    grid.className = 'c-apps-discover__grid';
    for (const app of rest) grid.append(discoverCard(app, strings, onOpen));
    host.append(grid);
  } else {
    const empty = document.createElement('p');
    empty.className = 'c-apps-discover__empty';
    empty.setAttribute('role', 'note');
    empty.textContent = (strings.discoverEmptyCat || 'No {cat} apps yet — check back soon.')
      .split('{cat}').join(category || '');
    host.append(empty);
  }
}

function createAppsDiscover({ strings = getStrings(), categories = APP_CATEGORIES, ready = false, onCategory, onBrowseWeb, onOpen } = {}) {
  const el = document.createElement('div');
  el.className = 'c-apps-discover';
  if (!ready) el.dataset.parked = '';

  el.append(chipRow(categories, strings, (cat) => {
    if (el.dataset.parked === undefined) renderLive(el, el._feed || { apps: [] }, cat, { strings, onOpen: el._onOpen });
    el._category = cat;
    if (onCategory) onCategory(cat);
  }));
  el._category = categories[0] || 'All';

  if (ready) {
    const live = document.createElement('div');
    live.className = 'c-apps-discover__live';
    el.append(live);
  } else {
    const soon = document.createElement('div');
    soon.className = 'c-apps-discover__soon';
    soon.setAttribute('role', 'note');
    soon.append(icon('rocket', { size: 32 }));
    const t = document.createElement('p');
    t.textContent = strings.discoverSoon
      || 'The Spixi Mini App directory is coming soon — you’ll browse and install featured apps right here.';
    soon.append(t);
    if (onBrowseWeb) {                                   // fallback — the web directory exists today
      soon.append(createButton({
        label: strings.browseWeb || 'Browse on the web', type: 'outline', size: 44,
        icon: icon('arrow-right', { size: 18 }), iconPosition: 'trailing',
        onClick: onBrowseWeb,
      }));
    }
    el.append(soon);
  }
  return el;
}

/** Free fn (#44): feed arrived — flip a parked view live (or refresh a live one) and
 *  render. `feed` = parseAppsFeed output; its categories rebuild the chip row when they
 *  differ from what's shown. Keeps the current category selection when still present. */
function setDiscoverFeed(el, feed, { strings = getStrings(), onCategory, onOpen } = {}) {
  if (!el || !feed) return el;
  el._feed = feed;
  el._onOpen = onOpen;
  delete el.dataset.parked;

  const soon = el.querySelector('.c-apps-discover__soon');
  if (soon) soon.remove();
  if (!el.querySelector('.c-apps-discover__live')) {
    const live = document.createElement('div');
    live.className = 'c-apps-discover__live';
    el.append(live);
  }
  if (feed.categories && feed.categories.length) {
    const current = el.querySelector('.c-apps-discover__cats');
    const shown = current ? [...current.querySelectorAll('.c-chip')].map((c) => c.textContent) : [];
    if (shown.join('␀') !== feed.categories.join('␀')) {
      const fresh = chipRow(feed.categories, strings, (cat) => {
        renderLive(el, el._feed, cat, { strings, onOpen });
        el._category = cat;
        if (onCategory) onCategory(cat);
      });
      if (current) current.replaceWith(fresh); else el.prepend(fresh);
      el._category = feed.categories[0];
    }
  }
  if (!feed.categories || !feed.categories.includes(el._category)) el._category = 'All';
  renderLive(el, feed, el._category, { strings, onOpen });
  return el;
}

/* ---- src/components/apps-feed.js ---- */
/**
 * apps-feed — the apps.spixi.io directory CONTRACT (DECISIONS #128④; endpoint confirmed
 * by Damir 2026-07-05): GET https://apps.spixi.io/data/apps.json — CORS `*`, max-age=600,
 * static GitHub Pages. Pure mapping, NO fetching here — the shell owns transport
 * (direct fetch where the WebView allows it; bridge proxy otherwise — the iOS WKWebView
 * http/https whitelist question is logged for BE, §9).
 *
 * Feed entry shape (site repo: ixian-platform/Spixi-Mini-Apps-Website):
 *   { id, name, publisher, description, category, featured, version,
 *     icon (png url), spixiUrl (install url), github, singleUser, multiUser }
 * Top level: { apps: [...], categories: ['All','AI','Games','IoT','Tools','Dev Tools'] }
 * (categories match c-apps-discover's built-in set — feed wins when present).
 *
 * Missing vs the details model — site-schema WISHLIST (Damir owns the repo):
 *   cover, screenshots[], related[], size, verified.
 *
 * feedEntryToApp(entry, state) → app (our model; `installed` resolved against state.apps
 *   so Discover can flag installed apps and route to the installed details, Damir ask)
 * parseAppsFeed(json, state) → { apps, categories } (json string or object; throws on
 *   malformed JSON — caller guards and falls back to the parked view)
 */

const APPS_FEED_URL = 'https://apps.spixi.io/data/apps.json';

function feedEntryToApp(entry, state) {
  if (!entry || typeof entry !== 'object' || entry.id == null) return null;
  const installed = !!(state && (state.apps || []).some((a) => a && a.id === entry.id));
  const caps = [];
  if (entry.multiUser) caps.push('MultiUser');
  return {
    id: entry.id,
    name: String(entry.name || ''),
    publisher: entry.publisher || '',
    description: entry.description || '',
    category: entry.category || '',
    featured: !!entry.featured,
    version: entry.version || '',
    icon: entry.icon || null,
    url: entry.spixiUrl || '',
    github: entry.github || '',
    capabilities: caps,
    installed,
  };
}

function parseAppsFeed(json, state) {
  const data = typeof json === 'string' ? JSON.parse(json) : json;
  const entries = data && Array.isArray(data.apps) ? data.apps : [];
  const cats = data && Array.isArray(data.categories) ? data.categories.filter(Boolean) : [];
  return {
    apps: entries.map((e) => feedEntryToApp(e, state)).filter(Boolean),
    categories: cats.length ? cats : undefined,
  };
}

/* ---- src/components/wallet-hero.js ---- */
/**
 * c-wallet-hero — the Wallet home hero (spec docs/wallet-shell-spec.md §2, #133/#134).
 * Hero-region pattern (#20: `surface/hero` + on-hero inks, gradient overlay), screen
 * title at heading-sm (#58), balance in tabular numerals (#21) with the unit inline,
 * an optional fiat line (renders ONLY when the bridge provides one — balance-level
 * fiat source is a §9 question; Damir's app-frame reference shows it, so the demo
 * seeds it), a hide-balance eye toggle, and the three quick actions from the reference:
 * Send (primary) · Receive · Scan.
 *
 * Balance/fiat arrive PRE-FORMATTED strings from the bridge (#55/#77) — component dumb.
 * Hidden state masks amount + fiat with bullets; the real strings live only in the
 * WeakMap (no DOM/aria leak). Eye = aria-pressed toggle with a CONSTANT label
 * ("Hide balance" — APG: pressed carries the state, the label must not flip); the
 * glyph is state-vocabulary per member-sheet: eye = visible, eye-off = hidden.
 *
 * The hero owns the top safe-area inset (`env(safe-area-inset-top)`) so the status-bar
 * region paints hero-colored with NO seam — the #22 watch-item surface.
 *
 * createWalletHero({ title, balance, unit, fiat, hidden, strings,
 *                    onSend, onReceive, onScan, onToggleHidden }) → header
 * Free fns (#44): setWalletBalance(el, { balance, fiat }) — bridge balance tick;
 *                 setBalanceHidden(el, hidden) — eye state (shell owns persistence, §7).
 */



const MASK = '••••••';
const store = new WeakMap();   // el → { balance, fiat, hidden, strings }

function renderAmounts(el) {
  const s = store.get(el);
  if (!s) return;
  const amount = el.querySelector('.c-wallet-hero__amountvalue');
  const fiat = el.querySelector('.c-wallet-hero__fiat');
  const compact = el.querySelector('.c-wallet-hero__compactbal');
  if (amount) amount.textContent = s.hidden ? MASK : (s.balance || '');
  if (compact) compact.textContent = s.hidden ? MASK : (s.balance || '');
  if (fiat) {
    fiat.textContent = s.hidden ? '••••' : (s.fiat || '');
    fiat.hidden = !s.fiat;
  }
  const eye = el.querySelector('.c-wallet-hero__eye');
  if (eye) {
    eye.setAttribute('aria-pressed', String(!!s.hidden));   // label stays constant (APG)
    eye.textContent = '';
    eye.append(icon(s.hidden ? 'eye-off' : 'eye', { size: 22 }));   // glyph = state (member-sheet vocabulary)
  }
}

function quickAction({ glyph, label, onClick }) {
  const b = document.createElement('button');
  b.type = 'button';
  b.className = 'c-wallet-hero__qa';
  const circle = document.createElement('span');
  circle.className = 'c-wallet-hero__qacircle';
  circle.append(icon(glyph, { size: 24 }));
  b.append(circle, document.createTextNode(label));
  if (onClick) b.addEventListener('click', onClick);
  return b;
}

function createWalletHero({
  title = 'Wallet', balance = '', unit = 'IXI', fiat = '', hidden = false,
  strings = getStrings(), onSend, onReceive, onScan, onToggleHidden,
} = {}) {
  const el = document.createElement('header');
  el.className = 'c-wallet-hero';

  const trow = document.createElement('div');
  trow.className = 'c-wallet-hero__titlerow';
  const t = document.createElement('h1');
  t.className = 'c-wallet-hero__title';
  t.textContent = strings.walletTitle || title;
  trow.append(t);
  // compact balance — visible only while the hero is minimized on scroll (#134 scroll UX)
  const toggleHidden = () => {
    const s = store.get(el);
    s.hidden = !s.hidden;
    renderAmounts(el);
    if (onToggleHidden) onToggleHidden(s.hidden);   // shell persistence stays in sync (audit M4)
  };
  const cb = document.createElement('span');
  cb.className = 'c-wallet-hero__compactbal u-tabular';
  cb.setAttribute('aria-hidden', 'true');   // the full balance block stays the AT source
  // minimized hero: tapping the compact balance toggles hide too (Damir #135; pointer
  // convenience — the balance-block/eye path returns when the hero expands)
  cb.addEventListener('click', toggleHidden);
  trow.append(cb);
  el.append(trow);

  const bal = document.createElement('div');
  bal.className = 'c-wallet-hero__balance';
  const label = document.createElement('div');
  label.className = 'c-wallet-hero__label';
  label.textContent = strings.availableBalance || 'Available Balance';
  bal.append(label);

  const row = document.createElement('div');
  row.className = 'c-wallet-hero__amountrow';
  const amount = document.createElement('div');
  amount.className = 'c-wallet-hero__amount u-tabular';
  const value = document.createElement('span');
  value.className = 'c-wallet-hero__amountvalue';
  const u = document.createElement('span');
  u.className = 'c-wallet-hero__unit';
  u.textContent = unit;
  amount.append(value, u);                               // gap via CSS margin — no stray text node
  const eye = document.createElement('button');
  eye.type = 'button';
  eye.className = 'c-wallet-hero__eye';
  eye.setAttribute('aria-label', strings.hideBalance || 'Hide balance');   // constant (APG toggle)
  eye.addEventListener('click', (e) => {
    // stopPropagation is LOAD-BEARING (Damir #136: center-taps "did nothing"): the toggle
    // re-render DETACHES the tapped svg, so the balance-block guard's closest() failed on
    // the orphaned target and the bubbled click toggled BACK (double-toggle = net zero)
    e.stopPropagation();
    toggleHidden();
  });
  // pointer convenience (Damir #135): tapping ANYWHERE on the balance block toggles too —
  // the eye stays the accessible control (keyboard/SR path)
  bal.addEventListener('click', toggleHidden);
  row.append(amount, eye);
  bal.append(row);

  const f = document.createElement('div');
  f.className = 'c-wallet-hero__fiat u-tabular';
  bal.append(f);
  el.append(bal);

  const actions = document.createElement('div');
  actions.className = 'c-wallet-hero__actions';
  actions.append(
    // all three identical — the special filled Send circle "felt weird" (Damir #135)
    quickAction({ glyph: 'arrow-up-right', label: strings.send || 'Send', onClick: onSend }),
    quickAction({ glyph: 'arrow-down-left', label: strings.receive || 'Receive', onClick: onReceive }),
    quickAction({ glyph: 'scan', label: strings.scan || 'Scan', onClick: onScan }),
  );
  el.append(actions);

  store.set(el, { balance, fiat, hidden: !!hidden, strings });
  renderAmounts(el);
  return el;
}

/** Bridge balance tick (#44). Pass pre-formatted strings; fiat '' hides the line. */
function setWalletBalance(el, { balance, fiat } = {}) {
  const s = store.get(el);
  if (!s) return el;
  if (balance != null) s.balance = balance;
  if (fiat != null) s.fiat = fiat;
  renderAmounts(el);
  return el;
}

/** Set the hidden state explicitly (shell restores its in-memory preference, §7). */
function setBalanceHidden(el, hidden) {
  const s = store.get(el);
  if (!s) return el;
  s.hidden = !!hidden;
  renderAmounts(el);
  return el;
}

/** Minimize/restore the hero (scroll UX, #134): balance block + quick actions collapse,
 *  the title row gains a compact balance. Pure state toggle — the scroll wiring lives
 *  in wallet-shell's attachWalletScroll. */
function setWalletHeroCompact(el, compact) {
  if (!el) return el;
  if (compact) el.dataset.compact = ''; else delete el.dataset.compact;
  // collapsed zones leave the a11y tree + tab order (#113 inert pattern + fallback for
  // pre-inert WebViews — conservative baseline #4)
  for (const zone of el.querySelectorAll('.c-wallet-hero__balance, .c-wallet-hero__actions')) {
    if (compact) {
      zone.setAttribute('aria-hidden', 'true');
      if ('inert' in zone) zone.inert = true;
      for (const b of zone.querySelectorAll('button')) b.tabIndex = -1;
    } else {
      zone.removeAttribute('aria-hidden');
      if ('inert' in zone) zone.inert = false;
      for (const b of zone.querySelectorAll('button')) b.removeAttribute('tabindex');
    }
  }
  return el;
}

/* ---- src/components/wallet-shell.js ---- */
/**
 * c-wallet-shell — Wallet flow shell, slice 1 (spec docs/wallet-shell-spec.md, #133/#134):
 * tx MODEL + render pipeline, filter chips (All/Sent/Received) with the #98
 * "Missing a transaction?" info pill at the row end, c-txlist-item rows (#55),
 * the tx-detail BOTTOM SHEET (Damir) and the missing-tx explainer sheet.
 *
 * Model tx: { txid, direction:'in'|'out', status:'confirmed'|'pending'|'failed'|'unknown',
 *             name, contact?, address?, timestamp, amount, fiat, fee? }
 *   status mirrors the legacy confirmation enum (true→confirmed / false→pending /
 *   error→failed / unknown). amount/fiat/fee arrive PRE-FORMATTED (#55/#77); rows
 *   render only when the field is present (data-honest — addPaymentActivity carries
 *   no fee today: §9 ask = extend the payload or a detail fetch). `contact:true` (or a
 *   name distinct from the address) personalizes the sheet with the deterministic
 *   avatar (Damir 2026-07-05).
 * state: { txs: [], filter: 'all'|'sent'|'received' }
 *
 * Explorer links (legacy parity): address-level = `ixian:explorer` → explorer.ixian.io
 * address view; tx-level mirrors WalletSentPage's viewexplorer URL. The shell routes
 * BOTH through the external-link confirm and fires the bridge intent via
 * opts.onExplorer(txOrNull). Naming follows the legacy lang keys ("Explorer").
 *
 * createWalletTxList(state, opts) / renderWalletTxList(listEl, state, opts)
 * setWalletFilter(listEl, state, filter, opts) — free fn (#44)
 * createWalletFilters(state, { listEl, host, strings, onExplorer }) → row
 * openTxSheet({ tx, host, strings, onExplorer }) / openMissingTxSheet({ host, strings, onExplorer })
 */












/* ————————————————————————— model (pure, DOM-free) ————————————————————————— */

/** Sent = everything outgoing incl. pending/failed — the status badge carries the
 *  caveat (Damir decided 2026-07-05: failed attempts LIST under "Sent"; users look
 *  for "that send I tried" there, hiding them makes failures invisible). */
function txMatchesFilter(tx, filter) {
  if (!tx) return false;
  if (filter === 'sent') return tx.direction !== 'in';
  if (filter === 'received') return tx.direction === 'in';
  return true;
}

/** Frontend tx search (#52 boundary: list-level only — everything the WebView holds):
 *  counterparty name, address, txid. Empty/whitespace needle matches all. */
function txMatchesQuery(tx, needle) {
  const q = (needle || '').trim().toLocaleLowerCase();
  if (!q) return true;
  if (!tx) return false;
  if ((tx.name || '').toLocaleLowerCase().includes(q)) return true;
  if ((tx.address || '').toLocaleLowerCase().includes(q)) return true;
  return (tx.txid || '').toLocaleLowerCase().includes(q);
}

function orderedTxs(state) {
  return (state.txs || [])
    .filter(Boolean)
    .filter((t) => txMatchesFilter(t, state.filter || 'all'))
    .filter((t) => txMatchesQuery(t, state.query));
}

/* ————————————————————————————— tx list ————————————————————————————— */

function walletEmpty(state, strings) {
  const el = document.createElement('div');
  el.className = 'c-wallet-empty';
  el.setAttribute('role', 'note');
  const q = (state.query || '').trim();
  const f = state.filter || 'all';
  el.textContent = q ? (strings.walletEmptySearch || 'No transactions match “{q}”').split('{q}').join(q)
    : f === 'sent' ? (strings.walletEmptySent || 'No sent payments yet')
    : f === 'received' ? (strings.walletEmptyReceived || 'No received payments yet')
    : (strings.walletEmptyAll || 'No activity yet — payments you send and receive show up here');
  return el;
}

function renderWalletTxList(listEl, state, opts = {}) {
  const strings = opts.strings || getStrings();
  listEl.textContent = '';
  const txs = orderedTxs(state);
  for (const tx of txs) {
    listEl.append(createTxItem({
      ...tx, strings,
      onClick: () => openTxSheet({ tx, host: opts.host, strings, onExplorer: opts.onExplorer }),
    }));
  }
  if (!txs.length) listEl.append(walletEmpty(state, strings));
  return listEl;
}

function createWalletTxList(state, opts = {}) {
  const el = document.createElement('div');
  el.className = 'c-wallet-txlist';
  renderWalletTxList(el, state, opts);
  return el;
}

/** Free fn (#44): switch the filter and re-render. */
function setWalletFilter(listEl, state, filter, opts) {
  state.filter = filter === 'sent' || filter === 'received' ? filter : 'all';
  return renderWalletTxList(listEl, state, opts);
}

/** Free fn (#44): set the search query and re-render. */
function setWalletQuery(listEl, state, query, opts) {
  state.query = query;
  return renderWalletTxList(listEl, state, opts);
}

/** Brief highlight on a just-landed row (Damir #136): the send flow returns home and the
 *  fresh pending tx pulses once (~2s wash) so the eye lands on it. Reduced motion skips
 *  the animation (explicit @media escape, #117 raw-keyframe precedent). */
function flashWalletTx(listEl, txid) {
  if (!listEl || txid == null) return null;
  const esc = window.CSS && CSS.escape ? CSS.escape(String(txid)) : String(txid).replace(/"/g, '\\"');
  const row = listEl.querySelector('.c-txlist-item[data-txid="' + esc + '"]');
  if (!row) return null;
  row.dataset.flash = '';
  row.addEventListener('animationend', () => { delete row.dataset.flash; }, { once: true });
  setTimeout(() => { delete row.dataset.flash; }, 2400);   // reduced-motion/no-animation fallback cleanup
  return row;
}

/* —————————————————— filter chips + "Missing a transaction?" —————————————————— */

const FILTERS = [
  { id: 'all', label: 'All', key: 'filterAll' },
  { id: 'sent', label: 'Sent', key: 'filterSent' },
  { id: 'received', label: 'Received', key: 'filterReceived' },
];

function createWalletFilters(state, opts = {}) {
  const strings = opts.strings || getStrings();
  const row = document.createElement('div');
  row.className = 'c-wallet-filters';
  row.setAttribute('role', 'group');
  row.setAttribute('aria-label', strings.filterTx || 'Filter transactions');
  const chips = FILTERS.map((f) => createChip({
    label: strings[f.key] || f.label,
    selected: (state.filter || 'all') === f.id,
    onClick: (e) => {
      for (const c of row.querySelectorAll('.c-chip')) setChipSelected(c, c === e.currentTarget);
      if (opts.listEl) setWalletFilter(opts.listEl, state, f.id, opts);
      if (opts.onFilter) opts.onFilter(f.id);
    },
    strings,
  }));
  row.append(...chips);

  // #98: standing quiet affordance for the chain-read-lag property; sits at the row END,
  // action-tonal so it owns the wash (chips stay neutral-outline unselected). Narrow
  // contexts collapse it to the ⓘ glyph alone (CSS; aria-label carries the name).
  const miss = document.createElement('button');
  miss.type = 'button';
  miss.className = 'c-wallet-misstx';
  miss.append(icon('info-circle', { size: 16 }));
  const mlabel = document.createElement('span');
  mlabel.className = 'c-wallet-misstx__label';
  mlabel.textContent = strings.missingTx || 'Missing a transaction?';
  miss.append(mlabel);
  miss.setAttribute('aria-label', strings.missingTx || 'Missing a transaction?');
  miss.addEventListener('click', () => openMissingTxSheet({
    host: opts.host, strings, onExplorer: opts.onExplorer,
  }));
  row.append(miss);
  return row;
}

/* ———————————— tools block (search + filters) + scroll UX (#134 Damir) ———————————— */

/** Sticky tools: c-search-field (FE search: names/addresses/txids) above the filter
 *  row. Sits at the top of the scroll container; attachWalletScroll hides/reveals it. */
function createWalletTools(state, opts = {}) {
  const strings = opts.strings || getStrings();
  const el = document.createElement('div');
  el.className = 'c-wallet-tools';
  const search = createSearchField({
    placeholder: strings.searchTx || 'Search transactions',
    onInput: (v) => { if (opts.listEl) setWalletQuery(opts.listEl, state, v, opts); },
    strings,
  });
  el.append(search, createWalletFilters(state, opts));
  return el;
}

/** Scroll choreography (Damir #134, the #113/#114 family — binary triggered CSS
 *  transitions, no scroll-linked per-frame writes):
 *  · scroll DOWN past `collapseAt` → hero minimizes (compact title+balance) and,
 *    past a small accumulated delta, the tools row tucks away → single-page tx list
 *  · a brief scroll UP (≥ `reveal` px accumulated) → tools return (search + filters)
 *  · at the absolute top → hero expands again
 *  Guards: tools never hide while they hold focus or a non-empty query (the user is
 *  mid-search). Returns detach().
 */
function attachWalletScroll(scrollEl, { hero, tools, collapseAt = 120, reveal = 24 } = {}) {
  let last = scrollEl.scrollTop || 0;
  let up = 0;

  const toolsBusy = () => {
    if (!tools) return false;
    if (tools.contains(document.activeElement)) return true;
    const input = tools.querySelector('input');
    return !!(input && input.value.trim());
  };
  const setTools = (hiddenFlag) => {
    if (!tools) return;
    if (hiddenFlag) {
      if (toolsBusy()) return;
      tools.dataset.hidden = '';
      tools.setAttribute('aria-hidden', 'true');
      if ('inert' in tools) tools.inert = true;
      for (const f of tools.querySelectorAll('button, input')) f.tabIndex = -1;
    } else {
      delete tools.dataset.hidden;
      tools.removeAttribute('aria-hidden');
      if ('inert' in tools) tools.inert = false;
      for (const f of tools.querySelectorAll('button, input')) f.removeAttribute('tabindex');
    }
  };

  const onScroll = () => {
    const top = scrollEl.scrollTop;
    const d = top - last;
    last = top;
    if (top <= 1) {                                      // absolute top → everything back
      if (hero) setWalletHeroCompact(hero, false);
      setTools(false);
      up = 0;
      return;
    }
    if (d > 0) {                                         // downward
      up = 0;
      if (top > collapseAt) {
        if (hero) setWalletHeroCompact(hero, true);
        setTools(true);
      }
    } else if (d < 0) {                                  // upward — brief pull reveals tools
      up += -d;
      if (up >= reveal) setTools(false);
    }
  };
  scrollEl.addEventListener('scroll', onScroll, { passive: true });
  return () => scrollEl.removeEventListener('scroll', onScroll);
}

/* ————————————————————————— shared bits ————————————————————————— */

/** Copy button with the member-sheet clipboard + check-morph pattern (audit #134①). */
function copyButton(value, label, strings = getStrings()) {
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'c-txsheet__copy';
  const idleLabel = (strings.copy || 'Copy') + ' — ' + label;
  btn.setAttribute('aria-label', idleLabel);
  btn.append(icon('copy', { size: 16 }));
  btn.addEventListener('click', () => {
    if (navigator.clipboard) navigator.clipboard.writeText(String(value)).catch(() => {});
    btn.textContent = '';
    btn.append(icon('check', { size: 16 }));               // confirmation morph — no false toast
    btn.setAttribute('aria-label', strings.txCopied || 'Copied');   // SRs hear the confirm
    setTimeout(() => {
      btn.textContent = '';
      btn.append(icon('copy', { size: 16 }));
      btn.setAttribute('aria-label', idleLabel);
    }, 1400);
  });
  return btn;
}

/** Latch a sheet-closing bridge intent so the exit transition can't re-fire it (#72④). */
function latched(sheetRef, fn) {
  return (e) => {
    const b = e.currentTarget;
    if (b.dataset.acted !== undefined) return;
    b.dataset.acted = '';
    b.disabled = true;
    closeSheet(sheetRef());
    fn();
  };
}

const STATUS_META = {
  confirmed: { label: 'Confirmed', key: 'txConfirmed', type: 'success', glyph: 'checks' },
  pending: { label: 'Pending', key: 'txPending', type: 'warning', glyph: 'clock-hour-10' },
  failed: { label: 'Failed', key: 'txFailed', type: 'error', glyph: 'alert-square-rounded' },
  unknown: { label: 'Unknown', key: 'txUnknown', type: 'info', glyph: 'hourglass-empty' },   // badge types: warning|error|info|success|accent (#54)
};

/* ————————————————————————— tx detail sheet (Damir: bottom sheet) ————————————————————————— */

function sheetRow(label, value) {
  if (value == null || value === '') return null;
  const r = document.createElement('div');
  r.className = 'c-txsheet__row';
  const l = document.createElement('span');
  l.className = 'c-txsheet__rowlabel';
  l.textContent = label;
  const v = document.createElement('span');
  v.className = 'c-txsheet__rowvalue u-tabular';
  v.textContent = String(value);
  r.append(l, v);
  return r;
}

function openTxSheet({ tx = {}, host, strings = getStrings(), onExplorer } = {}) {
  const status = STATUS_META[tx.status] ? tx.status : 'unknown';
  const meta = STATUS_META[status];
  const type = status !== 'confirmed' ? status : (tx.direction === 'in' ? 'received' : 'sent');
  const isContact = !!tx.contact || (!!tx.name && !!tx.address && tx.name !== tx.address);

  const content = document.createElement('div');
  content.className = 'c-txsheet';

  /* header — contact avatar personalizes when we know the counterparty (Damir #134);
     otherwise the direction circle carries the identity slot */
  const head = document.createElement('div');
  head.className = 'c-txsheet__head';
  if (isContact) {
    head.append(createAvatar({ name: tx.name, address: tx.address, size: 48 }));
  } else {
    const dir = document.createElement('span');
    dir.className = 'c-txsheet__dir';
    dir.dataset.type = type;
    dir.append(icon(tx.direction === 'in' ? 'arrow-down-left' : 'arrow-up-right', { size: 24 }));
    head.append(dir);
  }
  const htext = document.createElement('div');
  htext.className = 'c-txsheet__headtext';
  const title = document.createElement('h2');
  title.className = 'c-txsheet__title';
  title.textContent = tx.direction === 'in'
    ? (isContact ? ((strings.receivedFrom || 'Received from {name}').split('{name}').join(tx.name)) : (strings.received || 'Received'))
    : (isContact ? ((strings.sentTo || 'Sent to {name}').split('{name}').join(tx.name)) : (strings.sent || 'Sent'));
  htext.append(title);
  head.append(htext);
  head.append(createBadge({ label: strings[meta.key] || meta.label, type: meta.type, weight: 'tonal', icon: meta.glyph }));
  content.append(head);

  /* amount */
  const amt = document.createElement('div');
  amt.className = 'c-txsheet__amount u-tabular';
  amt.dataset.type = type;
  amt.textContent = tx.amount || '';
  content.append(amt);
  if (tx.fiat) {
    const fiat = document.createElement('div');
    fiat.className = 'c-txsheet__fiat u-tabular';
    fiat.textContent = tx.fiat;
    content.append(fiat);
  }

  /* address — member-sheet addr-chip pattern (#99): FULL address, wrapping, working copy.
     Labelled by WHOSE address it is (Damir #135): received → sender's, sent → recipient's. */
  if (tx.address) {
    const addrLabel = document.createElement('div');
    addrLabel.className = 'c-txsheet__addrlabel';
    addrLabel.textContent = tx.direction === 'in'
      // #171: curly apostrophe — matches the dictionary-wide typographic ’ (was ASCII ')
      ? (strings.senderAddress || 'Sender’s address')
      : (strings.recipientAddress || 'Recipient’s address');
    const addrRow = document.createElement('div');
    addrRow.className = 'c-txsheet__addr';
    const addr = document.createElement('span');
    addr.className = 'c-txsheet__addrvalue u-tabular';
    addr.textContent = tx.address;
    addrRow.append(addr, copyButton(tx.address, addrLabel.textContent, strings));
    content.append(addrLabel, addrRow);
  }

  /* meta — rows render only when the bridge provided the field (data-honest);
     Status always renders (legacy confirmation enum incl. unknown, Damir #134) */
  const metaBox = document.createElement('div');
  metaBox.className = 'c-txsheet__meta';
  const rows = [
    sheetRow(strings.status || 'Status', strings[meta.key] || meta.label),
    // timeText = pre-formatted native-bridge time string (verbatim); timestamp = epoch (formatted)
    sheetRow(strings.date || 'Date',
      (tx.timeText != null && tx.timeText !== '') ? tx.timeText
        : (tx.timestamp != null ? formatTxTimestamp(tx.timestamp) : '')),
  ].filter(Boolean);
  if (tx.fee != null && tx.fee !== '') {
    // fee row carries an ⓘ that reveals a one-line explanation (Damir #135)
    const feeRow = sheetRow(strings.fee || 'Fee', tx.fee);
    const feeExplain = document.createElement('p');
    feeExplain.className = 'c-txsheet__explain';
    feeExplain.setAttribute('role', 'status');           // announced when filled (polite)
    const feeInfo = document.createElement('button');
    feeInfo.type = 'button';
    feeInfo.className = 'c-txsheet__info';
    feeInfo.setAttribute('aria-label', strings.whatsThisFee || 'What is this fee?');
    feeInfo.setAttribute('aria-expanded', 'false');      // disclosure state for AT (audit n1)
    feeInfo.append(icon('info-circle', { size: 14 }));
    feeInfo.addEventListener('click', () => {
      const open = !feeExplain.textContent;
      feeExplain.textContent = open
        ? (strings.feeExplain || 'Network fee — paid to the Ixian network for processing this transaction, not to Spixi.')
        : '';
      feeInfo.setAttribute('aria-expanded', String(open));
    });
    feeRow.querySelector('.c-txsheet__rowlabel').append(feeInfo);
    feeRow.append(feeExplain);
    feeRow.classList.add('c-txsheet__row--fee');
    rows.push(feeRow);
  }
  if (tx.txid) {
    const idRow = sheetRow(strings.txId || 'Transaction ID', tx.txid);
    idRow.append(copyButton(tx.txid, strings.txId || 'Transaction ID', strings));
    rows.push(idRow);
  }
  metaBox.append(...rows);
  content.append(metaBox);

  /* explorer — routes through the external-link confirm in the shell (onExplorer duty) */
  if (onExplorer) {
    content.append(createButton({
      label: strings.viewExplorer || 'View in Explorer', type: 'outline', size: 44, width: 'full',
      icon: icon('arrow-up-right', { size: 18 }), iconPosition: 'trailing',
      onClick: latched(() => sheet, () => onExplorer(tx)),
    }));
  }

  const sheet = createSheet({ content, host, strings, title: '' });   // head carries the identity
  sheet.setAttribute('aria-label', strings.txDetails || 'Transaction details');
  openSheet(sheet);
  return sheet;
}

/* ————————————————————— missing-tx explainer sheet (#98) ————————————————————— */

function openMissingTxSheet({ host, strings = getStrings(), onExplorer } = {}) {
  const content = document.createElement('div');
  content.className = 'c-misstx';
  const body = document.createElement('p');
  body.className = 'c-misstx__body';
  body.textContent = strings.missingTxBody
    || 'Spixi reads your history directly from the Ixian blockchain — recent transactions can take a moment to appear, and very old ones may not be listed here.';
  content.append(body);

  const actions = document.createElement('div');
  actions.className = 'c-misstx__actions';
  // single action — no refresh command exists in the bridge (Damir #135); the list
  // already rebuilds on every addPaymentActivity tick
  if (onExplorer) {
    // legacy parity: `ixian:explorer` opens THIS address on explorer.ixian.io
    actions.append(createButton({
      label: strings.viewAllExplorer || 'View all transactions on Explorer', type: 'fill', size: 44, width: 'full',
      icon: icon('arrow-up-right', { size: 18 }), iconPosition: 'trailing',
      onClick: latched(() => sheet, () => onExplorer(null)),
    }));
  }
  content.append(actions);

  const sheet = createSheet({
    content, host, strings,
    title: strings.missingTx || 'Missing a transaction?',   // sheet title = accessible name
  });
  openSheet(sheet);
  return sheet;
}

/* ---- src/components/wallet-send.js ---- */
/**
 * c-wallet-send — the send flow, slice 2 (spec §3, #133: ONE screen + review sheet).
 * Replaces the legacy 3-page hop (wallet_send → send2 → sent):
 *
 * 1. RECIPIENT — search over contacts (deterministic avatars) OR a raw address input
 *    ("Send to an address" reveal) OR QR (`ixian:quickscan` via onQuickScan; the shell
 *    calls setSendAddress with the scan result). Selecting shows a recipient row with ✕.
 * 2. AMOUNT — decimal-sanitized input (≤8 decimals, chain precision), Available line,
 *    Max (balance − fee, #77 truncation), live fee + total; inline insufficient error.
 * 3. REVIEW = c-sheet (#26 deliberateness step): recipient · amount · fee · total +
 *    explicit Confirm (latched → loading, #29/#72④) / Cancel. onSend(payload, ctrl) —
 *    the bridge runs the real send: ctrl.done() → success morph → onDone(payload)
 *    (shell returns home; the pending row arrives via addPaymentActivity); ctrl.fail(msg)
 *    → inline error in the sheet, Confirm re-enabled (retry stays possible).
 *
 * Numbers: user input is RAW here (the one surface where FE math is unavoidable —
 * validation + Max + total); display strings still follow #77 (truncate, never round).
 * The bridge remains the source of truth and re-validates on its side.
 * Legacy multi-recipient stays commented out C#-side — payload is single-recipient but
 * shaped plural-ready ({ recipients: [ { address, name? } ] }).
 *
 * createWalletSend({ contacts, balance, fee, strings, host,
 *                    onQuickScan, onSend, onDone }) → view
 * Free fn (#44): setSendAddress(el, address) — QR-scan result lands in the address path.
 */










/* fromUnits is wallet-send-only (Max display); its inverse toUnits + the
   sanitize/canonical helpers now live in money.js (#143 dedupe). */
function fromUnits(u) {
  const neg = u < 0n;
  const a = neg ? -u : u;
  const i = (a / 100000000n).toString();
  const d = (a % 100000000n).toString().padStart(8, '0').replace(/0+$/, '');
  return (neg ? '-' : '') + i + (d ? '.' + d : '');
}

let walletSendSeq = 0;                                     // aria-controls ids (receive-audit n2)

function createWalletSend({
  contacts = [], balance = 0, fee = 0, strings = getStrings(), host,
  lockedRecipient = null,   // chat Pay (#139): { name?, address } — pre-picked, NO change (the peer is known)
  onQuickScan, onSend, onDone,
} = {}) {
  // NB contract: balance/fee are RAW numerics (number or plain decimal string) — this is
  // the one FE surface doing money math. Pre-formatted display strings (hero-style
  // '923,852.00') are NOT valid inputs here.
  const el = document.createElement('div');
  el.className = 'c-wallet-send';
  const addrFieldId = 'c-wallet-send-addrfield-' + (++walletSendSeq);
  const balU = toUnits(balance);
  const feeU = toUnits(fee);
  const state = { recipient: null, amount: '', sending: false, attempt: 0 };

  /* ——— recipient section ——— */
  const recSec = document.createElement('section');
  recSec.className = 'c-wallet-send__section';
  const recTitle = document.createElement('h2');
  recTitle.className = 'c-wallet-send__label';
  recTitle.textContent = strings.sendTo || 'Send to';
  recSec.append(recTitle);

  /* selected recipient row (hidden until picked) */
  const picked = document.createElement('div');
  picked.className = 'c-wallet-send__picked';
  picked.hidden = true;
  recSec.append(picked);

  /* picker: search + contact rows + address reveal */
  const picker = document.createElement('div');
  picker.className = 'c-wallet-send__picker';
  const search = createSearchField({
    placeholder: strings.searchContacts || 'Search contacts',
    onInput: (v) => renderContacts(v),
    strings,
  });
  picker.append(search);
  const rows = document.createElement('div');
  rows.className = 'c-wallet-send__contacts';           // appended after the address row below

  // "Send to an address" sits ON TOP of the contacts, aligned with them — a contact-style
  // row whose avatar slot is the qrcode glyph (Damir #136); tapping expands the input below
  const addrRow = document.createElement('button');
  addrRow.type = 'button';
  addrRow.className = 'c-wallet-send__contact';
  addrRow.setAttribute('aria-expanded', 'false');
  addrRow.setAttribute('aria-controls', (addrFieldId));   // reveal linked for AT (receive-audit n2, applied here too)
  const addrGlyph = document.createElement('span');
  addrGlyph.className = 'c-wallet-send__addrglyph';
  addrGlyph.append(icon('qrcode', { size: 20 }));
  const addrLabel = document.createElement('span');
  addrLabel.className = 'c-wallet-send__contactname';
  addrLabel.textContent = strings.sendToAddress || 'Send to an address';
  addrRow.append(addrGlyph, addrLabel);
  picker.append(addrRow);

  const addrField = document.createElement('div');
  addrField.className = 'c-wallet-send__addrfield';
  addrField.id = addrFieldId;
  addrField.hidden = true;
  const addrInput = document.createElement('input');
  addrInput.className = 'c-wallet-send__addrinput';
  addrInput.type = 'text';
  addrInput.autocomplete = 'off';
  addrInput.spellcheck = false;
  addrInput.placeholder = strings.ixianAddress || 'Ixian address';
  addrInput.setAttribute('aria-label', strings.ixianAddress || 'Ixian address');
  const scanBtn = document.createElement('button');
  scanBtn.type = 'button';
  scanBtn.className = 'c-wallet-send__scan';
  scanBtn.setAttribute('aria-label', strings.scan || 'Scan');
  scanBtn.append(icon('scan', { size: 20 }));
  if (onQuickScan) scanBtn.addEventListener('click', onQuickScan);   // → ixian:quickscan; result via setSendAddress
  addrField.append(addrInput, scanBtn);
  const addrUse = createButton({
    label: strings.useAddress || 'Use this address', type: 'outline', size: 44, width: 'full',
    onClick: () => {
      const a = addrInput.value.trim();
      if (a.length < 12) { setSendError(el, strings.badAddress || 'That doesn’t look like an Ixian address.'); return; }
      pick({ address: a });
    },
  });
  addrField.append(addrUse);
  picker.append(addrField);
  addrRow.addEventListener('click', () => {
    const open = addrField.hidden;
    addrField.hidden = !open;
    addrRow.setAttribute('aria-expanded', String(open));
    if (open) addrInput.focus();
  });

  picker.append(rows);                                   // contacts BELOW the address row (Damir #136)

  const errLine = document.createElement('p');
  errLine.className = 'c-wallet-send__error';
  errLine.setAttribute('role', 'alert');
  errLine.hidden = true;
  addrField.append(errLine);   // under the input it validates — it rendered BELOW the contacts (Damir bug, round 3)
  recSec.append(picker);
  el.append(recSec);

  function renderContacts(q) {
    const needle = (q || '').trim().toLocaleLowerCase();
    rows.textContent = '';
    const list = contacts.filter((c) => !needle
      || (c.name || '').toLocaleLowerCase().includes(needle)
      || (c.address || '').toLocaleLowerCase().includes(needle))
      .sort((a, b) => (a.name || a.address || '').localeCompare(b.name || b.address || ''));
    // #142 (Damir 2026-07-05c): NO caps — the #136 window forced you to know
    // the name; the full A–Z list scrolls and search narrows. The amount
    // section never competes: picking COLLAPSES the picker to the picked row,
    // and until a recipient exists the amount can't be submitted anyway.
    for (const c of list) {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'c-wallet-send__contact';
      b.append(createAvatar({ name: c.name, address: c.address, size: 40 }));
      const t = document.createElement('span');
      t.className = 'c-wallet-send__contactname';
      t.textContent = c.name || c.address;
      b.append(t);
      b.addEventListener('click', () => pick({ ...c, contact: true }));
      rows.append(b);
    }
    if (!list.length && needle) {
      const none = document.createElement('p');
      none.className = 'c-wallet-send__none';
      none.setAttribute('role', 'note');
      none.textContent = (strings.noContactMatch || 'No contact matches “{q}” — you can paste their address instead.').split('{q}').join(q);
      rows.append(none);
    }
  }

  function pick(recipient) {
    state.recipient = recipient;
    errLine.hidden = true;
    picked.textContent = '';
    picked.hidden = false;
    picker.hidden = true;
    if (recipient.contact) picked.append(createAvatar({ name: recipient.name, address: recipient.address, size: 40 }));
    else {
      const glyph = document.createElement('span');
      glyph.className = 'c-wallet-send__pickedglyph';
      glyph.append(icon('qrcode', { size: 20 }));
      picked.append(glyph);
    }
    const pt = document.createElement('span');
    pt.className = 'c-wallet-send__pickedtext';
    const pn = document.createElement('span');
    pn.className = 'c-wallet-send__pickedname';
    pn.textContent = recipient.name || (strings.address || 'Address');
    pt.append(pn);
    const pa = document.createElement('span');
    pa.className = 'c-wallet-send__pickedaddr u-tabular';
    pa.textContent = recipient.address;
    pt.append(pa);
    picked.append(pt);
    if (!lockedRecipient) {                              // locked = the peer is fixed, no ✕ (#139)
      const clear = document.createElement('button');
      clear.type = 'button';
      clear.className = 'c-wallet-send__clear';
      clear.setAttribute('aria-label', strings.changeRecipient || 'Change recipient');
      clear.append(icon('x', { size: 18 }));
      clear.addEventListener('click', () => {
        state.recipient = null;
        picked.hidden = true;
        picker.hidden = false;
        sync();
        const si = picker.querySelector('input');
        if (si) si.focus();                              // focus back into the picker (audit m2)
      });
      picked.append(clear);
    }
    sync();
    amtInput.focus();                                    // picker collapses under you — focus flows to the amount (audit m2)
  }

  /* ——— amount section ——— */
  const amtSec = document.createElement('section');
  amtSec.className = 'c-wallet-send__section';
  const amtTitle = document.createElement('h2');
  amtTitle.className = 'c-wallet-send__label';
  amtTitle.textContent = strings.amount || 'Amount';
  amtSec.append(amtTitle);

  const amtRow = document.createElement('div');
  amtRow.className = 'c-wallet-send__amountrow';
  const amtInput = document.createElement('input');
  amtInput.className = 'c-wallet-send__amount u-tabular';
  amtInput.type = 'text';
  amtInput.inputMode = 'decimal';
  amtInput.placeholder = '0';
  amtInput.setAttribute('aria-label', strings.amount || 'Amount');
  amtInput.addEventListener('input', () => {
    const v = sanitizeAmount(amtInput.value);
    if (v !== amtInput.value) amtInput.value = v;
    state.amount = v;
    sync();
  });
  const unit = document.createElement('span');
  unit.className = 'c-wallet-send__unit';
  unit.textContent = 'IXI';
  const maxBtn = createButton({ label: strings.max || 'Max', type: 'outline', size: 32,
    onClick: () => {
      // sending EVERYTHING deserves a deliberate stop (Damir #136): explicit confirm,
      // safe action autofocused (APG), only then the field fills
      const maxU = balU - feeU;
      // #150⑥ grammar (Damir 2026-07-05): the Max stop wears the standing
      // warning STRIP (error-tonal wash + alert glyph) — ADAPTED text: the
      // fill itself is editable, it's the payment that can't be undone
      const maxWarn = document.createElement('p');
      maxWarn.className = 'c-wallet-send__max-warn';
      maxWarn.append(icon('alert-square-rounded', { size: 18 }),
        document.createTextNode(strings.paymentsCannotUndo || 'Payments cannot be undone.'));
      openModal(createModal({
        title: strings.maxTitle || 'Send your entire balance?',
        body: (strings.maxBody || 'This fills in everything you have — {m} IXI after the network fee. You would be left with 0 IXI.')
          .split('{m}').join(fromUnits(maxU > 0n ? maxU : 0n)),
        content: maxWarn,
        role: 'alertdialog', host,
        actions: [
          { label: strings.cancel || 'Cancel', type: 'text', autofocus: true },
          { label: strings.maxConfirm || 'Yes, I understand', type: 'fill', onClick: () => {
            state.amount = fromUnits(maxU > 0n ? maxU : 0n);   // exact integer units — never overshoots
            amtInput.value = state.amount;
            sync();
          } },
        ],
      }));
    } });
  amtRow.append(amtInput, unit, maxBtn);
  amtSec.append(amtRow);

  const availLine = document.createElement('p');
  availLine.className = 'c-wallet-send__meta u-tabular';
  availLine.textContent = (strings.available || 'Available: {b} IXI').split('{b}').join(fromUnits(balU));
  amtSec.append(availLine);

  const feeLine = document.createElement('p');
  feeLine.className = 'c-wallet-send__meta u-tabular';
  amtSec.append(feeLine);

  const insuff = document.createElement('p');
  insuff.className = 'c-wallet-send__error';
  insuff.setAttribute('role', 'alert');
  insuff.hidden = true;
  amtSec.append(insuff);
  el.append(amtSec);

  /* ——— continue ——— */
  const cont = createButton({
    label: strings.reviewSend || 'Review', type: 'fill', size: 56, width: 'full',
    icon: icon('arrow-up-right', { size: 20 }),
    onClick: () => openSendReview(),
  });
  cont.disabled = true;
  const contWrap = document.createElement('div');
  contWrap.className = 'c-wallet-send__actions';
  contWrap.append(cont);
  el.append(contWrap);

  /* exact integer-unit math throughout (audit M1); EXACT strings at the money moments —
     #77 truncation is a feed-display rule, not a confirm-step rule (audit M3) */
  const amountU = () => toUnits(state.amount || '0');
  function valid() {
    if (!state.recipient || !state.amount) return false;
    const a = amountU();
    return a > 0n && a + feeU <= balU;
  }
  function sync() {
    const a = amountU();
    const total = a > 0n ? a + feeU : feeU;
    feeLine.textContent = (strings.feeAndTotal || 'Network fee {f} IXI · Total {t} IXI')
      .split('{f}').join(fromUnits(feeU)).split('{t}').join(fromUnits(total));
    const over = a > 0n && a + feeU > balU;
    insuff.hidden = !over;                                 // unhide BEFORE text → alert announces
    if (over) insuff.textContent = strings.insufficient || 'Not enough IXI to cover this amount plus the network fee.';
    cont.disabled = !valid();
  }
  sync();

  /* ——— review sheet (#26) ——— */
  function openSendReview() {
    if (!valid() || state.sending) return;               // per-VIEW in-flight token (audit C1)
    const r = state.recipient;
    const aU = amountU();
    const content = document.createElement('div');
    content.className = 'c-sendreview';

    const who = document.createElement('div');
    who.className = 'c-sendreview__who';
    if (r.contact) who.append(createAvatar({ name: r.name, address: r.address, size: 48 }));
    const wt = document.createElement('div');
    wt.className = 'c-sendreview__whotext';
    const wn = document.createElement('div');
    wn.className = 'c-sendreview__name';
    wn.textContent = r.name || (strings.address || 'Address');
    const wa = document.createElement('div');
    wa.className = 'c-sendreview__addr u-tabular';
    wa.textContent = r.address;
    wt.append(wn, wa);
    who.append(wt);
    content.append(who);

    const rowsBox = document.createElement('div');
    rowsBox.className = 'c-sendreview__rows';
    const row = (label, value) => {
      const rr = document.createElement('div');
      rr.className = 'c-sendreview__row';
      const l = document.createElement('span'); l.className = 'c-sendreview__rowlabel'; l.textContent = label;
      const v = document.createElement('span'); v.className = 'c-sendreview__rowvalue u-tabular'; v.textContent = value;
      rr.append(l, v);
      return rr;
    };
    // EXACT values at the confirm moment (audit M3) — what you approve is what is sent
    rowsBox.append(
      row(strings.amount || 'Amount', fromUnits(aU) + ' IXI'),
      row(strings.fee || 'Fee', fromUnits(feeU) + ' IXI'),
      row(strings.total || 'Total', fromUnits(aU + feeU) + ' IXI'),
    );
    content.append(rowsBox);

    const sheetErr = document.createElement('p');
    sheetErr.className = 'c-wallet-send__error';
    sheetErr.setAttribute('role', 'alert');
    sheetErr.hidden = true;
    content.append(sheetErr);

    const actions = document.createElement('div');
    actions.className = 'c-sendreview__actions';
    const cancel = createButton({ label: strings.cancel || 'Cancel', type: 'text', size: 44,
      onClick: () => { if (!state.sending) closeSheet(sheet); } });
    const confirm = createButton({ label: strings.confirmSend || 'Confirm & send', type: 'fill', size: 44,
      icon: icon('arrow-up-right', { size: 18 }),
      onClick: (e) => {
        if (e.currentTarget.dataset.acted !== undefined || state.sending) return;   // #72④ latch + view token
        e.currentTarget.dataset.acted = '';
        state.sending = true;
        const attempt = ++state.attempt;                 // invalidates stale bridge callbacks
        // money in flight → the sheet must NOT be dismissible (audit C1): no Esc, no
        // scrim, Cancel disabled; fail() restores the safe-dismiss paths for retry
        cancel.disabled = true;
        setOverlayOpts(sheet, { host, lightDismiss: false, escDismiss: false });
        sheetErr.hidden = true;
        setLoading(confirm, true);
        const payload = { recipients: [{ address: r.address, name: r.name }], amount: state.amount, fee: fromUnits(feeU) };
        const done = () => {
          if (attempt !== state.attempt) return;         // stale callback from a superseded attempt
          state.sending = false;
          setLoading(confirm, false);
          setSuccess(confirm, { label: strings.sent || 'Sent' });
          setTimeout(() => { closeSheet(sheet); if (onDone) onDone(payload); }, 900);
        };
        const fail = (msg) => {
          if (attempt !== state.attempt) return;
          state.sending = false;
          setLoading(confirm, false);
          delete confirm.dataset.acted;                  // retry stays possible
          cancel.disabled = false;
          setOverlayOpts(sheet, { host, lightDismiss: false, escDismiss: true });
          sheetErr.hidden = false;                       // unhide BEFORE text → alert announces
          sheetErr.textContent = msg || strings.sendFailed || 'The payment could not be sent. Please try again.';
        };
        if (onSend) onSend(payload, { done, fail }); else done();
      } });
    actions.append(cancel, confirm);                               // #60: two short labels side-by-side
    content.append(actions);

    // lightDismiss OFF from the start — a money confirmation is explicit (#56 modal
    // philosophy); Esc stays a safe dismiss until the send is actually in flight
    const sheet = createSheet({ content, host, strings, lightDismiss: false,
      title: strings.reviewTitle || 'Review payment' });
    openSheet(sheet);
    return sheet;
  }

  renderContacts('');
  if (lockedRecipient) pick({ ...lockedRecipient, contact: !!lockedRecipient.name });   // chat Pay: straight to the amount
  return el;
}

/** QR-scan result lands here (shell wires `ixian:quickscan` → setSendAddress). Accepts
 *  the legacy QR formats `addr`, `addr:ixi`, `addr:send:amount`. */
function setSendAddress(el, scanned) {
  if (!el) return el;
  const raw = String(scanned || '');
  const parts = raw.split(':');
  const address = parts[0] || '';
  // a scan supersedes an already-picked recipient — restore the picker first so the
  // filled field is actually visible (audit m4)
  const clearBtn = el.querySelector('.c-wallet-send__clear');
  if (clearBtn) clearBtn.click();
  const input = el.querySelector('.c-wallet-send__addrinput');
  const field = el.querySelector('.c-wallet-send__addrfield');
  if (field) field.hidden = false;
  if (input) { input.value = address; input.focus(); }
  if (parts[1] === 'send' && parts[2]) {
    const amt = el.querySelector('.c-wallet-send__amount');
    if (amt) { amt.value = parts[2]; amt.dispatchEvent(new Event('input', { bubbles: true })); }
  }
  return el;
}

/** Inline error on the send view (shell hook parity with apps-add's setAddError). */
function setSendError(el, msg) {
  const err = el && el.querySelector('.c-wallet-send__error');
  if (!err) return el;
  err.hidden = !msg;                                     // unhide BEFORE text → alert announces (audit m3)
  err.textContent = msg || '';
  return el;
}

