/**
 * c-settings "App" screens — Downloads · Developer (log) · Contributors
 * (docs/settings-shell-spec.md §9b, slice 2 — interview-locked 2026-07-05).
 *
 * Bridge honesty (bridge-audit-B §6–§8, all commands EXIST):
 * - Downloads: list arrives WHOLESALE (clearFiles + addFile(name, ctime) per
 *   file, re-pushed after any change) → setDownloads(el, files) mirrors that.
 *   ctime is DateTime.ToString() — LOCALE-DEPENDENT OPAQUE STRING: display
 *   as-is, never parse. Row tap → ixian:open:<name> (fire-and-forget, C# owns
 *   the result). Trash → ixian:delete:<name> behind the house locked confirm;
 *   C# deletes then re-pushes the list. "Delete all" → ixian:deleted (the
 *   danger-screen command reused).
 * - Dev: setLog(text) pushes the WHOLE ixian.log as one string, possibly
 *   twice (OnAppearing + onload) → setDevLog is an idempotent replace. No
 *   export/tail command exists — this screen is viewer + copy ONLY (Damir).
 * - Contributors: fully static (legacy contributors.html); names ship as opts
 *   with the legacy 12 as default.
 *
 * SECURITY: file names and log text come from the bridge → textContent ONLY
 * (the legacy page concatenated names into innerHTML — NOT ported). The
 * `..` traversal gap on ixian:open/delete is C#-side (§9 flag 5).
 *
 * Async callbacks use the house (payload, ctrl) contract, one-shot; every
 * shell callback is try/catch-guarded to the fail path (#141-m4).
 */








// one-shot ctrl (#138 m1) — module-local unique name (house collision rule)
function appCtrl(onDone, onFail) {
  let used = false;
  return {
    done: () => { if (used) return; used = true; onDone(); },
    fail: (msg) => { if (used) return; used = true; onFail(msg); },
  };
}

// legacy contributors.html list (static; localizable via opts)
const CONTRIBUTORS = [
  'Lex Scalp', 'w4r3z4s', '#Zinsi', '¥0_brkz', 'YT', 'Serg',
  'hau Nguyen Dinh', 'Spoony', 'Sam', 'Chris45', 'Ayze LYC', 'Dilaks',
];

const SEARCH_MIN = 8;            // search appears once the list needs scanning

// view-takeover shell — settings-screens grammar (module-local, house collision rule)
function appScreenShell(className, title, onBack) {
  const el = document.createElement('div');
  el.className = className;
  el.append(createTopbar({ variant: 'view', title, onBack }));
  const body = document.createElement('div');
  body.className = 'c-settings__body u-scroll';
  el.append(body);
  const live = document.createElement('p');
  live.className = 'c-settings__live';
  live.setAttribute('aria-live', 'polite');
  el.append(live);
  return { el, body, live };
}

/**
 * Downloads — createSettingsDownloads({ files, host, onBack, onOpenFile,
 * onDeleteFile, onClearAll, strings }).
 * files: [{ name, time }] (time = the opaque ctime string).
 * Free fn: setDownloads(el, files) — the clearFiles/addFile wholesale mirror.
 */
function createSettingsDownloads({
  files = [],
  host,
  onBack,
  onOpenFile,                    // (name) — ixian:open:<name>, fire-and-forget
  onDeleteFile,                  // (name, ctrl) — ixian:delete:<name>; C# re-pushes the list
  onClearAll,                    // (ctrl) — ixian:deleted; C# re-pushes (empty)
  strings = getStrings(),
} = {}) {
  const { el, body, live } = appScreenShell(
    'c-settings-dl', strings.downloads || 'Downloads', onBack);
  const hostFor = () => host || el.closest('.demo-phone') || undefined;

  /* search — frontend name filter (#67 chat-list precedent, no bridge) */
  let query = '';
  const search = createSearchField({
    placeholder: strings.searchDownloads || 'Search files',
    ariaLabel: strings.searchDownloads || 'Search files',
    strings,
    onInput: (v) => { query = v.trim().toLowerCase(); applyFilter(); },
  });
  const searchWrap = document.createElement('div');
  searchWrap.className = 'c-settings-dl__search';
  searchWrap.append(search);
  body.append(searchWrap);

  /* list card */
  const groupWrap = document.createElement('div');
  groupWrap.className = 'c-settings__groupwrap';
  const card = document.createElement('div');
  card.className = 'c-settings__group';
  groupWrap.append(card);
  body.append(groupWrap);

  /* empty state — also what a clearFiles push renders */
  const empty = document.createElement('div');
  empty.className = 'c-settings-dl__empty';
  const emptyDisc = document.createElement('span');
  emptyDisc.className = 'c-disc';
  emptyDisc.dataset.hue = 'info';
  emptyDisc.dataset.grad = String(discGrad('download'));
  emptyDisc.append(icon('download', { size: 16 }));
  const emptyText = document.createElement('p');
  emptyText.className = 'c-settings__note';
  emptyText.textContent = strings.downloadsEmpty || 'Files you receive in chats appear here.';
  empty.append(emptyDisc, emptyText);
  body.append(empty);

  /* no-matches note (search active, nothing left) */
  const noMatch = document.createElement('p');
  noMatch.className = 'c-settings__note c-settings-dl__nomatch';
  noMatch.textContent = strings.downloadsNoMatch || 'No files match your search.';
  noMatch.hidden = true;
  body.append(noMatch);

  /* clear-all — the ONE error-hue destructive row on this surface (#147⑤ reservation) */
  let clearWrap = null;
  if (onClearAll) {
    clearWrap = document.createElement('div');
    clearWrap.className = 'c-settings__groupwrap';
    const clearCard = document.createElement('div');
    clearCard.className = 'c-settings__group';
    const section = document.createElement('div');
    section.className = 'c-settings__section';
    const row = document.createElement('button');
    row.type = 'button';
    row.className = 'c-settings__row';
    const lab = document.createElement('span');
    lab.className = 'c-settings__row-label';
    const disc = document.createElement('span');
    disc.className = 'c-disc';
    disc.dataset.hue = 'error';
    disc.dataset.grad = String(discGrad('trash'));
    disc.append(icon('trash', { size: 16 }));
    lab.append(disc, document.createTextNode(strings.clearDownloads || 'Delete all downloads'));
    row.append(lab, icon('chevron-right', { size: 18 }));
    row.addEventListener('click', () => settingsConfirm({
      title: strings.clearDownloadsTitle || 'Delete all downloads?',
      bodyText: strings.deleteDownloadsBody || 'Received files are removed from this device. Senders keep theirs.',
      confirmLabel: strings.deleteConfirm || 'Delete',
      host: hostFor(), strings,
      run: (ctrl) => onClearAll(ctrl),     // sync throw handled inside settingsConfirm
    }));
    section.append(row);
    clearCard.append(section);
    clearWrap.append(clearCard);
    body.append(clearWrap);
  }

  const fileRow = ({ name, time }) => {
    const section = document.createElement('div');
    section.className = 'c-settings__section';
    const row = document.createElement('div');
    row.className = 'c-settings-dl__row';
    row.dataset.name = name;

    const open = document.createElement('button');
    open.type = 'button';
    open.className = 'c-settings-dl__open';
    const disc = document.createElement('span');
    disc.className = 'c-disc';
    disc.dataset.hue = 'info';
    disc.dataset.grad = String(discGrad('file-isr'));
    disc.append(icon('file-isr', { size: 16 }));
    const meta = document.createElement('span');
    meta.className = 'c-settings-dl__meta';
    const nm = document.createElement('span');
    nm.className = 'c-settings-dl__name';
    nm.textContent = name;                 // UNTRUSTED — textContent only
    meta.append(nm);
    if (time) {
      const tm = document.createElement('span');
      tm.className = 'c-settings-dl__time';
      tm.textContent = time;               // opaque locale string — never parsed
      meta.append(tm);
    }
    open.append(disc, meta);
    if (onOpenFile) open.addEventListener('click', () => onOpenFile(name));
    else open.disabled = true;
    row.append(open);

    if (onDeleteFile) {
      const del = document.createElement('button');
      del.type = 'button';
      del.className = 'c-settings-dl__del';
      del.setAttribute('aria-label',
        (strings.deleteFile || 'Delete {name}').split('{name}').join(name));
      del.append(icon('trash', { size: 18 }));
      del.addEventListener('click', () => settingsConfirm({
        title: strings.deleteFileTitle || 'Delete this file?',
        bodyText: (strings.deleteFileBody || '“{name}” is removed from this device.')
          .split('{name}').join(name),
        confirmLabel: strings.deleteConfirm || 'Delete',
        host: hostFor(), strings,
        run: (ctrl) => onDeleteFile(name, ctrl),
      }));
      row.append(del);
    }
    section.append(row);
    return section;
  };

  function applyFilter() {
    let visible = 0;
    for (const s of card.children) {
      const rowEl = s.querySelector('.c-settings-dl__row');
      const name = rowEl ? (rowEl.dataset.name || '') : '';
      const hit = !query || name.toLowerCase().includes(query);
      s.hidden = !hit;
      if (hit) visible++;
    }
    noMatch.hidden = !(card.childElementCount > 0 && visible === 0);
    live.textContent = query
      ? (strings.downloadsMatches || '{n} files match').split('{n}').join(String(visible))
      : '';
  }

  function render(list) {
    card.replaceChildren(...list.map(fileRow));
    const has = list.length > 0;
    groupWrap.hidden = !has;
    empty.hidden = has;
    searchWrap.hidden = list.length < SEARCH_MIN;
    if (clearWrap) clearWrap.hidden = !has;
    applyFilter();
  }
  render(files);

  el._dlRender = render;                   // setDownloads hook
  return el;
}

/** Wholesale list update — mirrors the clearFiles + addFile(name, ctime) push. */
function setDownloads(el, files = []) {
  if (el._dlRender) el._dlRender(files);
}

/**
 * Developer — createSettingsDev({ log, onBack, onSendLog, strings }).
 * Read-only log viewer + Copy + Send (Damir). The log lands as ONE text node
 * (unbounded legacy dumps — no per-line DOM).
 * Send log is §9-GATED by callback presence: NO bridge command exists — the
 * proposal is C# opening the OS email/share sheet with ixian.log attached
 * (target e.g. info@ixian.io; spec §9b ask ⑦). A mailto: fallback is NOT
 * honest here — the log dwarfs URL limits.
 * Free fn: setDevLog(el, text) — idempotent (the push may arrive twice).
 */
function createSettingsDev({
  log = '',
  onBack,
  onSendLog,                     // (ctrl) — §9: OS email/share with the log attached
  strings = getStrings(),
} = {}) {
  const { el, body, live } = appScreenShell(
    'c-settings-dev', strings.developer || 'Developer', onBack);

  const note = document.createElement('p');
  note.className = 'c-settings__note';
  note.textContent = strings.devNote || 'The Spixi log on this device. Read-only.';
  body.append(note);

  const pane = document.createElement('pre');
  pane.className = 'c-settings-dev__log u-scroll';
  pane.setAttribute('tabindex', '0');      // keyboard-scrollable region
  pane.setAttribute('aria-label', strings.devLog || 'Application log');
  body.append(pane);

  const waiting = document.createElement('p');
  waiting.className = 'c-settings__note c-settings-dev__waiting';
  waiting.textContent = strings.devWaiting || 'Waiting for the log…';
  body.append(waiting);

  const actions = document.createElement('div');
  actions.className = 'c-settings-dev__actions';

  const copyBtn = createButton({
    label: strings.copyLog || 'Copy log', type: 'outline', size: 44,
    icon: icon('copy', { size: 18 }),
    onClick: () => {
      const text = pane.textContent;
      if (!text) return;
      // fail-soft: clipboard can be absent/denied in the WebView (address-copy grammar)
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(
          () => { setSuccess(copyBtn, { label: strings.copied || 'Copied' }); },
          () => { live.textContent = strings.copyLogFailed || 'Couldn’t copy — select the log text instead.'; },
        );
      } else {
        live.textContent = strings.copyLogFailed || 'Couldn’t copy — select the log text instead.';
      }
    },
  });
  copyBtn.classList.add('c-settings-dev__copy');
  actions.append(copyBtn);

  /* Send log (Damir) — wallet-export grammar: latched, loading, success morph,
     sync throw → fail path (#141-m4). The share itself is C#'s (§9b ask ⑦). */
  if (onSendLog) {
    let sending = false;                   // latched (one share at a time)
    const sendBtn = createButton({
      label: strings.sendLog || 'Send log', type: 'outline', size: 44,
      icon: icon('share-3', { size: 18 }),
      onClick: () => {
        if (sending || !pane.textContent) return;
        sending = true;
        setLoading(sendBtn, true);
        const ctrl = appCtrl(
          () => {
            sending = false;
            setLoading(sendBtn, false);
            setSuccess(sendBtn, { label: strings.sent || 'Sent' });
          },
          (msg) => {
            sending = false;
            setLoading(sendBtn, false);
            live.textContent = msg || strings.sendLogFailed || 'Couldn’t send the log.';
          },
        );
        try {
          onSendLog(ctrl);
        } catch (ex) {
          ctrl.fail();                     // sync throw → unlatch + clear spinner (#141-m4)
        }
      },
    });
    sendBtn.classList.add('c-settings-dev__send');
    actions.append(sendBtn);
  }
  body.append(actions);

  const apply = (text) => {
    pane.textContent = text || '';         // UNTRUSTED — textContent only
    const has = !!text;
    pane.hidden = !has;
    waiting.hidden = has;
    actions.hidden = !has;
    if (has) pane.scrollTop = pane.scrollHeight;   // newest entries at the end
  };
  apply(log);

  el._devApply = apply;                    // setDevLog hook
  return el;
}

/** Idempotent whole-log replace — the legacy setLog(text) mirror. */
function setDevLog(el, text) {
  if (el._devApply) el._devApply(text);
}

/**
 * Contributors — createSettingsContributors({ contributors, onBack, strings }).
 * Static thank-you screen (legacy contributors.html port): art slot + the
 * names on a card. Illustration swaps into the art slot later
 * (illustrations-plan.md language decision).
 */
function createSettingsContributors({
  contributors = CONTRIBUTORS,
  onBack,
  strings = getStrings(),
} = {}) {
  const { el, body } = appScreenShell(
    'c-settings-contrib', strings.contributors || 'Contributors', onBack);

  /* art slot — token-styled placeholder (backup-hero precedent) */
  const art = document.createElement('div');
  art.className = 'c-settings-contrib__art';
  art.setAttribute('aria-hidden', 'true');
  const disc = document.createElement('span');
  disc.className = 'c-disc c-settings-contrib__art-disc';
  disc.dataset.hue = 'accent';
  disc.dataset.grad = String(discGrad('heart-handshake'));
  disc.append(icon('heart-handshake', { size: 32 }));
  art.append(disc);
  body.append(art);

  const lead = document.createElement('p');
  lead.className = 'c-settings__note c-settings-contrib__lead';
  lead.textContent = strings.contributorsLead ||
    'Spixi is better because these people cared. Special thanks to:';
  body.append(lead);

  const groupWrap = document.createElement('div');
  groupWrap.className = 'c-settings__groupwrap';
  const card = document.createElement('div');
  card.className = 'c-settings__group c-settings-contrib__card';
  const list = document.createElement('ul');
  list.className = 'c-settings-contrib__list';
  for (const name of contributors) {
    const li = document.createElement('li');
    li.className = 'c-settings-contrib__name';
    li.textContent = name;
    list.append(li);
  }
  card.append(list);
  groupWrap.append(card);
  body.append(groupWrap);

  return el;
}

/* ---- src/components/launch-shell.js ---- */
/**
 * launch-shell — welcome carousel · create · restore · retry · onboarding tail
 * (docs/launch-spec.md, Phase 1 #5 — the LAST Phase-1 surface). Absorbs the
 * five legacy launch pages (ARCHITECTURE §5 row 1): intro / intro_new /
 * intro_restore / intro_retry / onboarding. Bridge grammar (bridge-audit-A
 * §7–10, audit-B OnboardPage — FROZEN): introload · accept · language:<code> ·
 * appearance:<int> · create:<nick>:<password> · avatar · selectfile ·
 * restore:<password> · proceed:<password> · joinbot · finish · back.
 *
 * Interview #0 (Damir 2026-07-06): ① welcome carousel ② the #160 brand
 * treatment (fixed-dark pin + brand gradient + bare glowing logo) is
 * WELCOME-ONLY — create/restore/retry/tail are normal themed surfaces
 * ③ tail = backup nudge (backup-ux-spec §3.3) + joinbot step ④ [L2] the
 * window-pagehide scrub also lands on createLockScreen (lock-shell.js).
 *
 * PREMIUM REWORK (Damir demo pass 2026-07-06): single full-bleed screen —
 * 4-slide autoplay carousel (LEGACY step1–4 art + copy, dark set — the
 * shipped intro.html illustrations, reused verbatim) over always-pinned
 * CTAs · language pill + appearance control reuse the settings sheets
 * (settingsOptionSheet #148⑥ flags / settingsThemeSheet #147 preview tiles —
 * ONE picker grammar app-wide) · terms = fine print; the first Create/Restore
 * tap emits ixian:accept (continuing = agreeing — no checkbox) · welcome
 * rides the new --gradient-launch (Damir "more premium colors" ask; the lock
 * keeps --gradient-lock until he converges them).
 *
 * SECURITY.md: passwords live ONLY in field values, transiently — scrubbed on
 * back / ctrl.done / window pagehide (#162 grammar; the shell registers ONE
 * self-cleaning window listener that scrubs every password field it owns).
 * Passwords are NEVER trimmed. NO logging of any kind in this file
 * (smoke-guarded like lock-shell).
 *
 * C# parse hazards gated inline (launch-spec §1, the ENC_DELIM precedent):
 * ixian:create:<nick>:<password> — nick = text up to the FIRST ':' and the
 * password remainder is Replace(nick+":","")-ed, so a nick containing ':' or
 * a password containing '<nick>:' would be silently corrupted. Never sent.
 *
 * createLaunchShell({ view, termsRequired, version, onLanguage(code),
 *   onAppearance(int), onAcceptTerms, onGoCreate, onGoRestore,
 *   onCreateAccount(nick, pass, ctrl), onPickAvatar, onSelectFile,
 *   onRestore(pass, ctrl), onRetry(pass, ctrl), onBackupNow, onJoinBot,
 *   onFinish, onBack(view), strings, host })
 *   onGoCreate/onGoRestore (optional): override the welcome CTAs' INTERNAL
 *   view switch — the native shell emits ixian:create / ixian:restore so C#
 *   navigates to the real LaunchCreatePage / LaunchRestorePage (each a separate
 *   WebView). Absent = internal show() (demo default).
 *   Ctrl contract (spec §3): one-shot done/fail; NO auto-release anywhere —
 *   create has no covering alert (indefinite loading, flag §6②); restore
 *   fails via showPasswordError → ctrl.fail(msg); retry's host maps
 *   removeLoadingOverlay → ctrl.fail('') = SILENT restore (the native alert
 *   already spoke — the unlock-screen grammar).
 *
 * Free fns (#44, C#→JS mirrors): setLaunchView(el, view) ·
 *   setLaunchVersion(el, v) ← setVersion · setLaunchTerms(el, required) ←
 *   showTerms · setLaunchAvatar(el, src) ← loadAvatar ·
 *   setLaunchFile(el, name) ← setUploadedFileName.
 */









const launchState = new WeakMap(); // el → st

const LAUNCH_VIEWS = ['welcome', 'create', 'restore', 'retry', 'tail'];

function launchCtrl(onDone, onFail) {            // one-shot (lockCtrl grammar)
  let used = false;
  return {
    done: (payload) => { if (used) return; used = true; onDone(payload); },
    fail: (msg) => { if (used) return; used = true; onFail(msg); },
  };
}

/* —— illustration slots ————————————————————————————————————
   Welcome slides reuse the SHIPPED legacy art verbatim (img/dark/onboarding/
   step1–4.svg, copied to src/demo/images/onboarding/ — Damir premium rework;
   the welcome is pinned dark so only the dark set rides). The backup nudge
   keeps its placeholder (nano-banana asset #6 pending, illustrations-plan §2
   palette; data-placeholder = the swap stays deliberate). Static strings
   only — innerHTML carries no user data. */
const ILLO_G = (id) => `<defs><linearGradient id="${id}" x1="0" y1="0" x2="1" y2="1">`
  + '<stop offset="0" stop-color="#3050bd"/><stop offset="1" stop-color="#515ee6"/>'
  + '</linearGradient></defs>';
const ILLOS = {
  backup:
    `<svg viewBox="0 0 240 240" xmlns="http://www.w3.org/2000/svg">${ILLO_G('ilg-b')}`
    + '<circle cx="120" cy="126" r="84" fill="#e3e4fe"/>'
    + '<path d="M120 44 L180 66 V132 Q180 178 120 200 Q60 178 60 132 V66 Z" fill="url(#ilg-b)"/>'
    + '<rect x="94" y="92" width="52" height="68" rx="10" fill="#f9fafb"/>'
    + '<circle cx="110" cy="110" r="7" fill="#769dff"/>'
    + '<circle cx="130" cy="110" r="7" fill="#b7c9f4"/>'
    + '<rect x="104" y="128" width="32" height="8" rx="4" fill="#cbcffe"/>'
    + '<rect x="104" y="142" width="24" height="8" rx="4" fill="#cbcffe"/>'
    + '</svg>',
};

function illoSlot(name) {
  const slot = document.createElement('div');
  slot.className = 'c-launch__illo';
  slot.dataset.illo = name;                      // illustrations-plan naming
  slot.dataset.placeholder = 'true';             // real-asset swap = deliberate
  slot.setAttribute('aria-hidden', 'true');      // decorative — copy carries meaning
  slot.innerHTML = ILLOS[name] || '';
  return slot;
}

/* —— view plumbing ———————————————————————————————————————————— */

function show(st, view) {
  st.view = view;
  st.root.dataset.view = view;
  for (const [name, node] of Object.entries(st.views)) node.hidden = name !== view;
}

const errLine = () => {
  const err = document.createElement('p');
  err.className = 'c-lock__error';               // one error grammar (lock kinship)
  err.setAttribute('role', 'alert');
  err.hidden = true;
  return err;
};

const textInput = ({ label, name }) => {
  const input = document.createElement('input');
  input.type = 'text';
  input.className = 'c-launch__input';
  input.autocomplete = 'off';
  input.spellcheck = false;
  input.placeholder = label;
  input.setAttribute('aria-label', label);
  if (name) input.dataset.field = name;
  return input;
};

/* —— welcome (the ONLY brand view — #160 treatment; premium rework) ——— */

function hostEl(st) {
  return st.opts.host || st.root.closest('.demo-phone') || undefined;
}

// #148⑥ inventory shape (settings parity — flags emoji now, SVG swaps later);
// overridable via opts.languages, real list ships with i18n (Phase 3)
const LAUNCH_LANGS = [
  { code: 'en-us', label: 'English', flag: '🇺🇸' },
  { code: 'zh-cn', label: '中文', flag: '🇨🇳' },
  { code: 'es-co', label: 'Español', flag: '🇨🇴' },
  { code: 'de-de', label: 'Deutsch', flag: '🇩🇪' },
  { code: 'fr-fr', label: 'Français', flag: '🇫🇷' },
  { code: 'it-it', label: 'Italiano', flag: '🇮🇹' },
  { code: 'ja-jp', label: '日本語', flag: '🇯🇵' },
  { code: 'pt-br', label: 'Português (Brasil)', flag: '🇧🇷' },
  { code: 'ru-ru', label: 'Русский', flag: '🇷🇺' },
  { code: 'sl-si', label: 'Slovenščina', flag: '🇸🇮' },
  { code: 'sr-sp', label: 'Srpski', flag: '🇷🇸' },
];

function buildWelcome(st) {
  const { opts } = st;
  const strings = st.strings;
  const v = document.createElement('div');
  v.className = 'c-launch__welcome';
  v.dataset.theme = 'dark';                      // #20/#160 subtree pin — welcome only

  // — floating top controls: language pill + appearance. BOTH open the
  //   settings sheets (one picker grammar app-wide; the sheets mount on the
  //   host OUTSIDE the dark pin — the lock hatch-modal precedent) —
  const top = document.createElement('div');
  top.className = 'c-launch__top';

  const languages = (opts.languages && opts.languages.length) ? opts.languages : LAUNCH_LANGS;
  st.language = opts.language || languages[0].code;
  const langPill = document.createElement('button');
  langPill.type = 'button';
  langPill.className = 'c-launch__pill';
  langPill.setAttribute('aria-haspopup', 'dialog');
  const langFlag = document.createElement('span');
  langFlag.className = 'c-launch__pill-flag';
  langFlag.setAttribute('aria-hidden', 'true');
  const langLabel = document.createElement('span');
  langLabel.className = 'c-launch__pill-label';
  const syncLang = () => {
    const cur = languages.find((l) => l.code === st.language) || languages[0];
    langFlag.textContent = cur.flag || '';
    langFlag.hidden = !cur.flag;
    langLabel.textContent = cur.label;
    langPill.setAttribute('aria-label', (strings.language || 'Language') + ': ' + cur.label);
  };
  syncLang();
  langPill.append(langFlag, langLabel, icon('chevron-down', { size: 16 }));
  langPill.addEventListener('click', () => {
    settingsOptionSheet({
      title: strings.language || 'Language',
      options: languages.map((l) => ({ value: l.code, label: l.label, flag: l.flag })),
      current: st.language,
      host: hostEl(st),
      strings,
      commit: (code, ctrl) => {
        // legacy ixian:language persists + reloads intro; fire-and-forget here
        try { if (opts.onLanguage) opts.onLanguage(code); } catch { /* pref */ }
        ctrl.done();
      },
      onPicked: (o) => { if (o) { st.language = o.value; syncLang(); } },
    });
  });

  const themeBtn = document.createElement('button');
  themeBtn.type = 'button';
  themeBtn.className = 'c-launch__pill c-launch__pill--icon';
  themeBtn.setAttribute('aria-label', strings.appearance || 'Appearance');
  themeBtn.setAttribute('aria-haspopup', 'dialog');
  themeBtn.append(icon('adjustments-alt', { size: 18 }));
  let themeCurrent = 0;                          // ThemeAppearance: system (flag §6⑥)
  themeBtn.addEventListener('click', () => {
    // #147 preview tiles — the pick stays VISIBLE on the pinned-dark welcome
    settingsThemeSheet({
      current: themeCurrent,
      host: hostEl(st),
      strings,
      commit: (val, ctrl) => {
        try { if (opts.onAppearance) opts.onAppearance(val); } catch { /* pref */ }
        ctrl.done();
      },
      onPicked: (o) => { if (o) themeCurrent = o.value; },
    });
  });
  top.append(langPill, themeBtn);
  v.append(top);

  const logo = document.createElement('span');
  logo.className = 'c-launch__logo';             // bare glowing glyph (#160, no disc)
  logo.setAttribute('aria-hidden', 'true');
  logo.append(icon('logo', { size: 44 }));
  v.append(logo);

  // — carousel: the SHIPPED legacy tour (step1–4 art + en-us copy verbatim);
  //   swipe + dots + arrows + gentle autoplay —
  const car = document.createElement('div');
  car.className = 'c-launch__carousel';
  const track = document.createElement('div');
  track.className = 'c-launch__track';
  car.append(track);

  const base = opts.illustrationBase || 'images/onboarding/';
  const defs = [
    {
      img: base + 'step1.svg',
      title: strings.slide1Title || 'Built for you. Owned by you.',
      copy: strings.slide1Copy || 'No servers, no middlemen. Every message is encrypted and stays on your device — delivered straight to your contact, and to no one else.',
    },
    {
      img: base + 'step2.svg',
      title: strings.slide2Title || 'No phone number. No email. Just a nickname.',
      copy: strings.slide2Copy || 'Your unique Spixi address is the only identity you need. Sign up in seconds and share nothing personal — the account is yours alone.',
    },
    {
      img: base + 'step3.svg',
      title: strings.slide3Title || 'Send money like you send a message.',
      copy: strings.slide3Copy || 'A private IXI wallet lives inside every chat. Send and receive payments in a tap — as simple and instant as saying hello.',
    },
    {
      img: base + 'step4.svg',
      title: strings.slide4Title || 'Mini Apps, right inside your chats.',
      copy: strings.slide4Copy || 'Play games, run tools, chat with on-device AI, or automate your world — all without ever leaving the conversation.',
    },
  ];
  const slides = defs.map((s, i) => {
    const slide = document.createElement('div');
    slide.className = 'c-launch__slide';
    slide.setAttribute('role', 'group');
    slide.setAttribute('aria-label', (i + 1) + ' / ' + defs.length);
    const img = document.createElement('img');
    img.className = 'c-launch__illo-img';
    img.src = s.img;
    img.alt = '';                                // decorative — the copy carries meaning
    img.draggable = false;
    img.addEventListener('error', () => { img.hidden = true; }, { once: true });
    slide.append(img);
    const h = document.createElement('h1');
    h.className = 'c-launch__slide-title';
    h.textContent = s.title;
    const p = document.createElement('p');
    p.className = 'c-launch__slide-copy';
    p.textContent = s.copy;
    slide.append(h, p);
    track.append(slide);
    return slide;
  });

  // dots (tablist; ←/→ keyboard)
  const dots = document.createElement('div');
  dots.className = 'c-launch__dots';
  dots.setAttribute('role', 'tablist');
  dots.setAttribute('aria-label', strings.introPages || 'Introduction');
  const dotBtns = defs.map((s, i) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'c-launch__dot';
    b.setAttribute('role', 'tab');
    b.setAttribute('aria-label', s.title);
    b.addEventListener('click', () => { stopAuto(); go(i); });
    dots.append(b);
    return b;
  });
  dots.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowRight') { stopAuto(); go(st.slide + 1); dotBtns[st.slide].focus(); }
    if (e.key === 'ArrowLeft') { stopAuto(); go(st.slide - 1); dotBtns[st.slide].focus(); }
  });

  st.slide = 0;
  const go = (i) => {
    st.slide = Math.max(0, Math.min(defs.length - 1, i));
    track.style.transform = 'translateX(' + (st.slide * -100) + '%)';
    slides.forEach((s, k) => s.setAttribute('aria-hidden', String(k !== st.slide)));
    dotBtns.forEach((b, k) => {
      b.setAttribute('aria-selected', String(k === st.slide));
      b.tabIndex = k === st.slide ? 0 : -1;      // roving tabindex
    });
  };

  // gentle autoplay (premium-tour idiom): wraps every 5s until the user takes
  // control (any manual nav/swipe = theirs now); prefers-reduced-motion = off;
  // self-stops when the shell leaves the DOM (demo/jsdom re-creation guard)
  let autoTimer = null;
  const stopAuto = () => { if (autoTimer) { clearInterval(autoTimer); autoTimer = null; } };
  const reduced = typeof matchMedia === 'function'
    && matchMedia('(prefers-reduced-motion: reduce)').matches;
  // only run autoplay when this shell actually BOOTS at welcome — on the native
  // form/tail pages every view is built (welcome hidden), and a ticking timer on
  // a hidden welcome is pure waste (go() is view-gated anyway). Demo boots welcome.
  if (!reduced && (st.opts.view || 'welcome') === 'welcome') {
    autoTimer = setInterval(() => {
      if (!v.isConnected) { stopAuto(); return; }
      if (st.view === 'welcome') go((st.slide + 1) % defs.length);
    }, 5000);
  }
  st.stopAuto = stopAuto;

  // pointer swipe (pan-y stays native — CSS touch-action)
  let downX = null;
  car.addEventListener('pointerdown', (e) => { downX = e.clientX; });
  car.addEventListener('pointerup', (e) => {
    if (downX === null) return;
    const dx = e.clientX - downX;
    downX = null;
    if (Math.abs(dx) < 40) return;               // sanctioned: swipe threshold
    stopAuto();
    go(st.slide + (dx < 0 ? 1 : -1));
  });

  v.append(car, dots);

  // — CTAs: always enabled, pinned; internal routing (the shell ABSORBS the
  //   legacy pages). CONSENT moved to the create/restore forms (Damir
  //   2026-07-06): the welcome is a clean brand choice, and ixian:accept now
  //   fires at the BINDING action (the actual create/restore commit), not here —
  const ctas = document.createElement('div');
  ctas.className = 'c-launch__ctas';
  const createBtn = createButton({ label: strings.createCta || 'Create new account', size: 56, width: 'full' });
  const restoreBtn = createButton({ label: strings.restoreCta || 'Restore existing account', type: 'outline', size: 56, width: 'full' });
  // The welcome CTAs route INTERNALLY by default (the shell absorbs the legacy
  // pages — demo/SPA behavior). On the REAL bridge the five legacy launch pages
  // still exist as separate C# WebViews, so the native shell passes onGoCreate/
  // onGoRestore to emit the NAVIGATION verbs (ixian:create / ixian:restore) and
  // let C# push LaunchCreatePage / LaunchRestorePage instead of switching in
  // place (a bare LaunchPage can't process create:<nick>:<password>). Additive,
  // backward-compatible: absent hook = the internal show() (unchanged demo).
  createBtn.addEventListener('click', () => {
    stopAuto();
    if (opts.onGoCreate) { try { opts.onGoCreate(); } catch { /* nav */ } }
    else show(st, 'create');
  });
  restoreBtn.addEventListener('click', () => {
    stopAuto();
    if (opts.onGoRestore) { try { opts.onGoRestore(); } catch { /* nav */ } }
    else show(st, 'restore');
  });
  ctas.append(createBtn, restoreBtn);
  v.append(ctas);

  const version = document.createElement('p');
  version.className = 'c-launch__version';
  version.hidden = true;
  v.append(version);

  st.els.version = version;
  go(0);
  return v;
}

/* —— legal docs + consent (shared by create/restore) ———————————————————
   Damir 2026-07-06: consent lives at the BINDING action (the create/restore
   commit), not on the welcome nav tap. Terms + Privacy open IN-APP in one
   sheet renderer; ixian:accept fires once, on the first commit. */

// LEGAL COPY — ENGLISH ONLY (Damir decision, DECISIONS #169). The Terms of Use and
// Privacy Policy are intentionally NOT localized: they have no `strings.*` dictionary
// entry, so every locale renders this English text by design. Localizing legal copy
// requires per-jurisdiction legal review and is out of scope for the i18n batch. Their
// TITLES (termsTitle / privacyTitle) ARE translated.
const TERMS_DEFAULT = 'Spixi is a decentralised, self-custodial app on the Ixian Platform. You are solely responsible for your wallet, backup file and password — no other way to recover them exists. IXI Labs collects no personal data. You must be at least 16 years old (or the higher minimum age your country requires) to use Spixi.\n\nThe full document is provided in English only.';
const PRIVACY_DEFAULT = 'IXI Labs does not collect any personal data through the Spixi app. No phone number or email is required, your messages stay on your device, and IXI Labs cannot access your message history or wallet keys.\n\nThe full Privacy Policy is provided in English only.';

function openDocSheet(st, title, text) {
  const strings = st.strings;
  const bodyEl = document.createElement('div');
  bodyEl.className = 'c-launch__terms-body u-scroll';
  // inline [label](https://…) → anchors (validated https only); the rest is
  // plain text nodes. Content is app-controlled (strings), never user input.
  const appendRich = (el, s) => {
    const re = /\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g;
    let last = 0, m;
    while ((m = re.exec(s))) {
      if (m.index > last) el.append(s.slice(last, m.index));
      const a = document.createElement('a');
      a.className = 'c-launch__link';
      a.href = m[2];
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      a.textContent = m[1];
      el.append(a);
      last = m.index + m[0].length;
    }
    if (last < s.length) el.append(s.slice(last));
  };
  // "# " = heading, "- " = list item, else a paragraph. Markers are stripped —
  // the TEXT stays verbatim (text nodes + validated links only, XSS-safe).
  let list = null;
  for (const raw of String(text).split('\n')) {
    const line = raw.replace(/\r$/, '');       // CRLF safety only — deliberately not trimmed (passwords are never trimmed; guard-counted)
    if (!line) { list = null; continue; }
    if (line.startsWith('# ')) {
      list = null;
      const h = document.createElement('h4');
      h.className = 'c-launch__terms-h';
      h.textContent = line.slice(2);
      bodyEl.append(h);
    } else if (line.startsWith('- ')) {
      if (!list) { list = document.createElement('ul'); list.className = 'c-launch__terms-list'; bodyEl.append(list); }
      const li = document.createElement('li');
      appendRich(li, line.slice(2));
      list.append(li);
    } else {
      list = null;
      const p = document.createElement('p');
      appendRich(p, line);
      bodyEl.append(p);
    }
  }
  const sheet = createSheet({ content: bodyEl, host: hostEl(st), title, strings });
  // explicit close affordance (scrim tap + Esc still work) — obvious corner tap
  const closeBtn = document.createElement('button');
  closeBtn.type = 'button';
  closeBtn.className = 'c-launch__sheet-close';
  closeBtn.setAttribute('aria-label', strings.close || 'Close');
  closeBtn.append(icon('x', { size: 20 }));
  closeBtn.addEventListener('click', () => closeSheet(sheet));
  sheet.append(closeBtn);
  openSheet(sheet);
}

// one-shot ixian:accept — emitted at the binding action (create/restore commit)
function emitAccept(st) {
  if (!st.termsRequired || st.acceptSent) return;
  st.acceptSent = true;
  try { if (st.opts.onAcceptTerms) st.opts.onAcceptTerms(); } catch { /* pref */ }
}

// consent line for the commit screens: "{lead} [Terms of Use] and acknowledge
// the [Privacy Policy]." — both open IN-APP (openDocSheet)
function consentLine(st, lead) {
  const strings = st.strings;
  const fine = document.createElement('p');
  fine.className = 'c-launch__fineprint';
  fine.append((lead || 'By continuing, you agree to the') + ' ');
  const termsLink = document.createElement('button');
  termsLink.type = 'button';
  termsLink.className = 'c-launch__link';
  termsLink.textContent = strings.termsLink || 'Terms of Use';
  termsLink.addEventListener('click', () => openDocSheet(st, strings.termsTitle || 'Terms of Use', strings.termsBody || TERMS_DEFAULT));
  fine.append(termsLink);
  fine.append(' ' + (strings.finePrintAck || 'and acknowledge the') + ' ');
  const privacyLink = document.createElement('button');
  privacyLink.type = 'button';
  privacyLink.className = 'c-launch__link';
  privacyLink.textContent = strings.privacyLink || 'Privacy Policy';
  privacyLink.addEventListener('click', () => openDocSheet(st, strings.privacyTitle || 'Privacy Policy', strings.privacyBody || PRIVACY_DEFAULT));
  fine.append(privacyLink, '.');
  return fine;
}

/* —— create (themed form view) ————————————————————————————————— */

function buildCreate(st) {
  const { opts } = st;
  const strings = st.strings;
  const v = document.createElement('div');
  v.className = 'c-launch__view';
  v.dataset.launchView = 'create';

  const pw = passwordField({ label: strings.password || 'Password', strings });               // new-password (group label carries "Wallet")
  const rp = passwordField({ label: strings.repeatPassword || 'Confirm password', strings });  // new-password
  const scrub = () => { pw.input.value = ''; rp.input.value = ''; pw.mask(); rp.mask(); };
  st.scrubs.push(scrub);

  v.append(createTopbar({
    variant: 'view',
    title: strings.createTitle || 'Create your account',
    backLabel: strings.back || 'Back',
    onBack: () => {
      scrub();                                   // SECURITY §5: scrub before leaving
      show(st, 'welcome');
      try { if (opts.onBack) opts.onBack('create'); } catch { /* nav */ }
    },
  }));

  const body = document.createElement('div');
  body.className = 'c-launch__body u-scroll';

  // — Profile group (Damir 2026-07-06 UX: two LABELLED sections read better than
  //   three anonymous stacked inputs). Avatar + nickname belong together —
  const gProfile = document.createElement('div');
  gProfile.className = 'c-launch__group';
  const lProfile = document.createElement('p');
  lProfile.className = 'c-launch__group-label';
  lProfile.textContent = strings.createProfileLabel || 'Your profile';
  gProfile.append(lProfile);

  // avatar preview: identity forms as the nick is typed (deterministic hue —
  // the avatar system IS the identity imagery, illustrations-plan §2)
  const avRow = document.createElement('div');
  avRow.className = 'c-launch__avatar';
  const avSlot = document.createElement('span');
  avSlot.className = 'c-launch__avatar-slot';
  const renderAvatar = () => {
    avSlot.replaceChildren(createAvatar({
      src: st.avatarSrc || null,
      name: nick.value.trim() || '·',
      size: 96,
    }));
  };
  const avBtn = createButton({ label: strings.addPhoto || 'Add a photo', type: 'outline', size: 44 });
  avBtn.addEventListener('click', () => {
    // ixian:avatar → native picker → loadAvatar(path) → setLaunchAvatar
    try { if (opts.onPickAvatar) opts.onPickAvatar(); } catch { /* picker */ }
  });
  avRow.append(avSlot, avBtn);
  const nick = textInput({ label: strings.nickname || 'Nickname', name: 'nick' });
  nick.addEventListener('input', () => { if (!st.avatarSrc) renderAvatar(); setError(''); });
  gProfile.append(avRow, nick);
  body.append(gProfile);

  // — Wallet-password group: the two secrets + the length hint, under one label —
  const gSec = document.createElement('div');
  gSec.className = 'c-launch__group';
  const lSec = document.createElement('p');
  lSec.className = 'c-launch__group-label';
  lSec.textContent = strings.createPasswordLabel || 'Wallet password';
  gSec.append(lSec, pw.wrap, rp.wrap);
  // proactive password condition (BE requires ENC_MIN) — shown UP FRONT, not
  // only as a post-submit error (Damir 2026-07-06)
  const hint = document.createElement('p');
  hint.className = 'c-launch__hint';
  hint.textContent = (strings.passwordHint || 'Use at least {n} characters.').replace('{n}', String(ENC_MIN));
  gSec.append(hint);
  body.append(gSec);

  const err = errLine();
  body.append(err);

  // prominent recovery callout (Damir 2026-07-06: "make it impossible to miss")
  // — self-custody has no backdoor. A tinted panel, not a quiet footnote.
  const warn = document.createElement('div');
  warn.className = 'c-launch__callout';
  warn.setAttribute('role', 'note');
  const warnTitle = document.createElement('p');
  warnTitle.className = 'c-launch__callout-title';
  warnTitle.textContent = strings.createWarnTitle || 'Spixi doesn’t store your password.';
  const warnBody = document.createElement('p');
  warnBody.className = 'c-launch__callout-body';
  warnBody.textContent = strings.createWarnBody
    || 'Without it and your backup file, your account and wallet can’t be recovered — not even by us.';
  warn.append(warnTitle, warnBody);
  body.append(warn);
  v.append(body);

  const footer = document.createElement('div');
  footer.className = 'c-launch__footer';
  // consent at the binding action, right above the commit button (Damir 2026-07-06)
  const consent = consentLine(st, strings.createConsent || 'By creating an account, you agree to the');
  const cta = createButton({ label: strings.createSubmit || 'Create my account', size: 56, width: 'full' });
  footer.append(consent, cta);
  v.append(footer);

  const setError = (msg, focusEl) => {
    err.textContent = msg;
    err.hidden = !msg;
    if (msg && focusEl) focusEl.focus();
  };
  pw.input.addEventListener('input', () => setError(''));
  rp.input.addEventListener('input', () => setError(''));

  let inFlight = false;
  const submit = () => {
    if (inFlight) return;
    const name = nick.value.trim();              // nick IS trimmed (display name); passwords NEVER
    const p = pw.input.value, r = rp.input.value;
    if (!name) return setError(strings.nickEmpty || 'Pick a nickname.', nick);
    if (name.includes(':')) {
      // C# splits create:<nick>:<password> on the FIRST ':' (launch-spec §1)
      return setError(strings.nickColon || 'Nicknames can’t contain “:”.', nick);
    }
    if (!p) return setError(strings.passwordEmpty2 || 'Choose a wallet password.', pw.input);
    if (p.length < ENC_MIN) {
      return setError((strings.newTooShort || 'The password needs at least {n} characters.').replace('{n}', String(ENC_MIN)), pw.input);
    }
    if (p !== r) return setError(strings.repeatMismatch || 'The passwords don’t match.', rp.input);
    if (p.includes(name + ':')) {
      // Replace(nick+":","") corruption hazard — never sent (launch-spec §1; §9 C# ask)
      return setError(strings.badPassword || 'That password contains an unsupported character sequence.', pw.input);
    }
    setError('');
    inFlight = true;
    nick.disabled = true; pw.input.disabled = true; rp.input.disabled = true; avBtn.disabled = true;
    setLoading(cta, true);
    // NO auto-release (spec §2.2): wallet generation takes seconds and there
    // is no covering native alert — the morph is the loading truth (flag §6②).
    const ctrl = launchCtrl(
      () => {                                    // C# navigates to Home; shell → tail
        inFlight = false;
        setLoading(cta, false);
        setSuccess(cta, { label: strings.created || 'Account created' });
        scrub();                                 // SECURITY §5
        setTimeout(() => {
          nick.disabled = false; pw.input.disabled = false; rp.input.disabled = false; avBtn.disabled = false;
          show(st, 'tail');
        }, 900);                                 // the encpass morph beat
      },
      (msg) => {
        inFlight = false;
        nick.disabled = false; pw.input.disabled = false; rp.input.disabled = false; avBtn.disabled = false;
        setLoading(cta, false);
        if (msg) setError(msg, pw.input);
      },
    );
    emitAccept(st);                              // consent at the binding action (spec §5)
    try {
      if (opts.onCreateAccount) opts.onCreateAccount(name, p, ctrl); else ctrl.done();
    } catch { ctrl.fail(strings.createFailed || 'Something went wrong creating the account.'); } // #141-m4
  };
  cta.addEventListener('click', submit);
  rp.input.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });

  renderAvatar();
  st.renderAvatar = renderAvatar;
  return v;
}

/* —— restore (themed form view) ———————————————————————————————— */

function buildRestore(st) {
  const { opts } = st;
  const strings = st.strings;
  const v = document.createElement('div');
  v.className = 'c-launch__view';
  v.dataset.launchView = 'restore';

  const pw = passwordField({ label: strings.walletPassword || 'Wallet password', current: true, strings }); // existing secret — off
  const scrub = () => { pw.input.value = ''; pw.mask(); };
  st.scrubs.push(scrub);

  v.append(createTopbar({
    variant: 'view',
    title: strings.restoreTitle || 'Restore your account',
    backLabel: strings.back || 'Back',
    onBack: () => {
      scrub();
      show(st, 'welcome');
      try { if (opts.onBack) opts.onBack('restore'); } catch { /* nav */ }
    },
  }));

  const body = document.createElement('div');
  body.className = 'c-launch__body u-scroll';

  // — premium hero (Damir 2026-07-06: "more premium; move the input+button
  //   lower"; premium round 2: the SHIPPED legacy restore illustration + a warm
  //   welcome-back line anchor the top, the form group drops toward the CTA
  //   (c-launch__lower margin-top:auto) —
  const base = opts.illustrationBase || 'images/onboarding/';
  const hero = document.createElement('div');
  hero.className = 'c-launch__hero';
  const heroIllo = document.createElement('img');
  heroIllo.className = 'c-launch__hero-illo';
  heroIllo.src = base + 'restore.svg';           // legacy restore art (dark set — launch is pinned dark)
  heroIllo.alt = '';                             // decorative — the copy carries meaning
  heroIllo.draggable = false;
  heroIllo.addEventListener('error', () => { heroIllo.hidden = true; }, { once: true });
  const heroTitle = document.createElement('h1');   // the view's primary heading (topbar title is a nav label div)
  heroTitle.className = 'c-launch__hero-title';
  heroTitle.textContent = strings.restoreHeroTitle || 'Welcome back';
  const heroCopy = document.createElement('p');
  heroCopy.className = 'c-launch__hero-copy';
  heroCopy.textContent = strings.restoreHeroCopy
    || 'Choose your backup file and enter your wallet password to bring your account back to this device.';
  hero.append(heroIllo, heroTitle, heroCopy);
  body.append(hero);

  // — form group, pinned to the lower third above the CTA —
  const lower = document.createElement('div');
  lower.className = 'c-launch__lower';

  const card = document.createElement('div');
  card.className = 'c-launch__card';
  const fileBtn = createButton({
    label: strings.chooseFile || 'Choose backup file…',
    type: 'outline', size: 56, width: 'full', icon: icon('file-isr', { size: 20 }),
  });
  fileBtn.addEventListener('click', () => {
    try { if (opts.onSelectFile) opts.onSelectFile(); } catch { /* picker */ }
  });
  const fileRow = document.createElement('p');
  fileRow.className = 'c-launch__file';
  fileRow.hidden = true;
  const fileGlyph = document.createElement('span');
  fileGlyph.className = 'c-launch__file-check';
  fileGlyph.setAttribute('aria-hidden', 'true');
  fileGlyph.append(icon('check', { size: 16 }));
  const fileName = document.createElement('span');
  fileName.className = 'c-launch__file-name';    // textContent only — names are untrusted
  fileRow.append(fileGlyph, fileName);
  card.append(fileBtn, fileRow, pw.wrap);
  const err = errLine();
  card.append(err);
  lower.append(card);

  // honesty line kept (spec §2.3): self-custody has no recovery path
  const note = document.createElement('p');
  note.className = 'c-launch__note';
  note.textContent = strings.restoreNote
    || 'Restoring needs this file and your password. Spixi can’t recover either for you.';
  lower.append(note);
  body.append(lower);
  v.append(body);

  const footer = document.createElement('div');
  footer.className = 'c-launch__footer';
  // consent at the binding action, right above the commit button (Damir 2026-07-06)
  const consent = consentLine(st, strings.restoreConsent || 'By restoring your account, you agree to the');
  const cta = createButton({ label: strings.restoreSubmit || 'Restore account', size: 56, width: 'full' });
  footer.append(consent, cta);
  v.append(footer);

  const setError = (msg, focusEl) => {
    err.textContent = msg;
    err.hidden = !msg;
    if (msg && focusEl) focusEl.focus();
  };
  pw.input.addEventListener('input', () => setError(''));

  let inFlight = false;
  const submit = () => {
    if (inFlight) return;
    if (!st.fileName) return setError(strings.fileEmpty || 'Choose your backup file first.');
    const p = pw.input.value;                    // NOT trimmed
    if (!p) return setError(strings.passwordEmpty || 'Enter your wallet password.', pw.input);
    setError('');
    inFlight = true;
    pw.input.disabled = true; fileBtn.disabled = true;
    setLoading(cta, true);
    // no auto-release: restore HAS an explicit fail signal — the host maps
    // showPasswordError (+removeLoadingOverlay; one-shot latch absorbs the
    // double signal) → ctrl.fail(msg) (spec §2.3)
    const ctrl = launchCtrl(
      () => {                                    // C# navigates to Home
        inFlight = false;
        setLoading(cta, false);
        setSuccess(cta, { label: strings.restored || 'Restored' });
        scrub();
      },
      (msg) => {
        inFlight = false;
        pw.input.disabled = false; fileBtn.disabled = false;
        setLoading(cta, false);
        setError(msg || strings.restoreFailed || 'That password didn’t open the backup.', pw.input);
      },
    );
    emitAccept(st);                              // consent at the binding action (spec §5)
    try {
      if (opts.onRestore) opts.onRestore(p, ctrl); else ctrl.done();
    } catch { ctrl.fail(); }                     // #141-m4
  };
  cta.addEventListener('click', submit);
  pw.input.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });

  st.els.fileRow = fileRow;
  st.els.fileName = fileName;
  return v;
}

/* —— retry (boot: the SAVED password failed) ———————————————————— */

function buildRetry(st) {
  const { opts } = st;
  const strings = st.strings;
  const v = document.createElement('div');
  v.className = 'c-launch__view';
  v.dataset.launchView = 'retry';

  const pw = passwordField({ label: strings.walletPassword || 'Wallet password', current: true, strings });
  const scrub = () => { pw.input.value = ''; pw.mask(); };
  st.scrubs.push(scrub);

  v.append(createTopbar({
    variant: 'view',
    title: strings.retryTitle || 'Unlock your wallet',
    backLabel: strings.back || 'Back',
    onBack: () => {
      scrub();
      show(st, 'welcome');
      try { if (opts.onBack) opts.onBack('retry'); } catch { /* nav — legacy pop */ }
    },
  }));

  const body = document.createElement('div');
  body.className = 'c-launch__body u-scroll';
  const copy = document.createElement('p');
  copy.className = 'c-launch__note';
  copy.textContent = strings.retryCopy
    || 'Your wallet couldn’t be unlocked with the saved password. Enter it to continue.';
  body.append(copy);

  const card = document.createElement('div');
  card.className = 'c-launch__card';
  card.append(pw.wrap);
  const err = errLine();
  card.append(err);
  body.append(card);
  v.append(body);

  const footer = document.createElement('div');
  footer.className = 'c-launch__footer';
  const cta = createButton({ label: strings.proceed || 'Unlock', size: 56, width: 'full' });
  footer.append(cta);
  v.append(footer);

  const setError = (msg, focusEl) => {
    err.textContent = msg;
    err.hidden = !msg;
    if (msg && focusEl) focusEl.focus();
  };
  pw.input.addEventListener('input', () => setError(''));

  let inFlight = false;
  const submit = () => {
    if (inFlight) return;
    const p = pw.input.value;                    // NOT trimmed
    if (!p) return setError(strings.passwordEmpty || 'Enter your wallet password.', pw.input);
    setError('');
    inFlight = true;
    pw.input.disabled = true;
    setLoading(cta, true);
    const ctrl = launchCtrl(
      () => {                                    // C# loads the wallet + navigates
        inFlight = false;
        setLoading(cta, false);
        setSuccess(cta, { label: strings.unlocked || 'Unlocked' });
        scrub();
      },
      (msg) => {
        // wrong password = NATIVE alert + removeLoadingOverlay → host sends
        // fail('') = SILENT restore, value kept (the unlock-screen grammar,
        // spec §2.4); fail(msg) = inline (mock / future §9 signal)
        inFlight = false;
        pw.input.disabled = false;
        setLoading(cta, false);
        if (msg) setError(msg, pw.input); else pw.input.focus();
      },
    );
    try {
      if (opts.onRetry) opts.onRetry(p, ctrl); else ctrl.done();
    } catch { ctrl.fail(''); }                   // #141-m4 (silent — alert-covered path)
  };
  cta.addEventListener('click', submit);
  pw.input.addEventListener('keydown', (e) => { if (e.key === 'Enter') submit(); });

  return v;
}

/* —— onboarding tail: backup nudge → join step (spec §2.5) ————————— */

function buildTail(st) {
  const { opts } = st;
  const strings = st.strings;
  const v = document.createElement('div');
  v.className = 'c-launch__tail';
  v.dataset.step = 'backup';

  let finished = false;                          // finish is once (latch)
  const finish = () => {
    if (finished) return;
    finished = true;
    try { if (opts.onFinish) opts.onFinish(); } catch { /* nav — modal pops */ }
  };
  const toJoin = () => { v.dataset.step = 'join'; backupStep.hidden = true; joinStep.hidden = false; };

  // step 1 — backup nudge (backup-ux-spec §3.3: quiet Later is ALLOWED;
  // the standing settings-row state takes over from there)
  const backupStep = document.createElement('div');
  backupStep.className = 'c-launch__tail-step';
  backupStep.append(illoSlot('backup'));
  const bTitle = document.createElement('h1');
  bTitle.className = 'c-launch__slide-title';
  bTitle.textContent = strings.backupHeadline || 'One file protects everything';
  const bCopy = document.createElement('p');
  bCopy.className = 'c-launch__slide-copy';
  bCopy.textContent = strings.backupCopy
    || 'Your identity, wallet and contacts — encrypted with your password into a single backup file.';
  const backupBtn = createButton({ label: strings.backupCta || 'Back up now', size: 56, width: 'full' });
  backupBtn.addEventListener('click', () => {
    // integration (§9): onboarding-complete + the settings Backup screen —
    // no new verb; onboarding continues on return, so advance now
    try { if (opts.onBackupNow) opts.onBackupNow(); } catch { /* nav */ }
    toJoin();
  });
  const laterBtn = createButton({ label: strings.backupLater || 'Later', type: 'text', size: 56, width: 'full' });
  laterBtn.addEventListener('click', toJoin);
  backupStep.append(bTitle, bCopy, backupBtn, laterBtn);

  // step 2 — join the official bot (legacy onboarding.html joinbot/finish)
  const base = opts.illustrationBase || 'images/onboarding/';
  const joinStep = document.createElement('div');
  joinStep.className = 'c-launch__tail-step';
  joinStep.hidden = true;
  const jIllo = document.createElement('img');    // the SHIPPED legacy join-community art
  jIllo.className = 'c-launch__tail-illo';
  jIllo.src = base + 'join-community.svg';
  jIllo.alt = '';                                 // decorative — the copy carries meaning
  jIllo.draggable = false;
  jIllo.addEventListener('error', () => { jIllo.hidden = true; }, { once: true });
  const jTitle = document.createElement('h1');
  jTitle.className = 'c-launch__slide-title';
  jTitle.textContent = strings.joinTitle || 'Join the Spixi community';
  const jCopy = document.createElement('p');
  jCopy.className = 'c-launch__slide-copy';
  jCopy.textContent = strings.joinCopy
    || 'Say hi in the official Spixi group chat and get updates from the team.';
  const joinBtn = createButton({ label: strings.joinCta || 'Join the community', size: 56, width: 'full' });
  joinBtn.addEventListener('click', () => {
    if (finished) return;                        // one-shot: joinbot rides the finish latch
    try { if (opts.onJoinBot) opts.onJoinBot(); } catch { /* contact add — C#-side */ }
    finish();
  });
  const skipBtn = createButton({ label: strings.joinSkip || 'Not now', type: 'text', size: 56, width: 'full' });
  skipBtn.addEventListener('click', finish);
  joinStep.append(jIllo, jTitle, jCopy, joinBtn, skipBtn);

  v.append(backupStep, joinStep);
  return v;
}

/* —— shell ————————————————————————————————————————————————— */

function createLaunchShell(opts = {}) {
  const { view = 'welcome', termsRequired = false, version = '', strings = getStrings() } = opts;
  const el = document.createElement('section');
  el.className = 'c-launch';
  el.dataset.theme = 'dark';                       // premium round 2: the WHOLE launch is
  // one continuous fixed-dark brand surface on --gradient-launch (welcome→create→
  // restore→retry→tail). The lock screen precedent: forms live on the gradient with
  // glass fields. Sheets still mount on the host OUTSIDE this pin (themed pickers).

  const st = {
    opts, strings,
    root: el,
    view: null,
    slide: 0,
    termsRequired: !!termsRequired,
    acceptSent: false,
    language: '',
    avatarSrc: null,
    fileName: '',
    views: {},
    els: {},
    scrubs: [],                                  // every password scrub, one registry
  };
  launchState.set(el, st);

  st.views.welcome = buildWelcome(st);
  st.views.create = buildCreate(st);
  st.views.restore = buildRestore(st);
  st.views.retry = buildRetry(st);
  st.views.tail = buildTail(st);
  el.append(st.views.welcome, st.views.create, st.views.restore, st.views.retry, st.views.tail);

  // SECURITY §5 + #162 grammar: ONE window-level pagehide listener scrubs
  // every password field the shell owns (backgrounded WebView). The shell IS
  // the page (no unmount hook), so the listener self-cleans on the first
  // pagehide after the element leaves the DOM (demo/jsdom re-creation guard).
  const onPageHide = () => {
    if (!el.isConnected) { window.removeEventListener('pagehide', onPageHide); return; }
    st.scrubs.forEach((s) => s());
  };
  window.addEventListener('pagehide', onPageHide);

  setLaunchVersion(el, version);
  show(st, LAUNCH_VIEWS.includes(view) ? view : 'welcome');
  return el;
}

/** Entry-point router mirror — C# repoints LaunchRetryPage with view:'retry',
 *  the HomePage onboarding modal with view:'tail' (#44 free-fn grammar). */
function setLaunchView(el, view) {
  const st = launchState.get(el);
  if (!st || !LAUNCH_VIEWS.includes(view) || st.view === view) return;
  show(st, view);
}

/** ← setVersion(Config.version) — quiet welcome footer line. */
function setLaunchVersion(el, v) {
  const st = launchState.get(el);
  if (!st) return;
  st.els.version.textContent = v || '';
  st.els.version.hidden = !v;
}

/** ← showTerms() — C# only calls it when terms are NOT yet accepted. Premium
 *  rework: consent is fine-print (continuing = agreeing), so this only arms
 *  the one-shot ixian:accept emitted on the first Create/Restore tap. */
function setLaunchTerms(el, required) {
  const st = launchState.get(el);
  if (!st) return;
  st.termsRequired = !!required;
  if (st.termsRequired) st.acceptSent = false;   // arm the one-shot on (re-)gate
}

/** ← loadAvatar(path) — native picker result lands as the create preview. */
function setLaunchAvatar(el, src) {
  const st = launchState.get(el);
  if (!st) return;
  st.avatarSrc = src || null;
  st.renderAvatar();
}

/** ← setUploadedFileName(name) — restore file pick confirmation. */
function setLaunchFile(el, name) {
  const st = launchState.get(el);
  if (!st) return;
  st.fileName = name || '';
  st.els.fileName.textContent = st.fileName;
  st.els.fileRow.hidden = !st.fileName;
}

/* ---- src/components/backup-nudge.js ---- */
/**
 * c-backup-nudge — the periodic "don't forget to back up" prompt.
 *
 * Legacy parity (Damir 2026-07-06 — supersedes backup-ux-spec §2.2 "not
 * periodic"): legacy HomePage.updateScreen → displayBackupReminder() shows the
 * index.html #backup-prompt slide-up at most once per Config.backupReminder
 * (30 days), tracked C#-side in Preferences("backupReminderTimestamp").
 * That C# cadence is UNCHANGED — the FE owns NO timer and NO storage. At
 * integration, the legacy C#→JS command toggleAnimatedSlider('backup-prompt')
 * maps to showBackupNudge() (#56 grammar: sliders → c-sheet on the host).
 *
 * showBackupNudge({ host, illustration, onBackup, onDismiss, strings }) →
 *   the sheet element (already opened). "Back up now" → onBackup() + close —
 *   the host emits ixian:backup (audited legacy Home verb; bridge stays
 *   frozen). "Not now" / scrim / Esc → plain dismiss (onDismiss). CTA is
 *   one-shot latched.
 * illustration = optional img src (launch-shell grammar: decorative alt="",
 *   error → falls back to the tonal shield disc). Point it at the shared
 *   backup art (illustrations-plan #6, the SAME file the launch tail uses) —
 *   the nudge upgrades by FILE DROP, no component edit.
 * Copy defaults = the legacy en-us lang block (index-backup-prompt-*),
 * overridable via strings.backupNudge* (ships via the SL channel at i18n).
 */





function showBackupNudge({ host, illustration = '', onBackup, onDismiss, strings = getStrings() } = {}) {
  const content = document.createElement('div');
  content.className = 'c-backup-nudge';

  const disc = document.createElement('div');
  disc.className = 'c-backup-nudge__disc';
  disc.setAttribute('aria-hidden', 'true');
  disc.append(icon('shield-lock'));

  let art = null;
  if (illustration) {
    art = document.createElement('img');
    art.className = 'c-backup-nudge__illo';
    art.src = illustration;
    art.alt = '';                                // decorative — the copy carries meaning
    art.draggable = false;
    disc.hidden = true;                          // art leads; disc is the fallback
    art.addEventListener('error', () => { art.remove(); disc.hidden = false; }, { once: true });
  }

  const title = document.createElement('h3');
  title.className = 'c-backup-nudge__title t-heading-xs';
  title.textContent = strings.backupNudgeTitle || 'Don’t forget to back up';

  const body = document.createElement('p');
  body.className = 'c-backup-nudge__body t-body-sm';
  body.textContent = strings.backupNudgeBody
    || 'Spixi is fully decentralized — your data stays on your device only. '
    + 'To keep your contacts safe and restore everything later, create a backup now.';

  let used = false;                              // one-shot: CTA rides the latch
  const cta = createButton({ label: strings.backupNudgeCta || 'Back up now', size: 56, width: 'full' });
  cta.addEventListener('click', () => {
    if (used) return;
    used = true;
    closeSheet(sheet);
    try { if (onBackup) onBackup(); } catch { /* host emits ixian:backup */ }
  });

  const skip = createButton({ label: strings.backupNudgeSkip || 'Not now', type: 'text', size: 56, width: 'full' });
  skip.addEventListener('click', () => closeSheet(sheet));

  const note = document.createElement('p');
  note.className = 'c-backup-nudge__note t-body-xs';
  note.textContent = strings.backupNudgeNote
    || 'It’s recommended to back up every time you add a new contact.';

  if (art) content.append(art);
  content.append(disc, title, body, cta, skip, note);

  const sheet = createSheet({ content, host, onDismiss, strings });
  sheet.classList.add('c-backup-nudge__sheet');
  // the content is self-labelling (no c-sheet title row — legacy prompt look)
  sheet.setAttribute('aria-label', strings.backupNudgeTitle || 'Don’t forget to back up');
  openSheet(sheet);
  return sheet;
}

/* ---- src/components/rating-nudge.js ---- */
/**
 * c-rating-nudge — the "are you enjoying Spixi?" prompt (backup-nudge sibling).
 *
 * Legacy grounding (HomePage.xaml.cs:1438 checkForRating + index.html
 * #ratingModal): C# fires the `showRatingPrompt` command while
 * Preferences("rating_action") == "show" — i.e. it RE-PROMPTS until answered;
 * answering either way marks it "done" (HomePage.xaml.cs:348). Yes → store
 * review URL (per-platform, Config.cs:50–51) · No → support email — the
 * negative path deflects into support instead of a store review. Verbs
 * `ixian:rating:yes` / `ixian:rating:no` are EXISTING audited Home verbs
 * (HomePage.xaml.cs:325) — bridge stays frozen. All of that C# logic is
 * UNCHANGED; at integration `showRatingPrompt` maps to showRatingNudge().
 *
 * showRatingNudge({ host, onRate, onDismiss, strings }) → the sheet element
 *   (already opened). "Yes, I am loving it" (fill) → onRate('yes') + close ·
 *   "Not so much…" (outline) → onRate('no') + close — ONE latch across both.
 *   Scrim/Esc → plain dismiss, NO verb (C# re-prompts later — legacy parity;
 *   a sheet's light-dismiss IS the "not now" the legacy modal never had).
 * Copy defaults = the legacy en-us lang block (rating-request-*), overridable
 * via strings.rating* (SL channel at i18n).
 */





function showRatingNudge({ host, onRate, onDismiss, strings = getStrings() } = {}) {
  const content = document.createElement('div');
  content.className = 'c-rating-nudge';

  const disc = document.createElement('div');
  disc.className = 'c-rating-nudge__disc';
  disc.setAttribute('aria-hidden', 'true');
  disc.append(icon('logo'));                     // the brand mark asks (legacy spixirounded.svg)

  const title = document.createElement('h3');
  title.className = 'c-rating-nudge__title t-heading-xs';
  title.textContent = strings.ratingTitle || 'Are you enjoying Spixi?';

  const body = document.createElement('p');
  body.className = 'c-rating-nudge__body t-body-sm';
  body.textContent = strings.ratingBody || 'Your feedback helps us make it better.';

  let used = false;                              // ONE latch across both answers
  const answer = (a) => {
    if (used) return;
    used = true;
    closeSheet(sheet);
    try { if (onRate) onRate(a); } catch { /* host emits ixian:rating:<a> */ }
  };

  const yes = createButton({ label: strings.ratingYes || 'Yes, I am loving it', size: 56, width: 'full' });
  yes.addEventListener('click', () => answer('yes'));

  const no = createButton({ label: strings.ratingNo || 'Not so much…', type: 'outline', size: 56, width: 'full' });
  no.addEventListener('click', () => answer('no'));

  content.append(disc, title, body, yes, no);

  const sheet = createSheet({ content, host, onDismiss, strings });
  sheet.classList.add('c-rating-nudge__sheet');
  // self-labelling content (no c-sheet title row — nudge-family look)
  sheet.setAttribute('aria-label', strings.ratingTitle || 'Are you enjoying Spixi?');
  openSheet(sheet);
  return sheet;
}

/* ---- src/bridge/native.js ---- */
/**
 * native.js — the REAL-bridge transport core (Phase 3 item 2,
 * docs/native-bridge-spec.md). The demos' inline mocks are the behavioral
 * contract; this file is the thin adapter that carries the same shell
 * callbacks over the frozen MAUI bridge (ARCHITECTURE §2, bridge-audit-A/B).
 *
 * JS→C#: `location.href = "ixian:<command>[:<params>]"` — RAW legacy
 *   composition, no encoding (C# HttpUtility.UrlDecodes the whole URL; a
 *   pre-encode here would double-decode on some WebViews — mirror legacy,
 *   hazards stay §9 asks, the real fix is the §8 `ixian:secure` proposal).
 * C#→JS: C# injects `executeUiCommand(fnRef, 'b64', ...)` — bare page-global
 *   function references, every arg a Base64-encoded UTF-8 string.
 *
 * DELIBERATE divergences from legacy spixi.js (spec §2):
 *   1. NO escapeParameter() on decoded args — legacy HTML-escaped every arg
 *      because handlers concatenated innerHTML; our shells are textContent-
 *      only, so escaping would render literal `&amp;` to users.
 *   2. NO alert() on dispatch errors — fail soft to console.error (legacy
 *      alerted the stack trace at the user).
 *   3. ready() emits `ixian:onload` ONCE (latched). `ixian:ready:<shellId>`
 *      dual-emit is NOT sent until BE approves the §8 proposal — several C#
 *      handlers match with Contains, so unknown commands aren't provably inert.
 *
 * Capability handshake (#115 convention): C# injects generation-time config as
 * `window.SPIXI_ENV` (ARCHITECTURE §7); `SPIXI_ENV.capabilities` gates every
 * §8/§9 feature. Absent env / absent key = OFF — shells degrade gracefully,
 * so this file works against TODAY'S C# with zero changes.
 *
 * No component imports — pure transport. Page adapters (scan-page.js,
 * lock-page.js) compose shells with a bridge instance.
 */

/** Legacy base64ToBytes mirror (spixi.js:97): Base64 → UTF-8 string. */
function b64ToUtf8(b64) {
  const bin = atob(b64);
  return new TextDecoder().decode(Uint8Array.from(bin, (c) => c.codePointAt(0)));
}

/**
 * createNativeBridge({ emit, win })
 *   emit(command) — transport sink; default sets location.href (the real
 *     bridge). Injectable for tests and for the demos' mock layer.
 *   win — window to expose C#-callable globals on (default: window).
 * Returns { send, expose, exposeAll, ready, cap, capabilities }.
 */
function createNativeBridge({ emit, win } = {}) {
  const w = win || window;
  const sink = emit || ((command) => { w.location.href = command; });
  let readySent = false;

  const capabilities = (w.SPIXI_ENV && w.SPIXI_ENV.capabilities) || {};

  const bridge = {
    /** Emit a full raw command. Must carry the ixian: scheme — fail loud in dev. */
    send(command) {
      if (typeof command !== 'string' || !command.startsWith('ixian:')) {
        throw new TypeError('bridge.send expects a full "ixian:…" command, got: ' + command);
      }
      sink(command);
    },
    /** Define a C#-callable page global. fn receives DECODED (raw) strings. */
    expose(name, fn) {
      w[name] = fn;
      return fn;
    },
    exposeAll(map) {
      for (const name of Object.keys(map)) bridge.expose(name, map[name]);
    },
    /** Page-ready signal — ixian:onload, once (C# queues pushes until then). */
    ready() {
      if (readySent) return;
      readySent = true;
      bridge.send('ixian:onload');
    },
    cap(name) { return !!capabilities[name]; },
    capabilities,
  };
  return bridge;
}

/**
 * Define the executeUiCommand dispatcher C# injects calls against.
 * Divergences 1 + 2 (docblock) live here.
 */
function installExecuteUiCommand(win) {
  const w = win || window;
  w.executeUiCommand = function executeUiCommand(cmd) {
    const args = [];
    try {
      // C# sendUiCommand emits a bare `null` (unquoted) for null args
      // (Utils.cs:77) → the arg arrives as JS null, and atob(null) throws,
      // which previously dropped the WHOLE command (e.g. setBalance's nick is
      // null before the profile loads → the balance push vanished). Treat
      // null/undefined as an empty string so the rest of the args still deliver.
      for (let i = 1; i < arguments.length; i++) {
        const a = arguments[i];
        args.push(a == null ? '' : b64ToUtf8(a));
      }
      if (typeof cmd !== 'function') {
        // eslint-disable-next-line no-console
        console.error('executeUiCommand: not a function', cmd);
        return;
      }
      cmd.apply(null, args);
    } catch (e) {
      // fail soft — never alert, never rethrow into EvaluateJavaScriptAsync
      // eslint-disable-next-line no-console
      console.error('executeUiCommand dispatch failed', e);
    }
  };
  return w.executeUiCommand;
}

/* ---- src/bridge/scan-page.js ---- */
/**
 * scan-page.js — real-bridge adapter for the Scan shell (Phase 3 item 2;
 * FIRST C# repoint target, Damir 2026-07-06). Mirrors legacy scan.html
 * (bridge-audit-B.md §5): decode happens IN the WebView (html5-qrcode,
 * vendored at Resources/Raw/html/js/html5-qrcode.min.js), success emits
 * `ixian:qrresult:<text>` (C# allowScanning one-shot → pops the page → raises
 * scanSucceeded to the parent), cancel emits `ixian:back` (pop + GC.Collect).
 *
 * mountScanPage({ host, bridge, strings, camera })
 *   host    — mount target (default document.body)
 *   bridge  — createNativeBridge() instance (injectable for tests/demos)
 *   strings — SL dictionary (default window.SL — ARCHITECTURE §7)
 *   camera  — provider { start(feedEl, onText, ctrl), stop(), setTorch? } —
 *             default wraps the vendored Html5Qrcode global; null/absent
 *             library → permission CTA lands on 'denied' with honest copy
 *             (integration gap is visible, never silent — spec §4).
 * Returns { el, bridge } (tests introspect both).
 */



/** Default camera provider over the vendored html5-qrcode library. */
function html5QrcodeCamera(win) {
  const w = win || window;
  if (!w.Html5Qrcode) return null;
  let instance = null;
  return {
    start(feedEl, onText, ctrl) {
      if (!feedEl.id) feedEl.id = 'spixi-scan-feed'; // Html5Qrcode mounts by element id
      instance = new w.Html5Qrcode(feedEl.id, { formatsToSupport: [0] }); // 0 = QR_CODE
      instance
        .start({ facingMode: 'environment' }, { fps: 10 }, (decodedText) => onText(decodedText))
        .then(() => ctrl.done())
        .catch(() => ctrl.fail());               // permission denied / no camera
    },
    stop() {
      const inst = instance;
      instance = null;
      if (inst) { try { inst.stop().catch(() => {}); } catch { /* already stopped */ } }
    },
    setTorch(on, ctrl) {
      if (!instance) { ctrl.fail(); return; }
      instance.applyVideoConstraints({ advanced: [{ torch: on }] })
        .then(() => ctrl.done())
        .catch(() => ctrl.fail());               // unsupported track → button reverts
    },
  };
}

function mountScanPage({ host, bridge, strings, camera } = {}) {
  const br = bridge || createNativeBridge();
  const sl = strings || (typeof window !== 'undefined' && window.SL) || {};
  const cam = camera !== undefined ? camera : html5QrcodeCamera();
  let el = null;
  let finished = false;                          // decode/cancel are terminal (C# pops the page)

  const stopCamera = () => { if (cam) { try { cam.stop(); } catch { /* fail soft */ } } };

  el = createScanView({
    state: 'prompt',
    strings: sl,
    onRequestPermission(ctrl) {
      if (!cam) { ctrl.fail(); return; }         // library missing — visible, honest (spec §4)
      const feed = el.querySelector('.c-scan__feed');
      cam.start(feed, (text) => deliverScanResult(el, text), ctrl);
    },
    onDecode(text) {                             // one-shot upstream (scan-shell gate)
      if (finished) return;
      finished = true;
      stopCamera();
      br.send('ixian:qrresult:' + text);         // raw legacy composition — C# splits on the literal
    },
    onCancel() {
      if (finished) return;
      finished = true;
      stopCamera();
      br.send('ixian:back');                     // C# pops + GC.Collect()
    },
    // torch affordance only when the provider can drive it (capability-gated UI)
    onTorch: cam && cam.setTorch ? (on, ctrl) => cam.setTorch(on, ctrl) : undefined,
  });

  (host || document.body).append(el);
  br.ready();                                    // ixian:onload — C# flushes queued pushes
  return { el, bridge: br };
}

/* ---- src/bridge/lock-page.js ---- */
/**
 * lock-page.js — real-bridge adapters for the Lock shell (Phase 3 item 2).
 * Grammar (bridge-audit-A.md §11, bridge-audit-B.md §3 — FROZEN):
 *   lock.html      → ixian:unlock:<password> (raw, colons pass through — C#
 *                    Splits on the prefix) · ixian:change (confirm mode =
 *                    cancel/authSucceeded(false); lock mode = push LaunchPage)
 *                    · ixian:onload re-emit = biometric retry (LockPage.onLoad
 *                    relaunches Plugin.Fingerprint — §9 flag stands).
 *                    C#→JS: setJustConfirm("True") only.
 *   settings_encryption.html → ixian:changepass:<DELIM><old><DELIM><new> —
 *                    LEADING delimiter (settings_encryption.html:110; C# takes
 *                    split[1]/split[2], EncryptionPassword.xaml.cs:55). The
 *                    condensed ARCHITECTURE §3 line omits the leading DELIM —
 *                    audit-B + legacy source are the truth.
 *
 * No-callback mirrors (spec §5): C# answers wrong passwords with NATIVE alerts
 * only. The lock shell auto-releases itself (spec §3, 1600 ms). The encpass
 * screen has no component-side release, so THIS adapter supplies one: after
 * 1600 ms with no page-pop, ctrl.fail() restores the form with the inline
 * wrong-current copy — matching the alert C# just showed; on success C# popped
 * the page and nothing here matters. Future §9 `unlockFailed`/`changePassFailed`
 * pushes are pre-wired as exposed globals (inert until BE ships them).
 *
 * SPIXI_ENV.biometrics — generation-time env flag (one addCustomString in the
 * repoint PR); absent = false = button hidden (#115 graceful default).
 */



const RELEASE_MS = 1600;                         // lock-spec §3 window, mirrored for encpass

function mountLockPage({ host, bridge, strings, mode, biometrics } = {}) {
  const br = bridge || createNativeBridge();
  const sl = strings || (typeof window !== 'undefined' && window.SL) || {};
  const bio = biometrics !== undefined
    ? !!biometrics
    : !!(typeof window !== 'undefined' && window.SPIXI_ENV && window.SPIXI_ENV.biometrics);
  let unlockCtrl = null;                         // latest in-flight ctrl (§9 unlockFailed pre-wire)

  const el = createLockScreen({
    mode: mode || 'unlock',
    biometrics: bio,
    strings: sl,
    onUnlock(password, ctrl) {
      unlockCtrl = ctrl;
      br.send('ixian:unlock:' + password);       // raw — C# Splits on the prefix, verifyWallet decides
      // no ctrl.done(): wrong password = native alert only; the shell's own
      // 1600 ms auto-release restores the form (value kept). Success = C#
      // replaces the page mid-latch — exactly the legacy feel.
    },
    onBiometricRetry() {
      br.send('ixian:onload');                   // deliberate re-emit (bypasses ready-latch by design)
    },
    onUseAnotherWallet() { br.send('ixian:change'); },  // lock mode → LaunchPage
    onCancel() { br.send('ixian:change'); },            // confirm mode → authSucceeded(false)
  });

  br.exposeAll({
    // C# onload push (confirm mode): setJustConfirm("True")
    setJustConfirm(v) { setLockMode(el, String(v).toLowerCase() === 'true' ? 'confirm' : 'unlock'); },
    // §9 pre-wire — inert until BE ships an explicit wrong-password push
    unlockFailed(msg) { if (unlockCtrl) unlockCtrl.fail(msg); },
  });

  (host || document.body).append(el);
  br.ready();
  return { el, bridge: br };
}

function mountEncPassPage({ host, bridge, strings } = {}) {
  const br = bridge || createNativeBridge();
  const sl = strings || (typeof window !== 'undefined' && window.SL) || {};
  let passCtrl = null;

  const el = createEncPassScreen({
    strings: sl,
    onChangePassword(oldPass, newPass, ctrl) {
      passCtrl = ctrl;
      // LEADING delimiter — split[1]=old, split[2]=new (see docblock)
      br.send('ixian:changepass:' + ENC_DELIM + oldPass + ENC_DELIM + newPass);
      // encpass no-callback mirror: C# alerts + pops on success, alerts and
      // stays on a wrong current password — release the form to match.
      setTimeout(() => { if (passCtrl === ctrl) { passCtrl = null; ctrl.fail(); } }, RELEASE_MS);
    },
    onBack() { br.send('ixian:back'); },         // C# popPageAsync()
  });

  br.exposeAll({
    // §9 pre-wire — explicit failure push would beat the timer when it lands
    changePassFailed(msg) { if (passCtrl) { const c = passCtrl; passCtrl = null; c.fail(msg); } },
  });

  (host || document.body).append(el);
  br.ready();
  return { el, bridge: br };
}

